window.__D("text/torat-shmuel/c040",{"p":[[2000470156,"שניחר גרונם לגמרי הי'<sup data-n=\"718\">384</sup> בהם שנפלו בתאוות היתר, ומהם ג\"כ שנכשלו בתאוות איסור ג\"כ, ולכן בירר מהם מה שאפשר להעלות היינו האותיות דתאוות היתר, משא\"כ לבושי' דתאוות איסור א\"א להעלות כ\"א ע\"ד שאמרו בכלי חרס שבירתם זהו תקנתם<sup data-n=\"719\">385</sup> וא\"א להעלותם כלל, אך הלבושי' דתאוות היתר זה באפשר להעלות, והיינו כי ענין התאוה היא רק כח המתאוה לבד, אבל באמת אינו מוכרח כלל וכלל להתאוות אפי' תאוות היתר, וכ\"ש תאוות איסור, ובכח המתאוה הלזה יכול להיות בבחי' אהבה עזה לאלקות, ובזה יובן מ\"ש ואהבת כו' בכל לבבך וארז\"ל בשני יצריך, שלכאו' אינו מובן כל ענין אומרו ואהבת שהוא לשון ציווי<sup data-n=\"720\">386</sup> איך שייך על מדה שבלב לשון ציווי, גם אמרם ז\"ל בשני יצריך שגם היצה\"ר ישוב לאהבת ה' ואיך הוא זה, אלא שהגם על עצם האהבה אינו שייך ציווי מ\"מ הלא הולדת האהבה הוא מהתבוננות השכל שכאשר מתבונן בדבר הנאהב איך שטוב לפניו הוא הדבר ההוא אזי מתפעל לאהוב את הדבר שמחייב השכל, ולכן שכאשר יתבונן היטב בהתבוננות השכל איך שאני הוי' לא שניתי, ואתה הוא קודם שנבה\"ע<sup data-n=\"721\">387</sup> כו' והיינו מפני כי כלליות השתלשלו' העולמות הוא משם והארה בעלמא שאינו נוגע אל עצמותו כלל וכלל, ואי לזאת יתבונן נא היטב מה יחפוץ יותר אם מה שהוא הארה בעלמא או את עצם אוא\"ס אשר מהארתו נתהוה כל העולמות עליונים ותחתונים, וכאשר יעמיק היטב בהתבוננות זו אזי גם כח המתאוה של היצה\"ר מתאוה תאוה להיות בבחי' אהבה עזה לאלקות כאשר אוהב כל דברים הגשמיי' כשמתבונן שטוב לפניו וביתר שאת שהרי בכל הטוב שבעולמות לא נמצא טוב כמו עצם האלקות להיות כי כולם הם מהארה, ודעת לנבון נקל<sup data-n=\"722\">388</sup> שא\"א להשתוות הארה לעצם שכרחוק מזרח ממערב הם, ולפ\"ז יתורץ ב' דקדוקי' הנ\"ל שבפסוק ואהבת שהציווי הוא על ההתבוננות, ושגם היצה\"ר יכול לבוא לאהבת ה' כו', רק שבענין העלאת האותיות הנה &lt;25&gt;\nּ אותיות דתאוות היתר אפשר להעלותם, מפני שלא נפגמו כ\"כ, אבל האותיות דתאוות איסור א\"א להעלותם כלל וכלל, כ\"א לדחותם וכענין שאמרו בכלי חרס שבירתם זהו תקנתם, וכמו שענין שבירת הכלי הוא עד שאינו ראוי' לתשמיש הקדום<sup data-n=\"723\">389</sup> כנודע, כן שבירת מח' ותאוות איסור הוא ביטולם לגמרי כמ\"ש ולא תתורו אחרי לבבכם<sup data-n=\"724\">390</sup> ואחרי עיניכם שעינא וליבא תרין סרסורין דחטאה<sup data-n=\"725\">391</sup> כ\"א לדחותם מכל וכל וזהו העלאתן כו', אבל אותיות דתאוות היתר מתעלים האותיות בדרך קירוב ע\"י שנעשים אותיות והסבר בעבודת ה'",[["718","384","<b>הי'</b>: בהמשך הנדפס ליתא."],["719","385","<b>בכלי חרס שבירתם זהו תקנתם</b>: ראה כלים פ\"ב, מ\"א."],["720","386","<b>ואהבת שהוא לשון ציווי</b>: ראה גם סהמ\"צ להצ\"צ ע' קצט. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה תעשה לי ובהערה 128."],["721","387","<b>ואתה הוא קודם שנבה\"ע</b>: ראה תפלת השחר. של\"ה תולדות אדם ג, ב. מאמרי אדה\"ז על מארז\"ל ע' שלו."],["722","388","<b>ודעת לנבון נקל</b>: משלי יד, ו."],["723","389","<b>שבירת הכלי. . לתשמיש הקדום</b>: בכלי חרס ראה רמב\"ם הל' כלים רפי\"ט."],["724","390","<b>ולא תתורו אחרי לבבכם</b>: שלח טו, לט."],["725","391","<b>שעינא וליבא תרין סרסורין דחטאה</b>: ראה ירושלמי ברכות פ\"א, ה\"ה. ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370243\" data-slug=\"torah-or\" data-id=\"3901370243\">תו\"א שמות נד, סע\"ג</a> ואילך. מאמרי אדה\"א שמות ח\"א ע' כ."]]],[2000470157,"שנעשים לבושי' להעלות בהם קירוב ודביקות לה' שעי\"ז גם הם מתדבקי' כו', וזהו שא' ביעקב ויקח מאבני המקום, וישם אותה מצבה<sup data-n=\"726\">392</sup> לשון יחיד שנעשה אבן א' לרמז על בחי' הביטול דחכ', ויצוק שמן הוא אור החכ' על ראשה הוא כלי החכ', כמו שהשכל שבראש הוא כלי לאור ההשכלה כו', וע\"ד שא' והאבן הזאת, שנודע שלשון זאת רומז על המקבל<sup data-n=\"727\">393</sup>, והיינו שא' שהעלה כ\"כ האותיות בבחי' הביטול עד שאין להם דבר בפ\"ע כ\"א שהם מקבלים לבד, שענין המקבל הוא היותו בטל להמשפיע כו', וזהו שרש ענין אבן בוחן שבוחן האדם ע\"י שמפתהו תחלה בהתלבשות האותית בתאוות, וכשמתגבר על יצרו המסיתו הרי ע\"י אבן זה נבחן האדם ולכן נעשה מזה אבן ישראל, וכמ\"ש משם רועה אבן ישראל<sup data-n=\"728\">394</sup> שקאי על בחי' החוזק שיש בנש\"י להיות בבחי' קשה עורף שלמעלה גם מהבנת השכל, רק שתחלה צריכים להגיע בבחי' השכל כל כמה שאפשר, ואז יכול לבוא גם לבחי' הביטול שלמעלה מהשכל<sup data-n=\"729\">395</sup> שנת' ענינו במ\"א כו', ונק' ג\"כ אבן השתי' שממנה הושתת העולם שאבא יסד ברתא<sup data-n=\"730\">396</sup>, וגם ממנה הושתת העולם שע\"י הבירור הנ\"ל מתעלים כל העולמות, וכמ\"ש גם את העולם נתן בלבם<sup data-n=\"731\">397</sup> שע\"י הבירור בלב האדם עי\"ז תלוי כל עליות והמשכות אלקות בעולמות כו'.\n<b>ועפ\"ז</b><sup data-n=\"732\">398</sup> יש לפרש מ\"ש מזבח אדמה תעשה לי<sup data-n=\"733\">399</sup> כו' ואם מזבח אבנים כו' לא תבנה אתהן גזית<sup data-n=\"734\">400</sup>, מפני מה במזבח אבנים הטיל תנאי שלא יבנה גזית<sup data-n=\"735\">401</sup>, אלא שפי' מזבח אדמה קאי על העלאת האדם עצמו, וכמארז\"ל למה נק' שמו אדם שנברא מן האדמה<sup data-n=\"736\">402</sup>, ואמרו שממקום כפרתו היינו מקום הזבח<sup data-n=\"737\">404</sup> נברא<sup data-n=\"738\">403</sup>, וזהו עיקר המזבח שעליו יקריב האדם מכם<sup data-n=\"739\">405</sup> להיות רוח האדם עולה<sup data-n=\"740\">406</sup>,",[["726","392","<b>מצבה</b>: ניתוסף בפנים ע\"פ המשך הנדפס."],["727","393","<b>זאת. . מקבל</b>: ראה מאו\"א מערכת זאת ס\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380109\" data-slug=\"likkutei-torah\" data-id=\"4001380109\">לקו\"ת צו ח, ב</a>. וראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 139."],["728","394","<b>משם רועה אבן ישראל</b>: ויחי מט, כד."],["729","395","<b>הביטול שלמעלה מהשכל</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380057\" data-slug=\"likkutei-torah\" data-id=\"4001380057\">לקו\"ת פקודי ד, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">פ' ראה יח, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380835\" data-slug=\"likkutei-torah\" data-id=\"4001380835\">כט, ד</a>. סה\"מ תרכ\"ז ס\"ע עד ואילך. ס\"ע רכו ואילך. תרל\"ח ע' קנ ואילך. ובהנסמן בהנ\"ל."],["730","396","<b>שאבא יסד ברתא</b>: ראה זהר רע\"מ פינחס רנו, ב. רמח, א. רנח, א. אגה\"ק ס\"ה. מאמרי אדה\"א דברים ח\"ב ע' שפ הערה ד\"ה מצירופי. קונטרסים ס\"ע תקמז ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540846\" data-slug=\"torat-chaim\" data-id=\"2300540846\">תו\"ח שמות ח\"א יב, א</a>."],["731","397","<b>גם את העולם נתן בלבם</b>: קהלת ג, יא. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380329\" data-slug=\"likkutei-torah\" data-id=\"4001380329\">לקו\"ת במדבר ה, ב</a>. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקעט. ע' תרמ. אוה\"ת בלק ע' תתקמ. וראה גם לקמן מאמר ד\"ה ואמנם כו' חולה בסופו."],["732","398","<b>ועפ\"ז</b>: פיסקא זו נרשמה בצד הימין של הגליון מלמעלמ\"ט וכנראה שניתוספה אח\"כ."],["733","399","<b>מזבח אדמה תעשה לי</b>: יתרו כ, כא."],["734","400","<b>ואם מזבח אבנים. . גזית</b>: יתרו שם, כב."],["735","401","<b>מפני מה. . גזית</b>: בהמשך הנדפס ליתא. ואולי נשמט מפני תיבות הדומות: גזית. . גזית."],["736","402","<b>למה נק' שמו אדם. . האדמה</b>: וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830234\" data-slug=\"or-hatorah-hb\" data-id=\"8158830234\">אוה\"ת בלק ע' תתקכ</a>. ראה תנחומא צו יד. וראה גם ב\"ר פי\"ז, ד הובא באוה\"ת שם ע' תתקלב."],["737","404","<b>הזבח</b>: בהמשך הנדפס: המזבח."],["738","403","<b>שממקום כפרתו. . נברא</b>: ראה ב\"ר פי\"ד, ח. ירושלמי נזיר פ\"ז, ה\"ב. רש\"י בראשית ב, ז. רמב\"ם הל' ביהב\"ח פ\"ב, ה\"ב."],["739","405","<b>יקריב האדם מכם</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמוכים לעד על יד הערה 39. סה\"מ תרכ\"ט ע' קכז. וש\"נ."],["740","406","<b>רוח האדם עולה</b>: ראה קהלת ג, כא."]]],[2000470158,"אבל אם נכשל בתאוות הן היתר והן ת\"א לזה אמר ואם מזבח אבנים להעלות האותיות תעשה לי, לא תבנה אתהן גזית קאי על האותיות דת\"א שלא די במה שתשבר קצתן כ\"א שזה צריך לשבר לגמרי מכל וכל, גם קאי על תאוות היתר שלא תבנה אתהן גזית שתפרר קצתן מהן וא\"כ יהי' ריבוי אבנים ובאמת העלאתן כשהם נעשים אחד כנ\"ל באבני יעקב, והטעם לזה כי חרבך הנפת<sup data-n=\"741\">407</sup> שהוא בחי' חרב אוכלת<sup data-n=\"742\">408</sup>, אשר עי\"ז ותחללה<sup data-n=\"743\">409</sup> היפך מ\"ש ולא תחללו את שם קדשי שמאחר שקצתם נשארו בבחי' הפירוד &lt;26&gt;\nּ הרי אין מקום שם להשראת הקדושה והרי הוא עושה חלל<sup data-n=\"744\">410</sup>, ולכן להיות כי ותחללה ע\"י הנפת החרב לכן אינו ראוי למזבח, וזהו שבמזבח אבנים דוקא הטיל התנאי כו'.\n<b></b>קיצור. שכמו בהחולה יש ג' בחי' כן בלבוש מחו\"ד יש ג\"כ ג' בחי' מח\"ז והרהור תאוות היתר<sup data-n=\"745\">411</sup> והרהורי עבירה, ועז\"נ ויקח מאבני ולא כל אבני היינו תאוות היתר לבד, ות\"א צריכים לדחות אותם מכל וכל, ולא תתורו, וה\"ז אבן בוחן, ועי\"ז נעשה אבן ישראל, י\"ל עוד שישראל הם העושים אותו לאבן שישרה בחי' א' בשם ב\"ן זה שבאותיות אלו, וגם אבן שתי' אבא יסד ברתא, וגם את העולם נתן בלבם כו'.",[["741","407","<b>כי חרבך הנפת</b>: המשך הכתוב ואם מזבח אבנים."],["742","408","<b>חרב אוכלת</b>: ע\"פ האזינו לב, מב."],["743","409","<b>ותחללה</b>: סיום הכתוב ואם מזבח אבנים."],["744","410","<b>ולא תחללו את שם קדשי. . חלל</b>: אמור כב, לב. ראה מאמר ד\"ה זה במאמרי אדה\"ז תקס\"ב ח\"ב ע' שפו ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380056\" data-slug=\"likkutei-torah\" data-id=\"4001380056\">לקו\"ת פקודי ד, א</a>. (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550219\" data-slug=\"torat-chaim\" data-id=\"2300550219\">הובא לקמן ב</a>) המשך מצה זו ספ\"מ על יד הערה 1276. (בחלק ההנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 149. תו\"ח תצוה ח\"ב שנז, ב. וש\"נ."],["745","411","<b>והרהור תאוות היתר</b>: בהמשך הנדפס: והרהורי היתר."]]],[2000470159,"<h3>ועפ\"ז כו' ותהי להם הלבנה</h3>\n<b>בס\"ד פ' משפטים</b>\n(יז) <b>ועפ\"ז</b> יובן גודל ענין חטא דדור הפלגה עד שגדלה חטאתם כ\"כ שלא ניתן למחול להם שהרי אין עומדין בדין הגדול ואין להם חלק לעוה\"ב, שביאר לנו הכתוב חטאתם במ\"ש ותהי להם הלבינה<sup data-n=\"746\">412</sup> לאבן, שבחרו הלבינה שהיא מל' דנוגה במקום האבן מל'<sup data-n=\"747\">413</sup> דקדושה, והיינו מ\"ש ושפחה כי תירש גבירתה<sup data-n=\"748\">414</sup>, ורצו להרוס בנין הקדושה ולהגביר הסט\"א, אך איך יומשך להם",[["746","412","<b>ועפ\"ז. . ותהי להם הלבינה</b>: מאמר זה הוא מאמר הז' מההמשך וכולל פרקים יז-יט.\nמאמר זה מיוסד על מאמר ד\"ה וידבר וגו' וארא וגו' שנדפס באוה\"ת וארא כרך ז ריש ע' ב'תקסח ואילך בשינויים ובהוספות."],["747","413","<b>האבן מל'</b>: ראה פרדס שער עה\"כ שכ\"ג, פ\"א מערכת אבן. ע\"ח שער ז\"א שי\"ז, פ\"ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381126\" data-slug=\"likkutei-torah\" data-id=\"4001381126\">לקו\"ת ברכה צט, ד</a>."],["748","414","<b>ושפחה כי תירש גבירתה</b>: ע\"פ משלי ל, כג. הובא בפרדס שבהערה 323. באוה\"ת כאן ניתוסף: שנת' בזהר פ' אחרי דס\"ט ע\"א. מכאן ואילך הוא לשון האוה\"ת בשינויים ובהוספות."]]],[2000470160,"אור וחיות מהקדושה לבחי' זו זהו ע\"י שיומשכו אותיות להאיר בבחי' מקיף לבד ולא בבחי' או\"פ כמו בקדושה שאם יאיר בפנימי' ה\"ז כמו בחי' גדול הוי' שבעיר אלקינו שהאור מאיר בפנימיות וממילא נמשך היראה והביטול והם לא רצו בזה כלל כ\"א לעמוד מרחוק מהקב\"ה ואעפ\"כ יומשך להם כל טוב, והיינו ע\"י אותיות המחי' בבחי' מקיף ואינו מאיר בפנימיות, ולהבין איך הוא האור המאיר בבחי' מקיף לבד יובן מענין הלבונה שהי' בי\"א סממני<sup data-n=\"749\">415</sup> הקטרת<sup data-n=\"750\">416</sup>, שנת' מזה בת\"א פ' תולדות ד\"ה ראה ריח בני<sup data-n=\"751\">417</sup> גבי אך כיצד הם חיים וקיימים מהקדושה<sup data-n=\"752\">418</sup> מאחר שהחיות נבלע בתוכם הנה זהו ענין לבונה שבי\"א סממני הקטרת שהוא אור המקיף עליהם מלמעלה ואינו נבלע בתוכם<sup data-n=\"753\">419</sup>, ובחי' לבונה הוא המחבר ע\"ס דקדושה להאיר לע\"ס דמסאבותא, ע\"ש. וע' מזה בפע\"ח שער עולם העשייה פ\"ד, ושער הקדישים פ\"ד, ובלק\"ת שה\"ש בד\"ה ביאור הדברים ע\"פ שחורה אני ונאוה ושם פ\"ה<sup data-n=\"754\">420</sup> מענין כאהלי קדר, ובמאו\"א אות למ\"ד סעי' ח' לבונה זכה נק' אור המקיף בקליפות ואור המקיף זך מן הפנימים עכ\"ל, ואפשר שנק' זכה ע\"ש ז\"ך אותיות שהרי זהו האותיות הנמשכי' להחיות הקליפות בבחי' מקיף א\"כ יש בו כל הך\"ז אותיות והם עדיין זכים כי אינם מעורבי' בסט' דמסאבותא, וכמ\"ש בע\"ח שער יו\"ד בסופו בפי\"א<sup data-n=\"755\">421</sup> שהוא ע\"ד שאין הקדש מתערב בחול, אך עומד על ראשם ומשם מאיר להם עכ\"ל, הרי שנק' קדש, וע\"כ נק' זכה, ויובן ענין ההארה שבבחי' מקיף לסט' דמסאבותא ע\"ד מ\"ש טהור עינים מראות ברע<sup data-n=\"756\">422</sup> והרי יודע מה שבחשיכה<sup data-n=\"757\">423</sup> אלו מעשה הרשעים במד\"ר ר\"פ בראשית<sup data-n=\"758\">424</sup>, ובפ' נשא רפ\"ט ע\"פ והי' במחשך מעשיהם<sup data-n=\"759\">425</sup> ויאמרו מי רואנו כו'\n&lt;27&gt;\nּ משל לארכיקוטין<sup data-n=\"760\">426</sup> כו' יעו\"ש, אלא שידיעה זו היא בבחי' מקיף עליהם, וכמו שהידיעה אינה מכרחת ומבטלת הבחירה, וע' בסש\"ב פמ\"ח<sup data-n=\"761\">427</sup> ובת\"א בד\"ה הן האדם הי' כאחד ממנו, בענין והייתם כאלקי' יודעי טו\"ר<sup data-n=\"762\">428</sup>, וזהו שאמרו ונעשה לנו שם<sup data-n=\"763\">429</sup>",[["749","415","<b>הלבונה שהי' בי\"א סממני הקטרת</b>: תשא ל, לד."],["750","416","<b>בי\"א סממני הקטרת</b>: ראה תשא שם. כריתות ו, א."],["751","417","<b>בת\"א פ' תולדות. . בני</b>: כ, רע\"ג [בדילוג]. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ולהבין וכו' מזבח הפנימי על יד הערה 29 ואילך."],["752","418","<b>מהקדושה</b>: וכ\"ה באוה\"ת כאן ובתו\"א: מקדושה."],["753","419","<b>בתוכם</b>: באוה\"ת ניתוסף: כו'."],["754","420","<b>ובלק\"ת שה\"ש. . פ\"ה</b>: י, א ואילך."],["755","421","<b>בע\"ח שער יו\"ד בסופו בפי\"א</b>: במהדורת שקלאב תק\"ס<sup data-n=\"e49\">א</sup>. בהמשך הנדפס: בפי\"ד. וצ\"ל כבפנים. בדפו\"א שער המלכים שי\"א, פ\"י."],["756","422","<b>טהור עינים מראות ברע</b>: חבקוק א, יג [ושם: רע — ראה מנחת שי שם. מאמרי אדה\"א בראשית ע' צו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540736\" data-slug=\"torat-chaim\" data-id=\"2300540736\">תו\"ח בא ח\"א קכג, ד</a>. וש\"נ]."],["757","423","<b>שבחשיכה</b>: וכ\"ה באוה\"ת כאן. בהמשך הנדפס ובמדרש: (ש)בחשוכא. דניאל ב, כב."],["758","424","<b>ר\"פ בראשית</b>: פ\"א, ו (בשינוי קל)."],["759","425","<b>והי' במחשך מעשיהם</b>: ישעי' כט, טו."],["760","426","<b>לארכיקוטין</b>: במדרש: לארכיקיטין."],["761","427","<b>פמ\"ח</b>: וכ\"ה באוה\"ת כאן. בהמשך הנדפס: פי\"ח — וצ\"ל כבפנים."],["762","428","<b>ובת\"א. . טו\"ר</b>: בראשית ו, א."],["763","429","<b>ונעשה לנו שם</b>: נח יא, ד. ראה לקו\"ת להאריז\"ל ס\"פ נח (ד\"ה מהרח\"ו ז\"ל). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560381\" data-slug=\"or-hatorah-hb\" data-id=\"8316560381\">אוה\"ת נח כרך ג ע' תרנז</a>. ע' תרסג. כרך ו ע' 2132 ואילך. וארא כרך ז ע' ב'תקנב-ג. סה\"מ תרמ\"ג ע' ז.\n\n<b>א</b>  <b>מובא גם בסה\"מ תרל\"ג ח\"א ע' קנו. המשך תער\"ב ח\"א ע' תכז ושם</b>: בע\"ח שער יו\"ד הוא שער המלכים פי\"א."]]],[2000470161,"כמו עד\"מ ענין השמות וקבלה מעשיות שהי' ידוע בדורות הראשונים כמו שפרש\"י ז\"ל באיכה סי' ב' ב' ע\"פ חלל ממלכה ושרי' והוא מבואר במד\"ר שם ע\"פ זה<sup data-n=\"764\">430</sup>, והיינו שהמזכיר השם או הכותבו בקמיע אינו יודע כלל מה הוא, א\"כ אין זה אלא בחי' מקיף עליו, ואעפ\"כ היו פועלים עי\"ז פעולות נפלאות וכמו שפרש\"י ביבמות פט\"ו דקי\"ו א' א\"נ בקפיצה אזל<sup data-n=\"765\">431</sup> שפרש\"י ע\"י שם וע' בתוספת<sup data-n=\"766\">432</sup> פרק עשרה יוחסין דע\"ג א' מ\"ש בשם בה\"ג<sup data-n=\"767\">433</sup>.\n<b>ויובן</b> עוד ענין הנ\"ל עד\"מ ההשפעה שע\"י אותיות שיש בזה או\"פ ואו\"מ, והיינו כשהתלמיד מבין השכל המלובש בהאותית זהו הנק' או\"פ, אבל כשאינו מבין השכל רק יכול לומר האותיות לבד ה\"ז נק' בחי' מקיף עליו<sup data-n=\"768\">434</sup>, וע' בלק\"ת בביאור ע\"פ את שבתותי תשמרו<sup data-n=\"769\">435</sup>, ובתוס' ללקו\"ת בד\"ה להבין מ\"ש באוצ\"ח<sup data-n=\"770\">436</sup> שז\"ע הצמצום שהי' באוא\"ס ונשאר רשימו שהו\"ע האותיות רל\"א שערים<sup data-n=\"771\">437</sup> המתגלגלי' פנים ואחור, שהאור שבהם אינו מושג, וכמו ע\"ה שעולה לתורה<sup data-n=\"772\">438</sup> כשמבין האותיות והתיבות ומברך עליהן אע\"פ שאינו מבין פירושם, וע' בסש\"ב פ\"ה בענין מקיף ומוקף, שגם בתלמיד המבין השכל בטוב טרם הבנתו על בוריו, שנעשה שכל התלמיד מוקף מהשכל, ואח\"כ כשמבין אותו בטוב נעשה שכלו מקיף להשכל נמצא גם באו\"פ עצמו יש מקיף ופנימי שז\"ע בחי' מקיף ומוקף כו', אלא שזהו באו\"פ, כמ\"כ נבין בחי' מקיף דאו\"מ ג\"כ כו'<sup data-n=\"773\">439</sup>, ועד\"ז יובן ענין לבונה זכה בחי' אותיות דקדושה המחיים את הקליפות בבחי' מקיף, וזה הי' כוונת דור הפלגה שבנו העיר והמגדל להגדיל כח הקלי'<sup data-n=\"774\">440</sup> וסט\"א ע\"י המשכת האותיות בבחי' מקיף, וזהו כענין שאה\"כ שלום יהי' לי<sup data-n=\"775\">441</sup> כי בשרירות לבי אלך למען ספות כו', וע\"ד שנת' באגה\"ת ספ\"ו בענין אין בידינו לא משלוות הרשעים, ולכן שעבוד מצרים הי' בכדי לתקן חטא דור הפלגה, וא\"כ אין מקום לטענת משה, וע\"ז אמרו<sup data-n=\"776\">442</sup> כי מה האדם<sup data-n=\"777\">443</sup> שיבא אחר המלך את אשר כבר עשהו שהן עצמן היו גלגול דור הפלגה שהודה משה<sup data-n=\"778\">444</sup> שדין אמת הי', שהן עצמן המשיכו על עצמן בחי' לבינה כענין זקף לבינה כו' ותייסרך רעתך<sup data-n=\"779\">445</sup> כו'<sup data-n=\"780\">446</sup>.",[["764","430","<b>במד\"ר. . זה</b>: איכ\"ר ב, ה."],["765","431","<b>אזל</b>: וכ\"ה באוה\"ת כאן. בגמ' הובאה תיבה זו בתירוץ שלפנ\"ז."],["766","432","<b>בתוספת</b>: ד\"ה מאי איכא."],["767","433","<b>מ\"ש בשם בה\"ג</b>: וכ\"ה באוה\"ת כאן. הבה\"ג צויין עה\"ג שם."],["768","434","<b>עליו</b>: וכ\"ה באוה\"ת כאן. ובהמשך הנדפס: לבד."],["769","435","<b>בלק\"ת. . תשמרו</b>: בהר מג, ב ואילך."],["770","436","<b>ובתוס' ללק\"ת. . באוצ\"ח</b>: הוספות לויקרא נב, ד ואילך."],["771","437","<b>רל\"א שערים</b>: ראה לקמן המשך מצה זו הערה 298."],["772","438","<b>ע\"ה שעולה לתורה</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, סהי\"ב. וש\"נ. מאמרי אדה\"א דברים ח\"ג ע' תשעט. וש\"נ. שע\"ת לט, ב ובהערה 18."],["773","439","<b>וע' בסש\"ב. . כו'</b>: כ\"ז ליתא באוה\"ת כאן. ובמקומו בא ציון לפרדס וללקו\"ת."],["774","440","<b>הקלי'</b>: וכ\"ה באוה\"ת כאן. בהמשך הנדפס: האלקי'. וצ\"ל כבפנים."],["775","441","<b>שלום יהי' לי</b>: נצבים כט, יא."],["776","442","<b>וע\"ז אמרו</b>: שמו\"ר ר\"פ וארא."],["777","443","<b>כי מה האדם</b>: קהלת ב, יב."],["778","444","<b>שהודה משה</b>: לעיל פי\"ד ובהערה 290."],["779","445","<b>ותייסרך רעתך</b>: ירמי' ב, יט."],["780","446","<b>כו'</b>: ניתוסף בפנים ע\"פ המשך הנדפס."]]],[2000470162,"<b></b>קיצור. שבנ\"י שבגלות מצרים הי'<sup data-n=\"781\">447</sup> גלגול דור הפלגה, ותהי להם הלבינה תמורת האבן והיינו שרצו להמשיך חיות מאותיות שבבחי' מקיף לבד כו' והו\"ע לבינה כו', ע\"ד השבעת השמות, וא\"כ אין מקום לשאלת משה שזהו הם עצמן והוא<sup data-n=\"782\">448</sup> בשביל שיתקנו.\n(יח) <b>והנה</b> ענין התיקון שלהם הי' ע\"י וימררו את חייהם בחומר ובלבנים<sup data-n=\"783\">449</sup> דהיינו ביטוש הגוף, ומבואר בזח\"ג שלח דקס\"ח א' שע\"י ביטוש הגוף כדין נהיר נהירא<sup data-n=\"784\">450</sup> &lt;28&gt;\nּ דנשמתא ואתאחדא בגופא, ויובן זה ע\"פ משנ\"ת במ\"א במעלת ענין שמאל דוחה<sup data-n=\"785\">451</sup> שיש בה<sup data-n=\"786\">452</sup> יתרון על בחי' ימין המקרבת, דהנה בענין העלי' יש מי שכחו רב ועצום לעלות בעילוי אחר עילוי בלתי שום סיוע כ\"א כחו העצמי, בבחי' התורה והעבודה וקבלת עומ\"ש הם המסייעים עלייתו בעילוי אחר עילוי<sup data-n=\"787\">453</sup> כו', ואמנם מי שאין לו כח רב כ\"כ לעלות בעצמו בעילוי אחר עילוי וכמ\"ש מי יעלה בהר ה'<sup data-n=\"788\">454</sup> נקי כפים ובר לבב<sup data-n=\"789\">455</sup> כו', שחשיב הרבה דברים שצריכים להיות יכול לעלות בהר ה' שז\"ע העליות בעילוי אחר עילוי שזהו כמשל העולה בהר שמתעלה ומתנשא מהאדם העומד בתחתיות ההר הנה הוא צריך לסיוע שיסייע לו בעליותו בהר ה', וז\"ע בחי' ימין המקרבת שמקרב החלוש בכחות וא\"י לעלות שעכ\"ז כאשר יומשך לו כח מן המשפיע יתעוררו כחותיו העצמיי' לעלות בהר ה', כמו שמעשים הטובים דנקי כפים ובר לבב הם המסייעים האדם העושה אותם, כן הארת בחי' ימין המקרבת נותנת כח שיוכל לעלות גם מי שבעצם אין כחו רב ועצום לעלות בהר, וכמו אדם החובק את חבירו בידו הימנית ומסייעו להלוך ולעלות למעלה מעלה, אך הנה בחי' ימין מקרבת הוא מקרב אדם הראוי לקרבו כמו מי שהוא לומד ועושה מצות, אלא שכחותיו חלושים ובעבודתו העצמי' אין כחו גדול כ\"כ שיעלה במעלות בעילוי אחר עילוי הנה לזה יומשך בחי' ימין המקרבת הנ\"ל, אמנם מי שנפל במדרגה עד שמה שהי' ביכולתו לעשות לא<sup data-n=\"790\">456</sup> עשה ג\"כ ונמצא הוא עצמו איבד כחותיו וירד עשר מעלות אחורנית, וכמ\"ש והיתה נפש אדוני צרורה<sup data-n=\"791\">457</sup> בצרור החיים את ה' אלקיך, שזהו עילוי שאין למעלה הימנו, ואת נפש אויביך היינו מי שלא עבד את ה', ועסק כל ימיו בתענוגי' גשמיים המאבדים את האדם מב' עולמות, שהרי איש שהוא מעונג רב גם עסקיו הגשמיים בלתי מסודרים כלל שהרי אינו עושה בהם כלל כ\"א הוא תמיד רודף אחרי תענוגיו המדומים שטובים הם, וכ\"ש עוה\"ב במה יזכה נער כזה את ארחו<sup data-n=\"792\">458</sup>, וזהו",[["781","447","<b>הי'</b>: וכ\"ה באוה\"ת כאן. ובהמשך הנדפס: היו."],["782","448","<b>והוא</b>: בהמשך הנדפס: והיינו."],["783","449","<b>וימררו. . ובלבנים</b>: שמות א, יד [בדילוג]."],["784","450","<b>נהירא</b>: בהמשך הנדפס: נהורא. באוה\"ת ובזהר: נהירו."],["785","451","<b>שמאל דוחה</b>: סוטה מז, א. ראה גם ביאוה\"ז קרח צה, ג ואילך."],["786","452","<b>בה</b>: בהמשך הנדפס ליתא."],["787","453","<b>בלתי שום. . עילוי</b>: בהמשך הנדפס ליתא. ואולי נשמט מפני תיבות הדומות: עילוי. . עילוי."],["788","454","<b>מי יעלה בהר ה'</b>: תהלים כד, ג."],["789","455","<b>נקי כפים ובר לבב</b>: שם כד, ד."],["790","456","<b>לא</b>: בהמשך הנדפס: ולא."],["791","457","<b>והיתה נפש אדוני צרורה</b>: שמואל-א כה, כט."],["792","458","<b>במה יזכה נער. . את ארחו</b>: תהלים קיט, ט."]]],[2000470163,"ששפטו הכתוב ואת נפש אויביך יקלענה בתוך כו' שהיא הקליעה למרחוק מאד כו', ועכ\"ז גם לאדם כזה יש תקוה טובה אחריתו, ואל יאמר נואש, והיינו ע\"י בחי' הגבורות דשמאל דוחה שמזיזים אותו ממקומו לבלי ירד מטה וגם על מקומו לא יעמוד ונאספי' כחות חדשים ואשר בהעלם יצאו אל הגילוי מכח אל הפועל עד שיזוז ממקומו להתחיל לעלות, ואז יומשך עליו חוט של חסד מבחי' החסדי' דימין מקרבת לקרב הרחוקים שיעלו במעלות כו', וזהו מאמר רב מתיבתא אעא<sup data-n=\"793\">459</sup> דלא שליט בה נורא מבטשים אותו, שע\"י הביטוש שמבטשין אותה מזיזים אותה ממקומה שישלוט בה האש בטוב, כי בהיותה על מקומה לא הי' ביכולת האש לשלוט בה כלל, וע\"י הביטוש שנער מעליה הנבערת והזיזה ממקומה עי\"ז יש כח באש לשלוט בה<sup data-n=\"794\">460</sup>, כך גופא דלא סליק ביה נהורא דנשמתא שמצד גשם וגסות הגוף ורצונותיו בתאוות גשמיי' וכנ\"ל<sup data-n=\"795\">461</sup> בענין הג' מיני חולאים, והרהוריהם, הנה ירדה נפשו עשר מעלות אחורנית, לכן ע\"י ביטוש הגוף והכנעת החומר עי\"ז ניזז ממקומו &lt;29&gt;\nּ עד שיאיר עליו אור החסדים דבחי' ימינו תחבקני<sup data-n=\"796\">462</sup> לחבקו ולהעלותו בעילוי אחר עילוי כו', וזהו שמאלו תחת לראשי<sup data-n=\"797\">463</sup> שבכדי שגם הרחוק יוכל להתעלות במעלות הנה זהו ע\"י שמאלו בחי' שמאל דוחה דוקא שעי\"ז ניזוז ממקומו, ואז ע\"י התקרבות דבחי' ימינו תחבקני בא לבחי' תחת לראשי כו'.\n<b></b>קיצור. שהתיקון שלהם הי' ע\"י<sup data-n=\"798\">464</sup> ביטוש הגוף, ע\"ד אעא דלא שליט בה<sup data-n=\"799\">465</sup> כו' מבטשין לי', וכמו מי שא\"י להעלות ע\"י בחי' ימין מקרבת יתעלה, אמנם המרוחק ביותר אינו פועל לו בחי' הקירוב כ\"א דוקא ע\"י בחי' הביטוש שמבטשין אותו עי\"ז מתקרב כו'.\n(יט) <b>ויובן</b> עוד ענין תיקון והלבשת הנפש בגוף להאיר אורה ע\"י ביטוש הגוף, לפי ששרש נה\"א הוא מבחי' התיקון<sup data-n=\"800\">466</sup> דשם מ\"ה, ושרש נה\"ב והגוף הוא מבחי' זמ\"ל קדמאין<sup data-n=\"801\">468</sup> דבחי' התהו<sup data-n=\"802\">467</sup> שקדם לתיקון<sup data-n=\"803\">469</sup>, כי מה שנברר תחלה מבחי' התהו היינו ממה שנפל בשבירה היותר מובחר שבהם נכלל בבחי' האצי'<sup data-n=\"804\">470</sup>, ואח\"כ המובחר מן הנשארים נעשה בריאה בחי' המרכבה דפני ארי' ופני שור<sup data-n=\"805\">471</sup> כו' וכן ביצי' ועשייה, ומהפסולת הוא התהוות נה\"ב נמצא שרש הראשון של נה\"ב הוא",[["793","459","<b>מאמר רב מתיבתא אעא</b>: ראה זהר שלח קסג, א."],["794","460","<b>בה</b>: בהמשך הנדפס: בהן."],["795","461","<b>וכנ\"ל</b>: פט\"ו. פט\"ז."],["796","462","<b>ימינו תחבקני</b>: נסמן בהערה הבאה."],["797","463","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["798","464","<b>ע\"י</b>: בהמשך הנדפס ליתא."],["799","465","<b>בה</b>: ניתוסף בפנים ע\"פ המשך הנדפס."],["800","466","<b>ששרש נה\"א. . התיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>)."],["801","468","<b>זמ\"ל </b>[ ז' מלכין]<b> קדמאין</b>: ראה גם לקמן המשך מצה זו הערה 1623."],["802","467","<b>ושרש נה\"ב. . התהו</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670141\" data-slug=\"torat-chaim\" data-id=\"2300670141\">תו\"ח נח ס, ג</a> ובהנסמן במ\"מ לשם. סה\"מ תרע\"ח ע' רפ."],["803","469","<b>התהו שקדם לתיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380237\" data-slug=\"likkutei-torah\" data-id=\"4001380237\">לקו\"ת אמור לז, ד</a>. וש\"נ. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת בהערה 51."],["804","470","<b>מה שנברר תחילה. . האצי'</b>: ראה גם לעיל מאמר ד\"ה גור ארי' יהודה ובהערה 63."],["805","471","<b>המרכבה דפני ארי' ופני שור</b>: ראה יחזקאל פ\"א."]]],[2000470164,"מבחי' הכלים דאורות דס\"ג דתהו<sup data-n=\"806\">472</sup> שהוא למעלה מבחי' מ\"ה דתיקון<sup data-n=\"807\">473</sup> כו', וגם יובן שסיבת מה שנשאר ולא נתברר כ\"א נשאר בבחי' הפסולת גם זה יורה דרכו שנפל למטה בתחתיות מאד מאד שנודע שזהו מפני כי בשרשו תחלה הי' למעלה יותר, וכמו האבן שבראש החומה<sup data-n=\"808\">474</sup> נופל למרחוק יותר הרבה מכמו האבן שבאמצע או בתחתיות כותל החומה, ונמצא מה שנשאר בבחי' הפסולת גם<sup data-n=\"809\">475</sup> זה יורה דרכו שקודם השבירה הי' במדריגה היותר גבוה בבחי' ש' ס\"ג<sup data-n=\"810\">476</sup> דתהו, וע\"כ בביטוש נה\"ב שפועל בה הזזה ממקומה להיות בבחי' ביטול היש עי\"ז מתעורר שרש נה\"ב ובחי' אורות דתהו שנסתלקו למעלה שיחזרו לשכון בבחי' הכלים שלהם שהוא שרש נה\"ב, ונמצא כי ביטוש והכנעת החומר של הגוף ונה\"ב גדול יותר מבחי' הבירור דתהו שממנו נברר<sup data-n=\"811\">477</sup> להיות בבחי' האצי' ובי\"ע, שהרי בבירור ההוא נשאר דבר היותר נעלה בבחי' השבירה ולא נתעלה, ואח\"כ ע\"י ביטוש הגוף וביטול היש דנה\"ב נתעלה ע\"י הזזתו ממקומו להיות בבחי' ביטול היש עכ\"פ, ותיקון זה של הנה\"ב גורם המשכה שיומשכו אורות דתהו כו', וכמשל עשן העולה מהפתילה<sup data-n=\"812\">478</sup> שגורם המשכת אור הנר אל הפתילה וע' כה\"ג בלק\"ת ראה בד\"ה אחרי הוי' פ\"א בענין כי מנסה כו' לדעת ובהביאור שם ספ\"ג<sup data-n=\"813\">479</sup>, ולכן ע\"י ביטוש הגוף סליק בי' נהורא דחכמתא, וזהו שאה\"כ וגם אני שמעתי<sup data-n=\"814\">480</sup> את נאקת בנ\"י, פי' נאקת היינו ביטוש הגוף שעי\"ז מעורר אורות דתהו ומזה נמשך ואזכור את בריתי, וזהו שנמשלו ישראל לזית<sup data-n=\"815\">481</sup> דוקא שכמו בזית ע\"י כתישה וטחינה וכבישה דוקא יוצא מהם השמן, כך בישראל &lt;30&gt;\nּ ע\"י ביטוש הגוף והכנעת החומר ע\"י עבודה קשה בחומר ובלבנים, ובכל עבודה קשה בטרדת הפרנסה המייגע המוח והגוף ע\"י בחי' ביטוש זה סליק בי' נהורא דנשמתא, ומה<sup data-n=\"816\">482</sup> שאנו רואים שמרוב בלבול המוח דטרדת הפרנסה נשכח ממנו לגמרי עבודת האלקי' ואינו לומד ולבבו לא יצר לו ע\"ז כלל, זהו כ\"ז שאינו מבין ולא התבונן בעצמו מדוע עשה אלקי' ככה ומה חרון אף הגדול<sup data-n=\"817\">483</sup> כ\"כ, וכמו במצרים שבתחילת שעבודם וכמעט כל זמן השעבוד לא עלה מהם נאקה וצעקה כלל עד\"ז הטרוד מאד כ\"ז היותו בבלבול הדעת עצום כ\"כ עד שאינו מחשב בעצמו העוני בדעת והכובד שביסורי'",[["806","472","<b>דס\"ג דתהו</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> ובהערה 2."],["807","473","<b>דס\"ג. . מ\"ה דתיקון</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"א. הנסמן במאמרי אדה\"א דברים ח\"א ע' ה הערה ד\"ה: שם."],["808","474","<b>האבן שבראש החומה</b>: ראה גם לעיל מאמר ד\"ה גור ארי' יהודה פ\"א. וש\"נ."],["809","475","<b>גם</b>: ניתוסף בפנים ע\"פ ההמשך הנדפס. וראה לעיל בשו\"ה יובן [בהמשך הנדפס: שנשאר] — גם."],["810","476","<b>ש' ס\"ג</b>: ראה זהר רע\"מ פינחס רמו, ב."],["811","477","<b>שממנו נברר</b>: בהמשך הנדפס: שנברר ממנו."],["812","478","<b>עשן העולה מהפתילה</b>: ראה גם (בנוסף לאוה\"ת וארא כאן ע' ב'תקע) לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 96. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שי. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540079\" data-slug=\"torat-chaim\" data-id=\"2300540079\">תו\"ח בשלח ח\"א רלט, רע\"ד</a> ובהערה 1094. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316500304\" data-slug=\"or-hatorah-hb\" data-id=\"8316500304\">אוה\"ת תולדות ח\"א ע' 304</a>. בשלח ע' תרפד."],["813","479","<b>בלק\"ת פ' ראה. . ספ\"ג</b>: יט, ג. כא, סע\"ב ואילך."],["814","480","<b>וגם אני שמעתי</b>: וארא ו, ה."],["815","481","<b>שנמשלו ישראל לזית</b>: לעיל רפי\"ד."],["816","482","<b>ומה</b>: בהמשך הנדפס: וזהו."],["817","483","<b>מדוע עשה. . הגדול</b>: ע\"פ נצבים כט, כג."]]],[2000470165,"וטורח הגוף ועל מה ולמה יגיע לו כך, עד שברוב רחמיו וחסדיו נותן לו לב לדעת ומתחרט על מעשיו הרעים אשר קפחו פרנסתו כמארז\"ל הרעותי את מעשי<sup data-n=\"818\">484</sup> וקפחתי פרנסתי וצועק לה' העונה לכל אז ה' יסלח לו שע\"י בירור זה יאיר אור הנפש בתוקף עוז, וכמו במצרים שהעבודה בחומר ובלבנים הי' התיקון דעיר ומגדל דדור הפלגה ושעי\"ז באה שועתם אל האלקים מן העבודה שהוא ע\"ד<sup data-n=\"819\">485</sup> מי בוכים<sup data-n=\"820\">486</sup> דמ\"ת שבוכים על עוצם ירידתם להיות מקור המשפיעים תענוגים גשמיי' שזהו ע\"י רקיע המבדיל ורוצים וחפצים בקרבתם<sup data-n=\"821\">488</sup> להתקרב ולעלות למעלה וכאמרם אנן בעינן למהוי קדם מלכא<sup data-n=\"822\">487</sup>, שזהו ההיפך לגמרי מדור הפלגה שרצו לילך בשרירות לבם הרע ושלא יהי' גילוי פנימיות אלקותו בבחי' הפנימיות וכנ\"ל ובחי' מי בוכים הם ההיפך מזה לגמרי כו', וע\"י מה שתקנו מה שפגמו בבחי' האותיות עי\"ז זכו<sup data-n=\"823\">489</sup> שיומשך המשכת פנימיות אלקותו ע\"י אותיות וז\"ע מ\"ת שהוא בחי' המשכת אלקות בבחי' הפנימיות ע\"י אותיות התורה כו'.\n<b></b>קיצור. ששרש נה\"ב הוא מבחי' התהו שלא נתברר ששרשו גבוה יותר בבחי' התהו וע\"י בחי' ביטול היש עי\"ז נמשכי' אורות דתהו כמשל עשן היוצא מהפתילה, ועד\"ז יובן שמבחי' טרדת הפרנסה עי\"ז נמשך שיאיר אור הנפש בהגוף ביתר שאת ויתר עז<sup data-n=\"824\">490</sup>, וע\"ד שהי' במצרים, והוא ע\"י היותו בבחי' מי בוכים כו'.\nוזהו שת\"י על ותחת רגליו<sup data-n=\"825\">491</sup> מדכר שעבודא דמצרים הות תמן חד ריבא מפנקא כו' ובטיש בטינא, נחית גבריאל ע\"ש והיינו להורות על הבירור בטש גוף התינוק בטינא והעלה אותו גבריאל לשמי מרומא כו', ובזה יובן איך ע\"י מחצית השקל עי\"ז תשא את ראש בנ\"י<sup data-n=\"826\">492</sup>, כי צדקה הוא מעשה ומעשה גדול, לפי שהוא בחי' אתכפי' הכנעת החומר של הגוף ונה\"ב שנותן מיגיעו<sup data-n=\"827\">493</sup>, ועי\"ז מזכך המוח אלף פעמים ככה כמ\"ש בת\"א<sup data-n=\"828\">494</sup> בד\"ה השמים כסאי ע\"ש וזהו הגורם נשיאות ראש, וזהו שא' בזהר אבנא למשקל בה דא יו\"ד, אבן א' ב\"ן שע\"י בירור דב\"ן נמשך מאלף",[["818","484","<b>הרעותי את מעשי</b>: ראה קדושין פב, ב."],["819","485","<b>ע\"ד</b>: וכ\"ה באוה\"ת כאן. ובהמשך הנדפס: בחי'."],["820","486","<b>מי בוכים</b>: ראה דרשות התורה לר' שם טוב ן' שם טוב ר\"פ ויקרא. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380321\" data-slug=\"likkutei-torah\" data-id=\"4001380321\">לקו\"ת במדבר ג, ב</a>."],["821","488","<b>בקרבתם</b>: בהמשך הנדפס: בקרבתנו."],["822","487","<b>דמ\"ת שבוכים. . אנן. . מלכא</b>: ראה ת\"ז ת\"ה (יט, ב). הנסמן במאמרי אדה\"א בראשית ע' קג. שמות ח\"א ריש ע' לו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380481\" data-slug=\"likkutei-torah\" data-id=\"4001380481\">לקו\"ת</a> במדבר שם. שלח מב, ב. לעיל מאמר ד\"ה כמגדל דוד צוארך פיסקא וביאור הדברים. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 6. לקמן ח\"ב (בחלק ההנחות) הנחה ד\"ה כנשר יעיר קנו על יד הערה 111 ואילך. ד\"ה ושאבתם מים על יד הערה 67."],["823","489","<b>זכו</b>: בהמשך הנדפס: זהו."],["824","490","<b>ביתר שאת ויתר עז</b>: ע\"פ ויחי מט, ג."],["825","491","<b>שת\"י על ותחת רגליו</b>: משפטים כד, י (בשינוי)."],["826","492","<b>תשא את ראש בנ\"י</b>: תשא ל, יב."],["827","493","<b>צדקה. . מיגיעו</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>)."],["828","494","<b>מזכך המוח. . בת\"א</b>: בראשית א, ב. סה\"מ תרל\"ח ע' רלב ואילך. וש\"נ. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות על יד הערה 87. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 131."]]],[2000470166,"בחי' אנכי כתר<sup data-n=\"829\">495</sup> וזהו נשיאות ראש ומאבן זה נעשה יו\"ד ע\"ד שנת' בענין האבנים דיעקב<sup data-n=\"830\">496</sup> שנעשו אבן אחד היינו בחי' יו\"ד דחכ' שהוא אחד האמת שבה שורה א\"ס כמ\"ש בסש\"ב פל\"ה בהג\"ה.",[["829","495","<b>אנכי כתר</b>: ראה זהר רע\"מ פינחס רנו, ב."],["830","496","<b>שנת' בענין האבנים דיעקב</b>: ראה לעיל קרוב לספט\"ז."]]],[2000470167,"<h3>[ישקני מנשיקות פיהו] והנה לע\"ל כתיב בבכי יבואו</h3>\n<b>פ' תרומה</b>\n&lt;31&gt;\nּ <b>(ך)</b> והנה לע\"ל כתיב בבכי יבואו<sup data-n=\"831\">497</sup> ובתחנונים אובילם כו' (ירמי' סי' ל\"א<sup data-n=\"832\">498</sup> ), והענין הוא מפני שלע\"ל יהי' גילוי בחי' טעמי תורה כדפרש\"י ע\"פ ישקני מנשיקות פיהו<sup data-n=\"833\">499</sup>, וז\"ל ע\"ש שנתן להם תורתו ודיבר עמהם פנים אל פנים, ואותם דודים עודם עריבים עליהם מכל שעשוע, ומובטחים מאתו להופיע עוד עליהם לבאר להם סוד טעמים<sup data-n=\"834\">500</sup> ומסתר צפונותיה ומחלים פניו לקיים דברו וזהו ישקני מנשיקות פיהו, ונמצא פי' ישקני מנשיקות פיהו על בחי' טעמים שיתגלו לע\"ל שזהו עיקר ביאת המשיח, וקיבול שכר הוא אח\"כ כמ\"ש בסש\"ב פל\"ו בהג\"ה שקבלת<sup data-n=\"835\">501</sup> שכר עיקרו באלף השביעי<sup data-n=\"836\">502</sup> כמ\"ש בלק\"ת מהאריז\"ל, וכדי להיות גילוי זה א\"א כ\"א ע\"י בכיה דוקא, וכמ\"ש מזה<sup data-n=\"837\">503</sup> בלק\"ת בד\"ה שוש אשיש פ\"ד<sup data-n=\"838\">504</sup> שהוא התעוררות רחמים והוא מדתו של יעקב<sup data-n=\"839\">505</sup> שמבריח מן הקצה אל הקצה ע' זח\"ב תרומה קע\"ה ב', וכמ\"ש בסש\"ב פמ\"ה וז\"ל וזהו שאה\"כ וישק יעקב לרחל וישא את קולו ויבך<sup data-n=\"840\">506</sup> כי רחל היא",[["831","497","<b>והנה לע\"ל כתיב בבכי יבואו</b>: מאמר זה הוא מאמר הח' מההמשך וכולל פרקים כ-כא.\nמאמר זה מיוסד על מאמר ד\"ה וידבר וגו' וארא וגו' שנדפס באוה\"ת וארא כרך ז ע' ב'תקעא ואילך.\nהנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחה: ישקני מנשיקות פיהו<sup data-n=\"e50\">*</sup>."],["832","498","<b>בבכי יבואו. . ירמי' סי' ל\"א</b>: פסוק ח."],["833","499","<b>כדפרש\"י ע\"פ ישקני מנשיקות פיהו</b>: שה\"ש א, ב. ראה גם אותיות דר\"ע אות ז<sup data-n=\"e51\">א</sup>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381320\" data-slug=\"likkutei-torah\" data-id=\"4001381320\">לקו\"ת שה\"ש מח, א</a>. מאמרי אדה\"א דברים ח\"ד ס\"ע א'תעג ואילך. ח\"ב ע' תקצ. וש\"נ. שה\"א ג, ב הערה 10. סה\"מ תרל\"ח ע' רכא. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה עטרת תפארת שיבה בסופו."],["834","500","<b>טעמים</b>: ברש\"י ובהמשך הנדפס: טעמי'."],["835","501","<b>שקבלת</b>: בתניא: וקבלת."],["836","502","<b>באלף השביעי</b>: ראה גם מ\"מ הגהות והע\"ק לסש\"ב ובליקוט פירושים כאן. תניא עם ליקוט פירושים וכו' כאן."],["837","503","<b>מזה</b>: ניתוסף בפנים ע\"פ ההמשך הנדפס."],["838","504","<b>בלק\"ת. . פ\"ד</b>: נצבים מח, א ואילך."],["839","505","<b>רחמים. . יעקב</b>: ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 18."],["840","506","<b>וישק. . ויבך</b>: ויצא כט, יא."],["e50","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>א</b>  נדפס גם באוצר המדרשים (אייזענשטיין) ח\"ב ע' 414."]]],[2000470168,"כנס\"י<sup data-n=\"841\">507</sup> מקור כל הנשמות ויעקב במדתו העליונה שהיא מדה\"ר שבאצי' הוא המעורר ר\"ר עלי'<sup data-n=\"842\">508</sup> וישא את קולו למעלה למקור הרחמים העליונים הנק' אב הרחמים ומקורם<sup data-n=\"843\">509</sup>, ויבך לעורר משם<sup data-n=\"844\">510</sup> ולהמשיך משם רחמים רבים על כל הנשמות ועל מקור כנס\"י להעלותן, ונמצא כי התעוררות ר\"ר דיעקב שיומשך למעלה לצורך העלאת כנס\"י ונש\"י זהו ע\"י בכי' דוקא שעי\"ז דוקא ממשיך להיות ברחמיך הרבים רחם עלינו<sup data-n=\"845\">511</sup>, וזהו שאומרים בברכת אהבת עולם אבינו אב הרחמן המרחם רחם נא עלינו, פי' אבינו זהו קאי על יעקב שמדתו שבאצי' הי' בחי' ת\"ת<sup data-n=\"846\">512</sup> דאצי' שזהו בחי' רחמן, והוא ע\"י בכייתו מעורר להיות ברחמיך הרבים רחם עלינו, וזהו המרחם רחם נא עלינו<sup data-n=\"847\">513</sup> כו', ולכן נא' וזכרתי את בריתי יעקב<sup data-n=\"848\">514</sup>, והיינו כי יש ב' בחי' רחמים<sup data-n=\"849\">515</sup> הא' הוא בחי' הרחמים שבסדר השתלשלות שהם במדה וגבול, אבל בחי' רחמיך הרבים הם בלי קץ וגבול כלל שהם רחמים גדולים, והענין דהנה מצד קוטן דעתינו אין אנו משיגי' כ\"כ גודל עוצם הרחמנות שעל הנפש האלקי' אשר ירדה פלאים בסתר המדריגה, ותמורת היותה דבוקה באוא\"ס חיי החיים ע\"י עמידתה באהוי\"ר, ירדה פלאים בסתר המדריגה בגוף ונה\"ב המסית ומדיח כו', ומצד קוטן דעתינו אין אנו משיגי' כ\"ז, וגם כי על כל פשעים תכסה האהבה<sup data-n=\"850\">516</sup> שאוהב א\"ע כו' כי אין אדם רואה חוב לעצמו<sup data-n=\"851\">517</sup>, אבל למעלה ידוע הכל, לכן אנו מבקשי' ברחמיך הרבים רחם עלינו כו', ומלבד הידיעה הנה גם הרחמים הם רחמים פשוטי' כו', וע\"ז אמר ברחמים גדולים אקבצך<sup data-n=\"852\">518</sup>, שזה קאי על לע\"ל, וגם עכשיו אקבצך מהיותך מוטרד במח\"ז וקשור בעניני עוה\"ז השפל, לרוממינו משפלתינו כו', וזהו המלך המרומם לבדו<sup data-n=\"853\">519</sup> כו' ואח\"כ אמר ברחמיך הרבים שהוא ית' המרומם לבדו, ויחיד חי העולמי' מלך<sup data-n=\"854\">520</sup> שחיות כל העולמות עליונים ותחתונים הוא מבחי' מל' דא\"ס אבל הוא ית' יחיד ומיוחד, וכמ\"ש מזה בת\"א בד\"ה &lt;32&gt;\nּ יביאו לבוש מל'<sup data-n=\"855\">521</sup> ובד\"ה כי אתה נרי הוי'<sup data-n=\"856\">522</sup>, ולכן ברחמיך הרבים רחם עלינו, וז\"ע מ\"ש בת\"א בד\"ה אשירה להוי'<sup data-n=\"857\">523</sup>",[["841","507","<b>רחל היא כנס\"י</b>: ראה זהר וארא כט, ב. ב\"ר פע\"א, ב. (בנוסף לתניא כאן). <a class=\"ft-cite\" href=\"#/read/torah-or/3901370425\" data-slug=\"torah-or\" data-id=\"3901370425\">תו\"א מג\"א צד, ד</a>."],["842","508","<b>עלי'</b>: וכ\"ה בתניא. בהמשך הנדפס: עליו."],["843","509","<b>אב הרחמים ומקורם</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380970\" data-slug=\"likkutei-torah\" data-id=\"4001380970\">לקו\"ת ר\"ה סב, ד</a>. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 14."],["844","510","<b>משם</b>: וכ\"ה גם בהמשך הנדפס. ובתניא ליתא."],["845","511","<b>ברחמיך הרבים רחם עלינו</b>: נוסח ברכת יוצר."],["846","512","<b>יעקב. . ת\"ת</b>: ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 16."],["847","513","<b>עלינו</b>: בהמשך הנדפס ליתא."],["848","514","<b>וזכרתי את בריתי יעקב</b>: בחוקותי כו, מב."],["849","515","<b>ב' בחי' רחמים</b>: ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540666\" data-slug=\"torat-chaim\" data-id=\"2300540666\">תו\"ח בשלח ח\"א קעא, א</a> ואילך. לעיל הערה 509."],["850","516","<b>על כל פשעים תכסה האהבה</b>: ע\"פ משלי י, יב."],["851","517","<b>אין אדם רואה חוב לעצמו</b>: ראה שבת קיט, א."],["852","518","<b>ברחמים גדולים אקבצך</b>: ישעי' נד, ז [ושם: וברחמים — אבל כ\"ה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 32. סה\"מ תרל\"ח ע' תלא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540911\" data-slug=\"torat-chaim\" data-id=\"2300540911\">תו\"ח בשלח ח\"א קעז, א</a>. וש\"נ]."],["853","519","<b>המלך המרומם לבדו</b>: נוסח ברכת יוצר."],["854","520","<b>ויחיד. . מלך</b>: נוסח ברכת ברוך שאמר."],["855","521","<b>בת\"א בד\"ה יביאו לבוש מל'</b>: מג\"א צ, ג."],["856","522","<b>ובד\"ה כי אתה נרי הוי'</b>: מקץ מ, ג."],["857","523","<b>בת\"א בד\"ה אשירה להוי'</b>: בשלח סג, ב."]]],[2000470169,"כי גאה גאה שזהו חנון ורחום הוי'<sup data-n=\"858\">524</sup> שהקדים בחי' חנון לרחום להיות הוי', וכדפי' בלק\"ת סד\"ה ואתחנן אל הוי', ושם ספ\"ד<sup data-n=\"859\">525</sup> שכדי להיות הוי' שהוא צמצום והתפשטות כו' כ\"ז הוא מחמת שהוא חנון ורחום, וא\"כ ברחמיך הרבים היינו רח\"ר הנמשכים מש' הוי' דלעילא שלפני ההשתלשלות להיות הוי' שבסדר ההשתל', והרד\"א בפי' ברכת יוצר אור כ' ברחמיך הרבים רחם עלינו ע\"ש וברחמיך הרבים לא עשיתם כלה (נחמי' סי' ט' ל\"א) והוא ע\"ד אני הוי' לא שניתי ואתם בנ\"י לא כליתם (במלאכי סי' ג'<sup data-n=\"860\">526</sup> ), והנה אני הוי' לא שניתי זהו בבחי' ע\"י וכמ\"ש בלק\"ת בשה\"ש בביאור ע\"פ צאינה וראינה דרוש הראשון ושם פ\"ד<sup data-n=\"861\">527</sup> כי בבחי' אצי' שהוא בחי' כמראה אדם יש שינויים, פעמים שההתכללות בענין שהחסד גובר ופעמים להיפך לפי פעלם דבני נשא ע' בזהר וירא דק\"ט ע\"ב, משא\"כ למעלה מהאצי' בבחי' כי לא אדם הוא עז\"נ אני הוי' לא שניתי ומבחי' זו נמשך מה שאתם בנ\"י לא כליתם ע\"ד חצי כלים<sup data-n=\"862\">528</sup> והם אינם כלים, וע' בפרש\"י בחומש ר\"פ נצבים ך\"ט י\"ב, ולכן הביא הרד\"א פסוק זה אע\"פ שיש עוד פסוקים כהנה כמו בנחמי' ט' י\"ט ואתה ברחמיך הרבים לא עזבתם, וע' מפסוק זה בילקוט פ' בלק ע\"פ מה אקב לא קבה אל דרמ\"ג ע\"ב<sup data-n=\"863\">529</sup> דהרבותא שאפי' בשעת החטא רחמיו עליהם, ועוד כהנה רבות, והיינו מטעם הנ\"ל, והנה מבחי' הרחמים נמשך להיות ותן בלבינו בינה<sup data-n=\"864\">530</sup> להבין ולהשכיל, ולכן ע\"י בבכי יבואו התעוררות רחמים יומשך<sup data-n=\"865\">531</sup> גילוי בחי' פנימיות התורה לע\"ל.\n<b></b>קיצור. שהגילוי טעמי תורה שלע\"ל יהי' ג\"כ ע\"י בכי', וכענין המשכת ר\"ר זהו ע\"י בכי' דיעקב שנא' וישא את קולו ויבך, וזהו שאומרי' בברכת יוצ\"א ברחמיך הרבים<sup data-n=\"866\">532</sup>, אבינו אב הרחמן המרחם רחם נא כו', וזהו המלך המרומם, ויחיד חי העולמי' מלך, חנון ורחום הוי', והרד\"א ע\"ד ברחמיך הרבים לא עשיתם כלה, חצי כלים והם אינם כלים כו'.\n(ךא) <b>וזהו</b> ובלילה שירו עמי<sup data-n=\"867\">533</sup> וארז\"ל פ\"ב דחגיגה די\"ב ע\"ב כל העוסק בתורה בעוה\"ז שדומה ללילה הקב\"ה מושך עליו חוט של חסד לעוה\"ב כו', ובת\"א בד\"ה ויהי מקץ שנתים ימים דרוש השני<sup data-n=\"868\">534</sup> כ' והנה בתורה יש בחי' טנת\"א ובחי' טעמים שבתורה<sup data-n=\"869\">535</sup> הוא כמ\"ש ובלילה שירו<sup data-n=\"870\">536</sup> עמי שבחי' השירה והטעמים",[["858","524","<b>חנון ורחום הוי'</b>: תהלים קיא, ד. קמה, ח. דהי\"ב ל, ט."],["859","525","<b>בלק\"ת סד\"ה ואתחנן. . ספ\"ד</b>: ג, א."],["860","526","<b>סי' ג</b>: פסוק ו."],["861","527","<b>בלק\"ת בשה\"ש. . פ\"ד</b>: ראה שם כג, ג."],["862","528","<b>חצי כלים</b>: סוטה ט, א. רש\"י האזינו לב, כג."],["863","529","<b>בילקוט פ' בלק. . דרמ\"ג ע\"ב</b>: דפוס וויניציא שכ\"ו. בלק כג, ח (רמז תשסו)."],["864","530","<b>ותן בלבינו בינה</b>: ברכת אהבת עולם."],["865","531","<b>רחמים יומשך</b>: כ\"ה גם באוה\"ת כאן. ובהמשך הנדפס: בחי' רחמים שיומשך."],["866","532","<b>ברחמיך הרבים</b>: ליתא בהמשך הנדפס."],["867","533","<b>ובלילה שירו עמי</b>: תהלים מב, ט [ושם: שירה — ראה אוה\"ת ברכה ע' א'תתנא: קרי בחולם כמו שירו בוא\"ו. ראה גם סה\"מ תרכ\"ו ע' רצב]. באוה\"ת ובהמשך הנדפס: שירה."],["868","534","<b>ובת\"א בד\"ה ויהי מקץ. . השני</b>: לא, ג."],["869","535","<b>שבתורה</b>: בתו\"א: שבתורה שבע\"פ. באוה\"ת כאן כבפנים."],["870","536","<b>שירו</b>: בתו\"א באוה\"ת ובהמשך הנדפס: שירה."]]],[2000470170,"שהוא<sup data-n=\"871\">537</sup> בחי' הניגון הוא עמו, ושם<sup data-n=\"872\">538</sup> שדוד נענש על שאמר זמירות היו לי חוקיך<sup data-n=\"873\">539</sup> כו' כי התו' היא למעלה מבחי' זו, אלא כענין ואהי' אצלו שעשועי' יום יום<sup data-n=\"874\">540</sup> והוא ענין שירה עמי בחי' טעמים וע' באגה\"ק סי' ל\"ו ד\"ה דוד זמירות<sup data-n=\"875\">541</sup> קרית להו, ובלק\"ת בד\"ה ואהי' אצלו אמון פ\"ג ובהביאור פ\"ב<sup data-n=\"876\">542</sup>, ונת' מזה במ\"א באריכות, ע\"ש ומשם תדרשנו<sup data-n=\"877\">543</sup>. ובלק\"ת בד\"ה שה\"ש<sup data-n=\"878\">544</sup> פ\"ב כ' והנה התלבשות והמשכה זו מבחי' שמו הגדול להתלבש בתורה, פי' שמו הגדול היינו ש' הוי' דלעילא שלמעלה\n&lt;33&gt;\nּ מהפסיק טעמא<sup data-n=\"879\">545</sup>, דהיינו ענין הקב\"ה יושב ועוסק בתורה<sup data-n=\"880\">546</sup> הוא בחי' טעמי תורה",[["871","537","<b>שהוא</b>: בתו\"א ובאוה\"ת: שהם."],["872","538","<b>ושם</b>: ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370153\" data-slug=\"torah-or\" data-id=\"3901370153\">תו\"א לג, א</a>."],["873","539","<b>זמירות היו לי חוקיך</b>: תהלים קיט, נד."],["874","540","<b>ואהי' אצלו שעשועי' יום יום</b>: משלי ח, ל [בדילוג — תיבת אצלו ליתא באוה\"ת כאן]."],["875","541","<b>באגה\"ק<sup data-n=\"e52\">ב</sup> סל\"ו<sup data-n=\"e53\">ג</sup> ד\"ה דוד זמירות</b>: תניא קס, ב ואילך."],["876","542","<b>ובלק\"ת בד\"ה ואהי' אצלו אמון. . פ\"ב</b>: במדבר יח, ג. יט, ג."],["877","543","<b>ונת'. . תדרשנו</b>: באוה\"ת כאן ליתא. ראה גם אוה\"ת נ\"ך כרך ב ע' תתקמא. סה\"מ תרכ\"ז ס\"ע שצא ואילך. ע' תסג ואילך. תרכ\"ט ע' תה ואילך. תרל\"ג ח\"ב ע' תקנד ואילך ובהנסמן בהנ\"ל."],["878","544","<b>ובלק\"ת </b>[בהמשך הנדפס: ועמ\"ש בלק\"ת]<b> בד\"ה שה\"ש</b>: א, ג [בהוספות וכו']."],["879","545","<b>ש' הוי'. . מהפסיק טעמא</b>: תשא לד, ו. זהר אד\"ר נשא קלח, רע\"א. באוה\"ת וארא כאן ניתוסף: עיין לעיל סעי' ב — ע' ב'תקסד. ראה גם סה\"מ תרל\"ח ע' נה. וש\"נ."],["880","546","<b>הקב\"ה יושב ועוסק בתורה</b>: ע\"ז ג, ב.\n\n<b>ב</b>  קו\"א נקרא ג\"כ אגה\"ק — לקו\"ת ד\"ה ויקרא. ועוד. ”הערות\" כ\"ק אדמו\"ר בסו\"ס התניא (מהדורת קה\"ת תשי\"ד ואילך).\n\n<b>ג</b>  ראה ב”הערות\" שם: קו\"א מסומן1 — בהוצאות2: 1856 תרכ\"ב. לעמברג חמו\"ד. 31864 ווין חש\"ד. ובהערה לשם: כנראה גם הצ\"צ סימן את הקו\"א. . ד\"ה דוד זמירות סימן ל\"ו. ובמהדורת י\"א ניסן תשמ\"ב (מהדורא קסד) ואילך ניתוסף: הערה לאחר זמן: לאחרונה נתקבלו כמה ביכלאך. . מסומן בגכי\"ק הצ\"צ סי' ל\"ז. . סי' ל\"ו. </b>\n<b>וכ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8160080255\" data-slug=\"or-hatorah-hb\" data-id=\"8160080255\">אוה\"ת מקץ כרך ה' ע' 1946</a>. וארא כאן ע' ב'תקעב. תצוה ע' א'תשנג. תהלים (יהל אור) ע' תסא. ע' תרלח. ביאוה\"ז נשא כרך ב ע' תתקעג. סה\"מ תרכ\"ז ע' רצד. ס\"ע שצא. </b>\n<b>אבל ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316270387\" data-slug=\"or-hatorah-hb\" data-id=\"8316270387\">אוה\"ת</a> בראשית כרך ה ע' 2010. וארא כרך ז ע' ב'תקצ. יתרו ע' תתפט. תזריע כרך א ע' רנה. ואתחנן ע' קסא. ברכה ע' א'תתנ. תהלים כרך ב ע' תתקמא. ביאוה\"ז אחרי כרך ב ע' תתקכב: סי' ל\"ז4. </b>\n<b>ויש להעיר שבכ\"מ5 צויין ש”ד\"ה וצדקה כנחל איתן\" הוא סי' ל\"ז. </b>\n<b>וכ\"ה גם (בנוסף לכל הבא לקמן) בסה\"מ תרפ\"ו שהובא בסמוך בהערה 4. ולהעיר מסה\"ש תש\"ה ע' 111. </b>\n<b>והם המסומנים ברשימת דפוסי התניא — כב. כח. כט. ל. כו[א-ב]. — כנראה שהציונים נעשו עפ\"י דעת המו\"ל. </b>\n<b>בס' תורת חב\"ד ח\"א (לקו\"א תניא), כפר חב\"ד ג' תמוז תשמ\"א ע' 22 בהערה 87 הנה משום מה נעדרה מהדורה זו. ויש להוסיפה ולפי מספריו צ\"ל: כד. </b>\n<b>ולכאורה כן משמע גם מסה\"מ תרנ\"ג ריש ע' רלט. הגהות לד\"ה פתח אלי' תרנ\"ח ע' ו וע' כ. סה\"מ תרפ\"ו ע' קצב שקורא ל”ד\"ה להבין מ\"ש בפע\"ח\" סי' ל\"ו. </b>\n<b>ומהם: <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450693\" data-slug=\"or-hatorah-hb\" data-id=\"8316450693\">אוה\"ת</a> בראשית כרך ג ע' 1118. ויחי (כרך ב) ע' שפז. (כרך ו) ע' 2274. (כרך ז) ע' 2538. וארא כאן ע' ב'תקעב. בשלח ע' תלב. תזריע (כרך ב) ע' תקטו. (כרך ד) ע' א'נב. בחוקותי כרך ב ע' תרצג [ושם: סי' ל\"ד. אבל במהדורת תשנ\"ג: סי' ל\"ז]. פ' ראה ע' תרסב וע' תרסג. ירמי' כרך א ע' שנ. תהלים (יהל אור) ע' שלה."]]],[2000470171,"ורננא דאורייתא זרקא מקף שופר<sup data-n=\"881\">547</sup>, והענין כי האותיות הם בחג\"ת והתגין בינה, והנקודות בחכמה והטעמים בכתר כן נת' ממ\"ש הפרד\"ס בשער האותיות הוא שער ך\"ז פ\"ג ובשער הנקודות פ\"ו<sup data-n=\"882\">548</sup> ובשער הטעמי' פ\"ה, והענין כי שרש האותיות הם בחי' כלים<sup data-n=\"883\">549</sup> שבהם וע\"י נמשך אור השכל מהרב לתלמיד שהרי אם לא האותיות לא הי' יכולת האדם להשפיע לזולתו דבר חכ', והנה לפי שנתחלקו לחלקי' היינו ך\"ב הברות ע\"כ יוכלו להיות כלים כמו שיוצק מחביות גדולה לתוך כלים קטנים כך עי\"ז יכולים<sup data-n=\"884\">550</sup> לקבל, וההתחלקות הוא ע\"י בחי' הגבורות, והוא ג\"כ החסד כו' וכמו גבורות גשמים<sup data-n=\"885\">551</sup> שיורדים בגבו' טיפין טיפין<sup data-n=\"886\">552</sup> וזהו עיקר החסד, ע\"כ המשכת האותיות הוא מבחי' חג\"ת, או י\"ל הצירוף האותיות להיות תיבה זהו ע\"י החסד, וכמ\"ש בסש\"ב ח\"ב פי\"ב<sup data-n=\"887\">553</sup> וכשנצטרפו ריבוי אותיות<sup data-n=\"888\">554</sup> להיות תיבה אזי מלבד ריבוי מיני כחות וחיות הנמשכי' כפי מספר אותיות התיבה<sup data-n=\"889\">555</sup>, עוד זאת העולה על כולנה המשכת כח עליון וחיות כלליות<sup data-n=\"890\">556</sup> כו' והוא המחברתן<sup data-n=\"891\">557</sup> ומצרפתן יחד כו' עכ\"ל, וא\"כ י\"ל שזהו מבחי' החסד, ובס\"י איתא שך\"ב אותיות נחלקי' בשלשה<sup data-n=\"892\">558</sup> מדרגות<sup data-n=\"893\">559</sup> יש מהם בבחי' החסדי' ויש בבחי' הגבורות ויש מהם בבחי' ממוצעים, וי\"ל מאחר שהאותיות הם כלים, והכלים יש בהם ג' בחי' פנימי אמצעי חיצון<sup data-n=\"894\">560</sup>, ע\"כ כלולים מחג\"ת, וע' בלק\"ת פ' שלח בד\"ה פ' הנסכים<sup data-n=\"895\">561</sup> ושם פ\"א גבי וג' כחות אלו הם בחי' אברהם יצחק ויעקב, נמצא האותיות הם מחג\"ת, והתגין הם<sup data-n=\"896\">562</sup> מהבינה, וכ\"כ במאו\"א אות תי\"ו סעי' יו\"ד תגין<sup data-n=\"897\">563</sup> מצד בינה תגא ברישא דמלכא, וע' באגה\"ק סי' ך\"ט ד\"ה אשת חיל עטרת בעלה בענין ודאשתמש בתגא חלף שהמל'<sup data-n=\"898\">564</sup> נק' תגא וכתרה של תורה לפי שהם גילוי רצון העליון ב\"ה, שהוא למעלה מחכ' עילאה כו', וא\"כ מה שהם מהבינה זהו ע\"ד בחי' בעטרה שעטרה לו אמו<sup data-n=\"899\">565</sup>, ואפ\"ל שזהו ת\"ת דאימא",[["881","547","<b>זרקא מקף שופר</b>: ראה זהר בראשית כד, א. ב. הנסמן במאמרי אדה\"א דברים ח\"ד ע' א'תסט."],["882","548","<b>פ\"ו</b>: כ\"ה גם באוה\"ת כאן. ובהמשך הנדפס: פ\"ג. וצ\"ל כבפנים."],["883","549","<b>האותיות. . כלים</b>: נסמן לעיל במאמר ד\"ה כמגדל דוד צוארך הערה 33."],["884","550","<b>יכולים</b>: ניתוסף בפנים ע\"פ המשך הנדפס. ובאוה\"ת כאן: יוכל התלמיד."],["885","551","<b>גבורות גשמים</b>: תענית ב, א. ראה סידור שחרית סא, ד. שער הסוכות רנז, ד. שער הלולב רסד, ב. מאמרי אדה\"ז הנחות הר\"פ ע' נו. תקס\"ב ח\"א ע' לב. ענינים ע' שפ. אמרי בינה שער הק\"ש נא, א ואילך. מאמרי אדה\"א דברים ח\"ד ע' א' תכח ואילך. סה\"מ תרכ\"ז ס\"ע רמט ואילך. וש\"נ."],["886","552","<b>טיפין</b>: ניתוסף בפנים ע\"פ ההמשך הנדפס. וכ\"ה גם באוה\"ת כאן."],["887","553","<b>פי\"ב</b>: בהמשך הנדפס: פמ\"ב. וצ\"ל כבפנים."],["888","554","<b>ריבוי אותיות</b>: באוה\"ת ובתניא: אותיות הרבה."],["889","555","<b>אותיות התיבה</b>: בהמשך הנדפס: אותיות התו'. בתניא: האותיות שבתיבה. באוה\"ת: התיבה."],["890","556","<b>כלליות</b>: באוה\"ת ובתניא: כללית."],["891","557","<b>והוא המחברתן</b>: בתניא: והיא מחברתן. באוה\"ת: והיא המחברתן."],["892","558","<b>ובס\"י איתא שך\"ב אותיות נחלקי' בשלשה מדרגות</b>: רפ\"ב."],["893","559","<b>שך\"ב אותיות נחלקי' בשלשה מדרגות</b>: ועיין מזה בפרדס שער האותיות פ\"ג (אוה\"ת כאן)."],["894","560","<b>והכלים. . פנימי אמצעי חיצון</b>: ראה ע\"ח שער המוחין ש\"כ, פ\"ה."],["895","561","<b>בלק\"ת פ' שלח בד\"ה פ' הנסכים</b>: [באוה\"ת כאן: בד\"ה ענין הנסכים] מא, ד."],["896","562","<b>הם</b>: בהמשך הנדפס: הוא."],["897","563","<b>תגין</b>: במאו\"א: תגי."],["898","564","<b>שהמל'</b>: באוה\"ת: שההלכות."],["899","565","<b>בעטרה שעטרה לו אמו</b>: שה\"ש ג, יא."]]],[2000470172,"שנעשה כתר לז\"א<sup data-n=\"900\">566</sup>, וזהו ההפרש בין תגין ובין טעמים שהם ג\"כ בכתר אלא שהטעמים הם בעתיק יומין וא\"א<sup data-n=\"901\">*567</sup> שהם כתר דאצי' ממש, משא\"כ התגין הם מה שמת\"ת דאימא נעשה כתר לז\"א, וע' מענין ב' כתרים אלו בלק\"ת סוף שה\"ש<sup data-n=\"902\">567</sup> בהביאור ע\"פ כי על כל כבוד חופה ובסידור<sup data-n=\"903\">568</sup> ד\"ה הנ\"ל, ועמ\"ש בד\"ה ומשוש חתן על כלה<sup data-n=\"904\">569</sup> שתושבע\"פ נק' כלה ונק' א\"ח<sup data-n=\"905\">571</sup>, ותושב\"כ נק' חתן<sup data-n=\"906\">570</sup> והשפעה מתושב\"כ לתושבע\"פ זהו ע\"י אותיות דתושב\"כ שהם נמשכי' בתושבע\"פ, והיינו דכתי' ונהר יוצא מעדן<sup data-n=\"907\">572</sup> להשקות את הגן, גן הוא בחי' תושבע\"פ ונהר יוצא הוא בחי' אותיות וכמ\"ש במאו\"א אות א' סנ\"ב<sup data-n=\"908\">573</sup> אות נק' היסוד כי הוא אות ברית קדש ואתוון רברבין ביסוד אימא ואתוון בינונים ביסוד ז\"א ואתוון זעירין<sup data-n=\"909\">574</sup> ביסוד דמל', וא\"כ המשכת אותיות בינונים דתושב\"כ הם בחי' יסוד ז\"א שנמשך בתושבע\"פ מל'<sup data-n=\"910\">575</sup>, וא\"ח &lt;34&gt;\nּ עט\"ב<sup data-n=\"911\">576</sup> נק' תגא כתר דז\"א, וזהו ששים המה מלכות<sup data-n=\"912\">577</sup> ושמונים פלגשים כו' אחת היא יונתי<sup data-n=\"913\">578</sup>, ששים המה מלכות ששים מס'<sup data-n=\"914\">579</sup> שמקבלים מאותיות דתושב\"כ, ותגין רצון התו' כתר דז\"א אחת היא יונתי בחי' רעו\"ד וכענין מס\"נ שלמעלה מהטו\"ד, ע\"ד יש קונה עולמו<sup data-n=\"915\">580</sup> בשעה א' כמ\"ש בד\"ה מה יפו<sup data-n=\"916\">581</sup> פעמיך בנעלים שממשיך רצה\"ע רעדכ\"ר<sup data-n=\"917\">582</sup> כתר דא\"א שלמעלה מהרצון שבתורה<sup data-n=\"918\">583</sup> וזהו תפלה גימ' שירה<sup data-n=\"919\">584</sup> שע\"י רעו\"ד נמשך שירה עמי טעמים כי מס\"נ",[["900","566","<b>ת\"ת דאימא שנעשה כתר לז\"א</b>: ראה ע\"ח שער מוחין דצלם שכ\"ג, רפ\"ה ורפ\"ז. מאמרי אדה\"א דברים ח\"ג ע' תתעג. וש\"נ."],["901","*567","<b>שהטעמים הם בעתיק יומין וא\"א</b>: ראה מאו\"א מערכת טעמים סי\"ח."],["902","567","<b>בלק\"ת סוף שה\"ש</b>: מז, ג ואילך."],["903","568","<b>ובסידור</b>: דרושים לחתונה קל, ב ואילך."],["904","569","<b>בד\"ה ומשוש חתן על כלה</b>: וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770088\" data-slug=\"or-hatorah-hb\" data-id=\"8316770088\">אוה\"ת</a> כאן. שה\"ש ח\"ב ע' תנד. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770429\" data-slug=\"or-hatorah-hb\" data-id=\"8316770429\">אוה\"ת שה\"ש ח\"ב ע' תכט</a>: בד\"ה כמשוש חתן על כלה ויצא תקס\"ח. הועתק גם לקמן בהמשך מצה זו רפ\"ב [ושם: ומשוש]. מאמרי אדה\"ז הנחת הר\"פ ע' סג [ושם: והי' כמשוש]. נביאים ע' קפה [ושם: כנ\"ל]. ע' קפט [ושם: כמשוש חתן]. אוה\"ת סידור ע' רכו ואילך. ובארוכה במאמרי אדה\"א דרושי חתונה ח\"א ע' טו ואילך."],["905","571","<b>א\"ח</b>: אשת חיל."],["906","570","<b>שתושבע\"פ נק' כלה. . ותושב\"כ נק' חתן</b>: ראה גם ערכי הכנויים לבעל סדה\"ד מערכת חתן. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381105\" data-slug=\"likkutei-torah\" data-id=\"4001381105\">לקו\"ת ברכה צד, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381110\" data-slug=\"likkutei-torah\" data-id=\"4001381110\">צה, ד</a>. מאמרי אדה\"א דרושי חתונה שם ובהערה לשם. סה\"מ תרל\"ח ע' קנה ואילך. לקמן המשך מצה זו פי\"ז ובהערה 535. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מצה זו על יד הערה 24."],["907","572","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["908","573","<b>סנ\"ב</b>: באוה\"ת כאן : סי\"ב וצ\"ל כבפנים, וכ\"ה באוה\"ת נח נה, ב."],["909","574","<b>ואתוון רברבין. . זעירין</b>: במאו\"א: ואותיות רברבין ביסוד בינה ואותיות. . ואותיות קטנות — וכ\"ה באוה\"ת נח שם."],["910","575","<b>בתושבע\"פ מל'</b>: ראה ת\"ז בהקדמה יז, א."],["911","576","<b>וא\"ח עט\"ב</b>: משלי יב, ד."],["912","577","<b>ששים המה מלכות</b>: שה\"ש ו, ח."],["913","578","<b>אחת היא יונתי</b>: שם ו, ט. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380843\" data-slug=\"likkutei-torah\" data-id=\"4001380843\">לקו\"ת פ' ראה לא, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381294\" data-slug=\"likkutei-torah\" data-id=\"4001381294\">שה\"ש מא, ג</a> ואליך."],["914","579","<b>ששים. . מס'</b>: ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381281\" data-slug=\"likkutei-torah\" data-id=\"4001381281\">לקו\"ת שה\"ש לח, ב</a> מציין: ע' ברבות בשיר השירים במקומו ובפ' קרח [פי\"ח, כא] גבי ובני קרח לא מתו. ראה גם הנסמן במאמרי אדה\"א שמות ח\"א ע' עו."],["915","580","<b>יש קונה עולמו</b>: ע\"ז י, ב."],["916","581","<b>בד\"ה מה יפו</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381302\" data-slug=\"likkutei-torah\" data-id=\"4001381302\">לקו\"ת שה\"ש מג, ג</a>."],["917","582","<b>רעדכ\"ר</b>: ראה זהר ספדצ\"נ תרומה קעו, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670202\" data-slug=\"torat-chaim\" data-id=\"2300670202\">תו\"ח בראשית לו, ג</a> הערה 23. תצוה ח\"ב שעו, ג."],["918","583","<b>שלמעלה מהרצון שבתורה</b>: ראה גם מאמרי אדה\"ז על מארז\"ל ע' תמח. סהמ\"צ להצ\"צ לט, ב."],["919","584","<b>תפלה גימ' שירה</b>: מובא גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316650111\" data-slug=\"or-hatorah-hb\" data-id=\"8316650111\">אוה\"ת</a> וארא כאן ע' ב'תקעג. חוקת ע' תתמ. תהלים כרך ב ע' תתקמב. סה\"מ תר\"ל ע' קסא."]]],[2000470173,"הוא למעלה מהטו\"ד<sup data-n=\"920\">585</sup>, ור\"ל למעלה מהטעם והדעת ושכל המושג ע\"ד שהחכ' נק' טעמים<sup data-n=\"921\">586</sup> לפעמים, וע\"כ ממשיך בחי' טעמים דכתר שלמעלה מהטעמים דחכ', וי\"ל שז\"ע מ\"ש טוב טעם ודעת למדני<sup data-n=\"922\">587</sup> בחי' טעם הכמוס, וי\"ל לפי שבמצותיך האמנתי האמונה היא למעלה מהטו\"ד, וכן המצות שרשן בכתר<sup data-n=\"923\">588</sup> כו', וזהו שוש אשיש<sup data-n=\"924\">589</sup> כו' כחתן כו' תושב\"כ וככלה כו'<sup data-n=\"925\">590</sup> תושבע\"פ להיות כי אשיש בטעמים דכ\"ע כו' והנקודות הם מחכ' ולכן ע\"י הנקודות משתנה פי' התיבה, והיינו כי מקור הדבור מהחכ' אבא יסד ברתא לכן הנקודות שהם מהחכ' עושים הפי' בהתיבה, וכ\"ה בפרד\"ס שער הנקודות פ\"ו וכ\"כ במאו\"א<sup data-n=\"926\">591</sup> אות נו\"ן ס\"ל נקודות בכ\"מ מצד החכ' וכן נקודה בהיכלא נקודה חכ' בהיכלא בינה, וע' בד\"ה ראה שבלק\"ת<sup data-n=\"927\">592</sup> שבנפש זהו בחי' הביטול שלמעלה מן השכל, וא\"כ לכאו' זהו כענין הטעמים שנת\"ל שזהו בחי' מס\"נ שלמעלה מן השכל, אך הענין דבאמת יש הבדל ביניהם שענין בחי' הביטול דחכ' בחי' ונחנו מה<sup data-n=\"928\">593</sup> זהו ג\"כ למעלה מהשכל המושג אך אעפ\"כ בחכ' זהו מושג, ולכן בהמשכתם למטה נמשך מהם פי' התיבה שזהו פשט שיבין זולתו, אך הטעמים שבכתר הם זרקא מקף שופר נגינה זהו למעלה לגמרי משכל המושג שאינם שייכי' כלל לפי' האותיות, והטעם שאינם שייכי' כלל להבנת האותיות לפי ששרשם מהכתר שהוא למעלה מהשגה כ\"א הם ניגון ונעימה והיינו שהם המשכת התענוג עליון שהוא בעצם למעלה מהשכל, ולכן כשמשכיל ונופל לו שכל חדש מתמלא תענוג לפי שברגע זו נמשך מעצמיות נפשו בחי' נפש המשכלת להאיר בבחי' השכל דחכ' ואז מאיר התענוג שהוא מבחי' העונג דכתר, ולכן נא' אז תתענג על הוי'<sup data-n=\"929\">594</sup> היינו בחי' הוי' דחכ', וזהו בחי' הטעמים דכתר כו'.\n<b></b>קיצור. ובלילה שירה, עסק התו' בעוה\"ז שדומה ללילה, טנת\"א, אותיות בחג\"ת, תגין בבינה, נקודות בחכ', טעמים בכתר.",[["920","585","<b>מס\"נ הוא למעלה מהטו\"ד</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370443\" data-slug=\"torah-or\" data-id=\"3901370443\">תו\"א מג\"א צט, ב</a>. (מובא) לקמן בהמשך מצה זו פכ\"ו ובהערה 855."],["921","586","<b>שהחכ' נק' טעמים</b>: ראה לקמן הערה 622."],["922","587","<b>טוב טעם ודעת למדני</b>: תהלים קיט, סו. ראה גם ביאוה\"ז האזינו קכו, ג. מאמרי אדה\"א נ\"ך ע' תפב ואילך."],["923","588","<b>המצות שרשן בכתר</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310046\" data-slug=\"tanya\" data-id=\"3401310046\">תניא פמ\"א</a> בהגהה ובמ\"מ הגהות והע\"ק לשם. מאמרי אדה\"א קונטרסים ע' רסג. וש\"נ."],["924","589","<b>שוש אשיש</b>: ישעי' סא, י."],["925","590","<b>תושב\"כ וככלה כו'</b>: בהמשך הנדפס ליתא. באוה\"ת כאן כבפנים ובהשמטת כל ה”כו''."],["926","591","<b>במאו\"א</b>: בשינוי קצת."],["927","592","<b>בד\"ה ראה שבלק\"ת</b>: פ' ראה יח, א ואילך."],["928","593","<b>ונחנו מה</b>: בשלח טז, ז. ח. ראה גם מאמרי אדה\"א בראשית ע' כב. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540049\" data-slug=\"torat-chaim\" data-id=\"2300540049\">תו\"ח שמות ח\"א מג, א</a>. וש\"נ. לקמן המשך מצה זו פ\"ד. פכ\"ז. פרק ג\"ל. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי הענן והחשך ובהערה 36. לקמן ח\"ב (בחלק המאמרים) ד\"ה ויובן כו' הני ששה ועשרים הודו על יד הערה 140."],["929","594","<b>אז תתענג על הוי'</b>: ישעי' נח,יד."]]],[2000470174,"<h3>[ואתה תצוה] וז\"ע שארז\"ל על שלא ברכו בתורה</h3>\n<b>פ' תצוה</b>\n(ךב) <b>וז\"ע</b> שארז\"ל על שלא ברכו<sup data-n=\"930\">595</sup> בתורה<sup data-n=\"931\">596</sup>, דר\"ל שלא המשיכו המשכת אוא\"ס בתורה, וזהו כמ\"ש במ\"א שזה נמשך ע\"י התפלה<sup data-n=\"932\">597</sup> בחי' ביטול הרצון מט\"ט<sup data-n=\"933\">598</sup> קושר כתרים לקונו<sup data-n=\"934\">599</sup>, א\"כ ע\"י התפלה נמשך המשכת הכתר שהוא הטעמים, וז\"ע יהי רצון המשכת הרצון שלמעלה מהחכ'<sup data-n=\"935\">600</sup>, והיינו אע\"פ שלפי הרצון הנמשך מהחכ' שבתורה נמשך עליו הדין ע\"ד אין יסורים בלא עון<sup data-n=\"936\">601</sup> מ\"מ ע\"י שממשיכים מהרצון עליון דכתר ממשיכים להיות סלח לנו, &lt;35&gt;\nּ וזהו יהי רצון וענין קושר כתרים, ע' מזה בת\"א בד\"ה מזוזה מימין<sup data-n=\"937\">602</sup> ובלק\"ת ד\"ה מה יפו פעמיך<sup data-n=\"938\">603</sup>, וע' בת\"א ד\"ה ויקח מן הבא בידו מנחה<sup data-n=\"939\">604</sup> מעלת התפלה שזהו דבר חדש, וע' בלק\"ת סד\"ה ואהי' אצלו אמון<sup data-n=\"940\">605</sup> מענין ממושבותיכם תביאו לחם תנופה, וכיון שממשיכים ע\"י ק\"ש ותפלה מבחי' כתר זהו כענין הטעמים שהם המשכת אותיות התענוג מבחי' ע\"י וא\"א, וזהו ברכו בתורה היינו המשכת אוא\"ס בתורה, וכענין דוד הי' מחבר תושמ\"ע בהקב\"ה<sup data-n=\"941\">606</sup>, והגם שהכתרים נמשכי' מהאותיות ותיבות התפלה והרי האותיות הם בחי' אחרונה שבארבע בחי' טנת\"א, מ\"מ ד' בחי' טנת\"א הרי<sup data-n=\"942\">608</sup> הם",[["930","595","<b>וז\"ע שארז\"ל על שלא ברכו בתורה</b>: מאמר זה הוא מאמר הט' וסיום ההמשך וכולל פרקים כב-כג.\nמאמר זה מיוסד על מאמר ד\"ה וידבר וגו' וארא וגו' שנדפס באוה\"ת וארא כרך ז ריש ע' ב'תקעד ואילך בשינויים ובהוספות.\nהנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחה: ואתה תצוה את בנ\"י<sup data-n=\"e54\">*</sup>."],["931","596","<b>שלא ברכו בתורה</b>: ב\"מ פה, ב. נדרים פא, א. ראה גם לק\"ת פ' ראה כט, א. אוה\"ת ואתחנן ס\"ע רנב ואילך. דרך חיים פא, א. סה\"מ תרכ\"ט ע' רצ. וש\"נ. תרל\"ג ח\"ב ע' תלו ואילך. וש\"נ."],["932","597","<b>וזהו </b>[בהמשך הנדפס: והיינו]<b>. . ע\"י התפלה</b>: ראה מאמר ד\"ה תורה צוה תקס\"ז נדפס במאמרי אדה\"ז תקס\"ו ע' שעב."],["933","598","<b>מט\"ט</b>: וכ\"ה באוה\"ת כאן. במאמרי אדה\"ז שם: סנד\"ל."],["934","599","<b>מט\"ט קושר כתרים לקונו</b>: ראה זהר בראשית לז, ב. סה\"מ תש\"ח ע' 202 בהערה."],["935","600","<b>יהי רצון. . מהחכ'</b>: ראה גם לעיל מאמר ד\"ה כמגדל דוד צוארך ובהערה 58."],["936","601","<b>אין יסורים בלא עון</b>: שבת נה, סע\"א."],["937","602","<b>בת\"א בד\"ה מזוזה מימין</b>: מקץ מב, ב. מג, סע\"א ואילך."],["938","603","<b>ובלק\"ת ד\"ה מה יפו פעמיך</b>: שה\"ש מג, ג."],["939","604","<b>בת\"א ד\"ה ויקח מן הבא בידו מנחה</b>: וישלח כה, ד."],["940","605","<b>וע' בלק\"ת. . אמון</b>: במדבר כ, א ואילך."],["941","606","<b>דוד הי' מחבר תושמ\"ע בהקב\"ה</b>: באוה\"ת כאן ע' ב'תקעה: בזח\"ג פ' פינחס דף רכ\"ב ע\"ב. בסה\"מ תרל\"ו ח\"ב ע' רסד: בס' מעין החכמה מדרש רז\"ל. . וכ\"ה ברע\"מ פ' פנחס דף רכ\"ב ע\"ב. שם ע' שכז: בס' הבהיר או בס' מעין החכ'. תרכ\"ז ע' כד וע' לא במעיין החכ' או בס' הבהיר. ראה ס' הבהיר סקצ\"ו ובאור בהיר לשם. מאמרי אדה\"א דברים ח\"ג ע' תשפג. וש\"נ. ח\"ד ע' א'רכא. וש\"נ. דרושי חתונה ח\"ב ע' תרכח בשם מדרש."],["942","608","<b>הרי</b>: ניתוסף בפנים ע\"פ ההמשך הנדפס."],["e54","*","ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470175,"כמו ד' בחי' דצח\"ם<sup data-n=\"943\">607</sup> שבאמת הדומם גבוה יותר בשרשו, כמ\"ש בד\"ה מזמור שיר חנוכת הבית דרוש השני<sup data-n=\"944\">609</sup>, ולכן בתושבע\"פ לא נז' שום ביאור על הטעמים<sup data-n=\"945\">610</sup>, כי כל החכמה שבתושבע\"פ זהו נמשך מהאותיות שבתושב\"כ שמפסוקי' המדברים במצות שבת<sup data-n=\"946\">611</sup> נעשה בתושבע\"פ כל אורך ורוחב מס' שבת וכן מס'<sup data-n=\"947\">612</sup> עירובין, ומפסוק בסוכות תשבו ולקחתם לכם כו' נעשה כל מס' סוכה<sup data-n=\"948\">613</sup> והיינו רק מהאותיות והתיבות, אבל על הטעמים שבפסוקים לא נמצא שום ביאור בתושבע\"פ, ועל התגין ארז\"ל קווצותיו תלתלים שהי' ר\"ע דורש על כל קוץ וקוץ תלי תלים של הלכות<sup data-n=\"949\">614</sup>, והיינו על התגין, וכן על הנקודות יש לפעמים לימוד בתושבע\"פ כמו יש אם למקרא ויש אם למסורת<sup data-n=\"950\">615</sup>, וכן למה נקוד על איה<sup data-n=\"951\">616</sup>, רק על הטעמים לא נמצא שום לימוד בתושבע\"פ, והיינו כי תושבע\"פ היא בחי' בינה כמ\"ש בלק\"ת בד\"ה ביום השמיני עצרת<sup data-n=\"952\">617</sup>, כנישין שז\"ע שמע בני מוסר אביך<sup data-n=\"953\">618</sup> זה תושב\"כ, ואל תטוש תורת אמך זהו תושבע\"פ, כי אם לבינה תקרא<sup data-n=\"954\">619</sup>, ולפעמים מצינו שאמרו בת\"ז מל' פה תושבע\"פ קרינן לה, והיינו שתושב\"כ ותושבע\"פ הם ח\"ע וח\"ת<sup data-n=\"955\">620</sup>, והנה בינה הוא בחי' השגה והבנה והוא הנמשך מאור החכ', ולכן הטעמים שהם למעלה מן החכ' א\"א שיבואו בבחי' השגה בבינה, ע\"ד רבי לא שנה חייא מנין לו<sup data-n=\"956\">621</sup>, והנה לפעמים אמרו בענין טנת\"א טעמים בחכ' נקודות בבינה תגין בז\"א אותיות במל'<sup data-n=\"957\">622</sup>, אך הענין הוא דיש ב' בחי' באותיות היינו אותיות שמהם נבראו שמים וארץ ואותיות התורה,",[["943","607","<b>ד' בחי' טנת\"א. . דצח\"ם</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' א'יט. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940173\" data-slug=\"or-hatorah-hb\" data-id=\"8159940173\">אוה\"ת</a> כאן. יתרו ע' א'ג וע' א'ז (אוה\"ת אמור כרך ב ע' תקפט וע' תקצג)."],["944","609","<b>בד\"ה מזמור שיר. . השני</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381123\" data-slug=\"likkutei-torah\" data-id=\"4001381123\">לקו\"ת ברכה צט, א</a>. ד."],["945","610","<b>בתושבע\"פ. . על הטעמים</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' קה. ח\"ד ע' א'תע. ובהנסמן בהנ\"ל. שמות ח\"א ע' לב וע' ע."],["946","611","<b>שמפסוקי' המדברים במצות שבת</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 22."],["947","612","<b>מס'</b>: וכ\"ה באוה\"ת כאן. ובהמשך הנדפס ליתא."],["948","613","<b>בסוכות תשבו ולקחתם לכם. . מס' סוכה</b>: אמור כג, מב. מ. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ישקני מנשיקות פיהו ובהערה 68."],["949","614","<b>ארז\"ל קווצותיו תלתלים. . הלכות</b>: כ\"ה בכ\"מ<sup data-n=\"e55\">א</sup>. שה\"ש ה, יא. ראה ערובין כא, סע\"ב. מנחות כט, ב."],["950","615","<b>יש אם למקרא. . למסורת</b>: קדושין יח, ב."],["951","616","<b>למה נקוד על איה</b>: ב\"מ פז, א."],["952","617","<b>תושבע\"פ. . בינה. . בד\"ה ביום השמיני עצרת</b>: לקו\"ת שמ\"ע פה, ב. ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תנ. וש\"נ. במדבר ח\"ג ע' תתקפ. וש\"נ."],["953","618","<b>שמע בני מוסר אביך</b>: משלי א, ח. ראה גם אגה\"ק סכ\"ט (קנא, א). מאמרי אדה\"ז תקע\"א ע' פא. מאמרי אדה\"א דברים ח\"ד שם. וש\"נ."],["954","619","<b>כי אם לבינה תקרא</b>: משלי ב, ג. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600547\" data-slug=\"or-hatorah-hb\" data-id=\"8316600547\">אוה\"ת משלי כרך א ע' תקמז</a>."],["955","620","<b>שתושב\"כ ותושבע\"פ הם ח\"ע וח\"ת</b>: ראה גם (בנוסף לאוה\"ת כאן) <a class=\"ft-cite\" href=\"#/read/torah-or/3901370024\" data-slug=\"torah-or\" data-id=\"3901370024\">תו\"א בראשית ו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540135\" data-slug=\"torat-chaim\" data-id=\"2300540135\">תו\"ח וארא ח\"א עא ג</a>. וש\"נ."],["956","621","<b>רבי. . חייא מניין לו</b>: וכ\"ה באוה\"ת כאן. סה\"מ תרס\"ה ע' רצז. ראה ערובין צב, א. מאמרי אדה\"א שמות ח\"א ע' לג."],["957","622","<b>טעמים בחכ'. . אותיות במל'</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א. (בנוסף ל<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316610260\" data-slug=\"or-hatorah-hb\" data-id=\"8316610260\">אוה\"ת</a> כאן) לקו\"ת חוקת נז, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' א'יט. מאמרי אדה\"א ויקרא ח\"ב ריש ע' תתלד. וש\"נ. דברים ח\"ד ע' א'תע. וש\"נ.\n\n<b>א</b>  <b>ומהם</b>: לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010090\" data-slug=\"or-hatorah-hb\" data-id=\"8159010090\">אוה\"ת</a> כאן. חוקת [מהדורת תשנ\"ח] ע' תתפט4. וראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רב."]]],[2000470176,"וע' מענין מעלת התו' באגה\"ק ד\"ה דוד זמירות<sup data-n=\"958\">623</sup> קרית להו, שיש בחי' בתורה שלא ידע אנוש ערכה<sup data-n=\"959\">624</sup>, א\"כ גם אותיות התו' הם גבוה יותר והיינו בחג\"ת, וכן בטעמים הא' הטעם המושג בשכל והשגה וכענין מ\"ט דר\"מ<sup data-n=\"960\">625</sup>, וכן אמרם ז\"ל ר\"ש דרש טעמי' דקרא<sup data-n=\"961\">626</sup> וזהו בחי' הטעמים שבחכ' אמנם יש בחי' טעמים שהם למעלה מהשגה ושכל המושג ונק' טעם הכמוס וכמ\"ש מזה בבה\"ז נשא<sup data-n=\"962\">627</sup> על המאמר בחללא דגלגלתא קרומא דאוירא דמו\"ס כו', וע\"ד סדכ\"ס<sup data-n=\"963\">628</sup>, כי חו\"ב נק' ג\"כ סתימין כמ\"ש הנסתרות לה' אלקינו<sup data-n=\"964\">629</sup> &lt;36&gt;\nּ הם חו\"ב ועכ\"ז זהו בחי' הטעמים שבחכ', רק שלגבי המדות הם סתימין, אך סדכ\"ס שגם מהסתימין הם סתום ונעלם וז\"ע בחי' מו\"ס, וע' בלק\"ת בחוקתי בד\"ה אם בחוקתי בענין שתוק כך עלה במח'<sup data-n=\"965\">630</sup>, ובהביאור ע\"פ אני הוי' אלקיכם דפ' ציצית דרוש השני<sup data-n=\"966\">631</sup>, וז\"ע הטעמים שהם בע\"י וא\"א, וז\"ע חכמות בחוץ תרונה בחי' רננא דאורייתא<sup data-n=\"967\">633</sup> פי' חכמות הם חכ' דאצי' וח\"ס<sup data-n=\"968\">632</sup>, זהו ע\"י תרונה בחי' שיר שבתורה כו', והנה ב' בחי' אלו דאותיות שנתגלו בתושבע\"פ וטעמים שיתגלו לע\"ל זהו בחי' אירוסין ונשואין וע' מזה בלק\"ת בד\"ה תורה צוה<sup data-n=\"969\">634</sup>, ועפ\"ז יובן מ\"ש במצה דעכשיו לחם עני<sup data-n=\"970\">635</sup> כי בחפזון יצאת<sup data-n=\"971\">636</sup>, ולע\"ל כי בחפזון לא תצאו כי הולך לפניכם ה', ובדרז\"ל במד\"ר<sup data-n=\"972\">637</sup> יצ\"מ הוא וב\"ד, אבל לע\"ל אני לבדי, והיינו כי באירוסין שייך ב\"ד<sup data-n=\"973\">638</sup> בחי' תנאים אם בחוקתי תלכו<sup data-n=\"974\">639</sup>, משא\"כ בנשואין, וענין החפזון ע' בסש\"ב פל\"א לברוח מן הרע, אבל לע\"ל ואת רוה\"ט אעביר<sup data-n=\"975\">640</sup>, וע' בלק\"ת פ' אמור בד\"ה וספרתם לכם ושם פ\"ג שיצ\"מ לא הי' רק לנה\"א, אבל נה\"ב לא נתהפכה א\"כ שייך ענין החפזון לברוח מן הרע והיינו ע\"י התלבשות ג' לבושי הנפש בתומ\"צ כמבואר בסש\"ב פי\"ב, ולחם עני היינו בחי' סיהרא<sup data-n=\"976\">641</sup>, אבל לע\"ל הנה",[["958","623","<b>באגה\"ק<sup data-n=\"e56\">ב</sup>. . דוד זמירות</b>: ראה תניא קסא, א."],["959","624","<b>שלא ידע אנוש ערכה</b>: איוב כח, יג."],["960","625","<b>מ\"ט דר\"מ</b>: פסחים מח, סע\"ב. ועוד."],["961","626","<b>ר\"ש דרש טעמי' דקרא</b>: יומא מב, סע\"ב. ועוד."],["962","627","<b>טעם הכמוס. . בבה\"ז נשא</b>: פח, ב ואילך."],["963","628","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["964","629","<b>חו\"ב. . הנסתרות לה' אלקינו</b>: נצבים כט, כח. ת\"ז ת\"י (כה, ב)."],["965","630","<b>בלק\"ת בחוקתי. . במח'</b>: מו, ג."],["966","631","<b>ובהביאור. . דרוש השני</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380510\" data-slug=\"likkutei-torah\" data-id=\"4001380510\">לקו\"ת שלח מט, ג</a>."],["967","633","<b>רננא דאורייתא</b>: ראה זהר בהקדמה ח, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקעא וע' תקפא. תקע\"א ע' ג. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670213\" data-slug=\"torat-chaim\" data-id=\"2300670213\">תו\"ח בראשית ד, א</a> ובהערה 7."],["968","632","<b>חכמות בחוץ תרונה. . חכ' דאצי' וח\"ס</b>: משלי א, כ. ראה זהר תולדות קמא, ב. לקמן המשך מצה זו רפכ\"ג (ומציין ע' מק\"מ שם). מאמרי אדה\"א שמות ח\"א ע' לג."],["969","634","<b>בלק\"ת בד\"ה תורה צוה</b>: ברכה צד, א ואילך."],["970","635","<b>במצה. . לחם עני</b>: באוה\"ת כאן: עוני. לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב כאן: עני כתי'. פ' ראה טז, ג. פסחים קטו, סע\"ב."],["971","636","<b>כי בחפזון יצאת</b>: פ' ראה שם."],["972","637","<b>כי בחפזון לא תצאו. . במד\"ר</b>: ישעי' נב, יב [ושם: לא בחפזון. בדילוג]. שמו\"ר פי\"ט, ו. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380227\" data-slug=\"likkutei-torah\" data-id=\"4001380227\">לקו\"ת אמור לה, ב</a>."],["973","638","<b>ב\"ד</b>: בהמשך הנדפס: כ\"ז. וכנצ\"ל: כבפנים."],["974","639","<b>אם בחוקתי תלכו</b>: בחוקותי כו, ג."],["975","640","<b>ואת רוה\"ט אעביר</b>: זכרי' יג, ב."],["976","641","<b>ולחם עני. . סיהרא</b>: ראה זהר בא מ, א. ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380100\" data-slug=\"likkutei-torah\" data-id=\"4001380100\">לקו\"ת ויקרא ו, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380297\" data-slug=\"likkutei-torah\" data-id=\"4001380297\">שם בהוספות נא, ב</a>. אוה\"ת כאן ע' ב'תקעו.\n\n<b>ב</b>  קו\"א נקרא ג\"כ אגה\"ק — לקו\"ת ד\"ה ויקרא. ועוד. ”הערות\" בסו\"ס התניא (מהדורת קה\"ת תשי\"ד ואילך). ראה לעיל ע' פ."]]],[2000470177,"ישכיל עבדי<sup data-n=\"977\">642</sup> דא סיהרא בזח\"א דקפ\"א שיהי' בבחי' וגבה מאד, והי' אור הלבנה כאור החמה<sup data-n=\"978\">643</sup>, וגם כי ע\"י ב\"ד ש' אלקי' נמשך יציאתם בבחי' לילה, ע' במד\"ר בא ס\"פ י\"ט, משא\"כ מבחי' שלמעלה מש' אלקי' אני לבדי כו', שז\"ע לעת ערב יהי' אור<sup data-n=\"979\">644</sup>.\n<b></b>קיצור. שלא ברכו היינו שלא המשיכו המשכת אוא\"ס בתורה שזהו ע\"י התפלה יהי רצון, והכתרים הם מדומם שבשרשו גבוה יותר ובתושבע\"פ לא נמצא כ\"א על נת\"א, משא\"כ טעמים, ומ\"ש במ\"א שטעמים בחכ' זהו טעם הגלוי ויש טעם הכמוס, שתוק כך עלה במח', מו\"ס, וז\"ע אירוסין ונשואין, ב\"ד, אני לבדי כו'.\n(ךג) <b>והנה</b> כל מה שנת\"ל בענין הזית<sup data-n=\"980\">645</sup>, הנה<sup data-n=\"981\">646</sup> כ\"ז הוא בחי' העלאת מ\"ן מחוץ לפרוכת, והיינו מבי\"ע לאצי', אבל משה הוא בחי' המ\"ד<sup data-n=\"982\">647</sup> שהוא בחי' שושבינא דמלכא<sup data-n=\"983\">648</sup> שהוא הממשיך מ\"ד שנמשך בעולם האצי', כי מ\"ד הוא המברר המ\"ן<sup data-n=\"984\">649</sup>, וזהו ענין תורתו אומנתו<sup data-n=\"985\">650</sup>, ודברי אשר שמתי בפיך<sup data-n=\"986\">651</sup>, מתניתן מלכתא<sup data-n=\"987\">652</sup> כמלך עצמו הגוזר אומר כו' והיא בחי' תורה אור<sup data-n=\"988\">653</sup>, כי הגם שבשרשה התורה היא מבחי' שערות שלמטה מן המצות שהם מבחי' גלגלתא בחי' לבנוניות, ארחין דגלגלתא<sup data-n=\"989\">654</sup>, מ\"מ גילוי התורה היא למעלה מן המצות שהמצות ירדו ונתלבשו בבי\"ע כו', משא\"כ התורה עם היות שהיא פי' וביאור המצות עכ\"ז גם למטה היא בחי' חכ', ולכן במשה כתי' נר תמיד<sup data-n=\"990\">655</sup>, והיינו כי בבי\"ע יש עליות וירידות, משא\"כ באצי' דאיהו וחיוהי חד, ומשה הוא בחי' חכ'<sup data-n=\"991\">656</sup> דאצי', ובחכ' אתברירו<sup data-n=\"992\">657</sup>, וגם י\"ל כי כל מצוה יש לה זמן פרטי כמו אכילת מצה בפסח, וישיבת סוכה בסוכות &lt;37&gt;\nּ דוקא,",[["977","642","<b>הנה ישכיל עבדי</b>: ישעי' נב, יג."],["978","643","<b>והי' אור הלבנה כאור החמה</b>: ישעי' ל, כו. ראה גם סה\"מ תרכט ע' קמג."],["979","644","<b>לעת ערב יהי' אור</b>: זכרי' יד, ז."],["980","645","<b>משנת\"ל בענין הזית</b>: פי\"ג (שמן זית). פי\"ד. פי\"ט."],["981","646","<b>הנה</b>: מכאן ואילך לשון מאמרי אדה\"ז על פרשיות התורה ח\"א ע' שנג (ראה לעיל הערה 172) בשינויים והוספות וכו'."],["982","647","<b>מ\"ן. . המ\"ד</b>: זהר בראשית יז, סע\"ב. יח, רע\"א. ראה גם בענין מ\"ן ומ\"ד מאמרי אדה\"ז תקס\"ג ח\"א ע' קפג ואילך."],["983","648","<b>משה. . שושבינא דמלכא</b>: זהר רע\"מ ויקרא כ, א. מצורע נג, ב. רע\"מ שופטים ערה, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540828\" data-slug=\"torat-chaim\" data-id=\"2300540828\">תו\"ח שמות ח\"א יא, ג</a> הערה 510."],["984","649","<b>מ\"ד הוא המברר המ\"ן</b>: ראה (בנוסף להערה 172) פע\"ח שער התפלה ש\"א, פ\"ז. מאמרי אדה\"א קונטרסים ס\"ע תקמג ואילך. וש\"נ."],["985","650","<b>תורתו אומנתו</b>: שבת יא, א."],["986","651","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא."],["987","652","<b>מתניתן מלכתא</b>: ביצה כח, ב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370128\" data-slug=\"torah-or\" data-id=\"3901370128\">תו\"א וישב כז, ב</a>. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קפט."],["988","653","<b>תורה אור</b>: משלי ו, כג."],["989","654","<b>התורה. . שערות. . המצות. . ארחין דגלגלתא</b>: ראה לעיל פי\"א פיסקא וביאור הענין."],["990","655","<b>נר תמיד</b>: תצוה כז, כ. אמור כד, ב."],["991","656","<b>ומשה. . חכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."],["992","657","<b>ובחכ' אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר היכלות פקודי רנד, סע\"ב. ע\"ח שער דרושי נקודות ש\"ח, פ\"ו. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550161\" data-slug=\"torat-chaim\" data-id=\"2300550161\">תו\"ח תשא ח\"ב שפד, ד</a> ואילך."]]],[2000470178,"ותקיעת שופר בר\"ה, והקרבת הקרבנות בבהמ\"ק וכמ\"ש מזה בתשו' הרשב\"א ז\"ל שבד\"כ נחלקו המצות בג' בחי'<sup data-n=\"993\">658</sup> זמן ומקום וכלים היינו כלי המקדש, אבל בתורה הנה ארז\"ל כל העוסק בתורת עולה<sup data-n=\"994\">659</sup> כאלו הקריב עולה הגם כי אין בהמ\"ק, והלומד הל' פסח או ה' סוכה גם שלא בזמנם ה\"ז כאלו קיים מצותן<sup data-n=\"995\">660</sup> לכן במשה שהוא בחי' תורה אור נא' בו נר תמיד, כי ההמשכה שע\"י התורה היא תמיד בלתי מוגבל בזמן כו', ולכן במשה כתי' ואתה הקרב אליך<sup data-n=\"996\">661</sup> את אהרן אחיך והוא כענין רוצה ה' את יריאיו<sup data-n=\"997\">662</sup>, וזהו ואתה תצוה, ואתה הוא בחי' חכ'<sup data-n=\"998\">664</sup> ויקחו אליך שמן זית זך<sup data-n=\"999\">663</sup>, לגבי משה תחלה, ומשם יורד לבי\"ע כי התורה דברה בענין ההתחלה כסדר המדרגות תחלה באצי' ואח\"כ בבי\"ע, שז\"ע הכח שיש לאהרן להעלות שהוא חקת עולם מאת בנ\"י<sup data-n=\"1000\">665</sup>, מאת<sup data-n=\"1001\">666</sup> הוא בחי' אותיות התו' כי התורה צ\"ל לימודה באותיות<sup data-n=\"1002\">667</sup> דוקא והרהור לאו כדבור דמי<sup data-n=\"1003\">668</sup>, שהאותיות נק' סוסים<sup data-n=\"1004\">669</sup> ויש סוסים זכרים וסוסים נקבות<sup data-n=\"1005\">670</sup>, והכח שיש באותיות לפי דאבא יסד ברתא והיינו מבחי' משה ואתה תצוה את בנ\"י, אתה הוא בחי' חכ', תצוה מל' התקשרות<sup data-n=\"1006\">671</sup> ומשם הוא נר תמיד למעלה מן הזמן, כי הזמן מתחיל בבחי' מל'<sup data-n=\"1007\">672</sup> מלך מלך ימלוך<sup data-n=\"1008\">673</sup> כו', ולכן",[["993","658","<b>בתשו' הרשב\"א ז\"ל. . המצות בג' בחי'</b>: ראה שו\"ת הרשב\"א ח\"א סו\"ס צד. מאמר על ישמעאל מהדורת. . ברסלוי 1863 ע' יח ואילך. מובא גם בסה\"מ תר\"ל ס\"ע שה ואילך. תרל\"ג ח\"ב ע' שעה<sup data-n=\"e57\">ג</sup>. תרל\"ח ע' תקיז."],["994","659","<b>כל העוסק בתורת עולה</b>: ראה מנחות קי, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181010\" data-slug=\"likkutei-sichot\" data-id=\"1300181010\">לקו\"ש מסעי כרך יח ע' 413</a>. וש\"נ. ערב פסח כרך לב ע' 37. וש\"נ."],["995","660","<b>והלומד הל' פסח או ה' סוכה גם שלא בזמנם. . קיים מצותן</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת במדבר יג, א</a>. מאמרי אדה\"ז תקס\"ב ח\"א ע' רד. ח\"ב ע' תמו ואילך. ע' תמח ואילך. מאמרי אדה\"א במדבר ח\"ב ע' תקצד. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550597\" data-slug=\"torat-chaim\" data-id=\"2300550597\">תו\"ח ויקהל ח\"ב שצג, א</a>. מאמר ד\"ה וידבר כו' אלה הם מועדי תרל\"ט נדפס בסה\"מ תרל\"ח ע' שלד. וש\"נ."],["996","661","<b>ואתה הקרב אליך</b>: תצוה כח, א."],["997","662","<b>רוצה ה' את יריאיו</b>: תהלים קמז, יא."],["998","664","<b>ואתה. . חכ'</b>: ראה (בנוסף להערה 172) סידור שחרית לט, ג. ש\"א עט, א ובהערה 5."],["999","663","<b>ואתה תצוה. . ויקחו אליך שמן זית זך</b>: תצוה כז, כ [בדילוג]."],["1000","665","<b>חקת עולם מאת בנ\"י</b>: תצוה כז, כא [בדילוג]."],["1001","666","<b>מאת בנ\"י מאת</b>: בהמשך הנדפס: ואת בנ\"י את. בבוך 1824 מאת ב\"י א\"ת."],["1002","667","<b>התורה צ\"ל לימודה באותיות</b>: ראה הל' ת\"ת לאדה\"ז פ\"ב, הי\"ב. מאמרי אדה\"ז תקס\"ז ע' מ ואילך. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540721\" data-slug=\"torat-chaim\" data-id=\"2300540721\">תו\"ח וארא ח\"א פ, ג</a>. וש\"נ. לקמן מאמר ד\"ה סמכוני באשישות ובהערה 78. המשך מצה זו פי\"ז ובהערה 541. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות על יד הערה 96. הנחה ד\"ה מצה זו על יד הערה 58. הנחה ד\"ה גל נעול על יד הערה 28."],["1003","668","<b>והרהור לאו כדבור דמי</b>: ברכות כ, סע\"ב."],["1004","669","<b>שהאותיות נק' סוסים</b>: ראה ת\"ז בהקדמה ח, א. לקמן המשך מצה זו פ\"ג. ספכ\"ד. מאמרי אדה\"ז תקס\"ט ע' י ובנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540280\" data-slug=\"torat-chaim\" data-id=\"2300540280\">תו\"ח בשלח ח\"א קמג, א</a> ובהערה 69. סה\"מ תרל\"ח ע' כד. וש\"נ."],["1005","670","<b>סוסים זכרים וסוסים נקבות</b>: ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן ובהערה 94."],["1006","671","<b>תצוה מל' התקשרות</b>: ראה גם מאמרי אדה\"ז כאן. תו\"א כאן בהמאמר פב, א."],["1007","672","<b>הזמן. . מל'</b>: ראה שער היחוד והאמונה פ\"ז. הנסמן במאמרי אדה\"א דברים ח\"א ע' קלה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540899\" data-slug=\"torat-chaim\" data-id=\"2300540899\">תו\"ח בשלח ח\"א רלד, א</a>. וש\"נ."],["1008","673","<b>מלך מלך ימלוך</b>: ראה זהר בראשית לד, א. אוה\"ת סידור ע' פג ואילך.\n\n<b>ג</b>  <b>ושם</b>: וכמ\"ש בתשו' הרשב\"א באל\"ף רנ\"ה סוף תשו' צ\"ד."]]],[2000470179,"מ\"ע שהזמן גרמא נשים פטורות<sup data-n=\"1009\">674</sup> כו', ואח\"כ יערוך אותו אהרן מבחי' חוץ לפרוכת ג\"כ כו'.\n<b></b>קיצור. מחוץ לפרוכת הוא מבי\"ע לאצי', אבל משה מ\"ד דאצי', ולכן כתי' בו נר תמיד דאיהו וחיוהי חד ובחכ' אתברירו, וזהו ואתה חכ' תצוה תקשר את בנ\"י, ויקחו אליך דוקא ומשם יורד לבי\"ע, את אותיות, והכח שיש באותיות לפי דאבא יסד ברתא, ומשם נר תמיד למעלה מבחי' הזמן כו', ואח\"כ יערוך אהרן מבחי' חוץ לפרוכת כו'.",[["1009","674","<b>מ\"ע שהזמן גרמא נשים פטורות</b>: קדושין כט, א במשנה. ראה גם סה\"מ תרל\"ח ע' קנח ואילך. וש\"נ."]]],[2000470180,"<h3>נעשה אדם</h3>\n<b></b><b>בס\"ד. ו' אדר תר\"מ א\"א בני מ\"מ שי' בסעודת בר מצוה</b>\n<b></b>בצלמנו כדמותנו, זה כה יחו\"ע, במצות - ג\"פ קיצורים\nוא\"ו אדר תר\"ם א\"א בני מ\"מ שי' בסעודת בר מצוה\n<b>נעשה</b> אדם<sup data-n=\"1010\">1</sup> בצלמנו כדמותנו, ואיתא ביר\"ק<sup data-n=\"1011\">3</sup> תפילין אות ג' שהביא בשם תיקוני זהר<sup data-n=\"1012\">4</sup>, נעשה אדם בצלמנו כדמותנו<sup data-n=\"1013\">2</sup> אם הוא מניח תפילין דיד ותפילין",[["1010","1","<b>נעשה אדם</b>: אודות מאמר זה נרשם בספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e58\">א</sup>: ”בצלמנו כדמותנו, זה כה, יחו\"ע, במצות — ג\"פ קיצורים\".\nמאמר ד\"ה זה דשנת תרס\"ג<sup data-n=\"e59\">ב</sup> מיוסד על מאמר זה. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151302\" data-slug=\"likkutei-sichot\" data-id=\"1300151302\">לקו\"ש וישלח כרך טו ע' 289</a> (ס\"ב) ואילך.\nמתחילה כתב כ\"ק אדמו\"ר מהר\"ש הפתיחה למאמר זה: ”ענין התפילין הנה\" והעביר קו בתיבות אלו וממעל לשורה כתב כבפנים.\n2 דרושים שאמר כ\"ק אדמו\"ר מהר\"ש אז בפתיחה בן פורת יוסף — ראה לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב.\nבנידון הכותרת שמופיע בריש המאמר נרשם בספר התולדות שם הערת כ\"ק אדמו\"ר: כ\"כ בכתי\"ק אדמו\"ר מהר\"ש נ\"ע על מאמר זה. ”א\"א\" — אולי פי' ”אמר אותו\". ראה גם לקמן ע' תעה.\nבהכותרת: ”מ\"מ\" להעיר מרשימות כ\"ק אדמו\"ר יומן ב' כ\"ו ניסן תרצ\"א (חוב' ה' ס\"ע 31) ד\"ה [מהברמ\"צ.\nלהעיר מרשימות יומן מאריענבאד תרצ\"ד (חוב' קפא ע' 6): הצ\"צ לכל ברמ\"צ הי' אומר דרוש מתחיל ”נעשה אדם\". לקו\"ש שם ובהערה 12.\nאודות תאריך יום הולדתו הנה בהכותרת כאן נרשם: ו' אדר. וכ\"ה בס' התולדות שם ובע' 22. לקמן בהנחת כ\"ק אדמו\"ר מהורש\"ב ד\"ה בן פורת בהכותרת נרשם: יום ד' פרשת תצוה תר\"ם (שחל וא\"ו אדר). ואילו ב”היום יום\" (בשלשלת היחס פ\"ד ע' 8) נרשם ז' אדר. ראה גם ס' התולדות שם ע' 79 (סה\"ש תש\"ה ע' 52)<sup data-n=\"e60\">ג</sup>."],["1011","3","<b>ביר\"ק</b>: בילקוט ראובני קטן<sup data-n=\"e61\">ד</sup> לר' אברהם ראובן בר' האשקי [יהושע] כ\"ץ פראג ת\"כ."],["1012","4","<b>תיקוני זהר</b>: תמ\"ז פג, ב."],["1013","2","<b>נעשה אדם בצלמנו כדמותנו</b>: בראשית א, כו.\n\n<b>א</b>  קה\"ת תש\"ז — ברשימת מאמרי שנה זו — ע' 51.\n\n<b>ב</b>  סה\"מ תרס\"ג ח\"א ע' רסב* — ובמהדורת תשנ\"ד ע' קפ**. ח\"ב ע' רפג.\nושם: הבר מצוה של ב\"ד.\nושם: הבר מצוה של בני.\n\n<b>ג</b>  ראה עוד אודותיו בס' התולדות ע' 22 ואילך.\n\n<b>ד</b>  השם ”קטן\" דספר זה מופיע על השער דיל\"ר (הגדול) עה\"ת."]]],[2000470181,"ברישא בכל יומא דאינון לקבל זכור ושמור<sup data-n=\"1014\">5</sup> איהו בצלמנו כדמותנו וא\"ל לאו, ולכאו' צ\"ל איך ע\"י תפילין עי\"ז איהו בבחי' בצלמנו כדמותנו, ויובן בהקדם תחלה ענין בצלמנו כדמותנו, הנה ההפרש בין צלם לדמות, שהצלם הוא כמו עצם הדבר ממש כמו שהוא, והדמות הוא רק מראה הדבר ההיא לבד, ועד\"מ כשעושים צלם איזה אדם חותכים מעץ או מאבן צלם איש ההוא בעובי גופו ובחיתוך אברים או כשמציקים מאיזה מין מתכת ג\"כ מציקים אדם צלם גופו כמ\"ש בציור פרטי אבריו של אדם ההוא במדת חוטמו ארכו ועוביו הכל כמו שהוא, משא\"כ כשמציירין דמות האדם לא נמצא שום דבר בעוביו כ\"א שמצויר בדיו שחור ע\"ג לבן וה\"ז נראה תמונת האדם, והגם שגם בתמונת האדם ג\"כ ניכר כל פרטי אבריו הן בארכם והן ברחבם אמנם אינם רק תמונת דבר ההיא ולא כמו שהוא בחיתוך אבריו בדרך מדידה שהיקף אבר יד או רגל ישתוה לעצם היד או הרגל אלא שרק נראה מדתו ע\"י הציור לבד ולא ממש, שלא נמצא כלל שום ממשות בדמות, כ\"א בצלם יש ממשות הדבר ההיא כו', או עד\"מ האדם העומד נגד המראה (שפיגל בל\"א) שנראה בה תמונת האדם ממש כמ\"ש, אבל באמת איננו שם כלל וכלל, ולכן כשעובר האדם ממקום מצבו נגד המראה לא ישאר שם רשימה כלל בהמראה, והיינו מפני שגם תחילה לא הי' בעצם כ\"א תמונתו לבד, ולכן כשהולך הלאה או הופך א\"ע על צד אחר לא נראה כלל, משא\"כ צלם איש ה\"ה תמיד בצלמו כמו האיש ההוא בכל פרטיו כשישנו שם וכשאינו שם שוה ממש בלי שום שינוי כו', וזהו שרש ההפרש בין נבואת משה לנבואת שארי כל הנביאים, שכל הנביאים נתנבאו בכה<sup data-n=\"1015\">6</sup> נוסף עליהם משה שנתנבא בזה, פי' כה הוא כדמותנו שהוא בחי' דמות הדבר ההיא לבד ולא העצם, וכמ\"ש וביד הנביאים אדמה<sup data-n=\"1016\">7</sup>, שנראה להם במראה הנבואה דמות הדבר, ולכן נק' בשם אספקלריא שאינה מאירה<sup data-n=\"1017\">8</sup> היינו כמו המראה שאינו עצם הדבר כלל כ\"א דמותו לבד כנ\"ל, משא\"כ משה נתנבא בזה הוא בחי' עצם הדבר כמו שהוא, וכמ\"ש פה אל פה<sup data-n=\"1018\">9</sup> אדבר בו ומראה ולא בחידות, פי' כי החידה הוא שאין אומרים לו הדבר כמו שהוא, רק מלובש בדבר אחר שמסתיר על הבנת הדבר ועכ\"ז אם הוא חכם ה\"ה מבין מתוך הלבשת החידה עצם הדבר, וה\"ז כמו המראה שהיא המראה תמונת האדם, אבל משה רבינו ראה באספקלריא<sup data-n=\"1019\">10</sup> המאירה היינו כמו שרואים דרך זכוכית לבינה שרואים בה דרך אור ישר עצם מהות הדבר כמו שהוא כו'.\n<b></b>קיצור. צלם הוא שנצטייר בעץ או באבן או במתכת עצם מהות הדבר, משא\"כ דמות הוא גוון לבד או כמו שנראה במראה, שאינו כמו עצם הדבר, וזהו ההפרש בין משה לשאר הנביאים שכל הנביאים נתנבאו בכה אספשא\"מ, ומשה נתנבא בזה אספה\"מ.",[["1014","5","<b>זכור ושמור</b>: יתרו כ, ח. ואתחנן ה, יב."],["1015","6","<b>שכל הנביאים נתנבאו בכה</b>: ראה ספרי ר\"פ מטות הובא ברש\"י שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540144\" data-slug=\"torat-chaim\" data-id=\"2300540144\">תו\"ח בשלח ח\"א קמד, ב</a> הערה 29."],["1016","7","<b>וביד הנביאים אדמה</b>: הושע יב, יא."],["1017","8","<b>אספקלריא שאינה מאירה</b>: יבמות מט, ב."],["1018","9","<b>פה אל פה</b>: בהעלותך יב, ח."],["1019","10","<b>משה. . באספקלריא המאירה</b>: יבמות שם. ראה גם תו\"ח ח\"ש קלא, ד."]]],[2000470182,"(ב) <b>ושרש</b> ענין בצלמנו כדמותנו, הנה כה שהוא בחי' כדמותנו הוא בחי' מל'<sup data-n=\"1020\">11</sup>, וזה הוא בחי' ת\"ת<sup data-n=\"1021\">12</sup>, שנמצא בחי' בצלמנו הוא בחי' ז\"א, וכדמותנו הוא בחי' מל', ובעבודה הוא בחי' יחו\"ע ויחו\"ת<sup data-n=\"1022\">13</sup>, בצלמנו הוא בחי' יחו\"ע, וכדמותנו הוא בחי' יחו\"ת<sup data-n=\"1023\">14</sup>, ושרש הענין הוא דכתי' לך ה' הגדולה והגבורה<sup data-n=\"1024\">15</sup> שמדת גדולתו ית' וכן מדת גבורתו ית' בטלים בתכלית באוא\"ס ב\"ה, וכן כל המדות הם בתכלית הביטול לאוא\"ס ב\"ה, וזהו לך שעולה מספרו חמשים<sup data-n=\"1025\">16</sup> שע\"ב<sup data-n=\"1026\">17</sup> שכמו השער משמש כניסה ויציאה<sup data-n=\"1027\">*18</sup> כך הם השערים דבינה שבהם נכנסים המדות להבטל באוא\"ס ב\"ה עצומ\"ה, והיינו שבינה הוא בחי' השגה בהתבוננות גדולת א\"ס איך שכולא קמי' כלא חשיב<sup data-n=\"1028\">18</sup>, ולית אתר פנוי מיני'<sup data-n=\"1029\">19</sup>, וע\"י השגה זו מתבטלת המדה מבחי' חפצה ורצונה לאהוב איזה דבר שתהי' בחי' אהבה זו בבחי' כליון לאוא\"ס, ולהיות כי ז' מדות נחלקים כ\"א לז' שעולה מספרם מ\"ט, לכן יש מ\"ט שע\"ב<sup data-n=\"1030\">*20</sup> היינו לכל פרט מדה יש שער שהוא בחי' התבוננות פרטיות בהשגת אוא\"ס ב\"ה איך שאני הוי' לא שניתי<sup data-n=\"1031\">20</sup> וכולא קמי' כלא חשיב שעי\"ז תהי' המדה זו בבחי' לך ה' הממלכה<sup data-n=\"1032\">21</sup>, ולכאו' צ\"ל למה כפל לאמר פעם ב' לך<sup data-n=\"1033\">22</sup>, דהל\"ל בפסוק הראשון<sup data-n=\"1034\">23</sup> כשאמר פעם הא' לך, גם תיבת הממלכה ג\"כ, אלא ע\"כ בהכרח לומר דאם<sup data-n=\"1035\">24</sup> היות שגם בחי' הממלכה בטל וטפל בבחי' לך עכ\"ז אינו כמו הביטול דבחי' המדות דז\"א, כ\"א באו\"א, והיינו שיש ב' בחי' בענין הביטול<sup data-n=\"1036\">25</sup>, הא' הוא בחי' ביטול היש לאין שהוא ג\"כ ביטול שמבטל בחי' ישותו וגשמיותו נגד בחי' האין המהוה היש, ועכ\"ז אינו בחי' ביטול אמיתי לגמרי כ\"א יש ובטל, והיינו שמבטל בחי' ישותו וחשיבותו ועכ\"ז הנה הוא בבחי' איזה מציאות, ויש מי שבטל ולא נתבטל לגמרי ע\"ד כמו בחי' הביטול דמ\"ה<sup data-n=\"1037\">26</sup> שבטל",[["1020","11","<b>כה. . מל'</b>: ראה פרדס שעה\"כ שכ\"ג, פי\"א מערכת כה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540244\" data-slug=\"torat-chaim\" data-id=\"2300540244\">תו\"ח בא ח\"א צח, א</a>. וש\"נ."],["1021","12","<b>וזה. . ת\"ת</b>: ראה פרדס שעה\"כ שכ\"ג, פ\"ז מערכת זה. מאו\"א מערכת זה ס\"ח."],["1022","13","<b>יחו\"ע ויחו\"ת</b>: זהר בהקדמה יב, א."],["1023","14","<b>בצלמנו. . יחו\"ע וכדמותנו. . יחו\"ת</b>: ראה אוה\"ת מטות ע' א'רנה. וש\"נ."],["1024","15","<b>לך ה' הגדולה והגבורה</b>: דבהי\"א כט, יא."],["1025","16","<b>לך. . חמשים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550228\" data-slug=\"torat-chaim\" data-id=\"2300550228\">תו\"ח פקודי ח\"ב תמג, ד</a>. וש\"נ. בהערה הבאה."],["1026","17","<b>חמשים שע\"ב</b>: ר\"ה כא, ב. ראה גם שעה\"י קלא, ב ובהערה 34. סה\"מ תרכ\"ז ע' קעב. וש\"נ."],["1027","*18","<b>השער משמש כניסה ויציאה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380821\" data-slug=\"likkutei-torah\" data-id=\"4001380821\">לקו\"ת פ' ראה כו, ב</a>. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה עטרת תפארת שיבה על יד הערה 40 (ובהנחת כ\"ק אדמו\"ר מהורש\"ב שם על יד הערה 30)."],["1028","18","<b>שכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1029","19","<b>ולית אתר פנוי מיני'</b>: ראה ת\"ז תנ\"ז צא, ב. ת\"ע קכב, ב. ס' האמונות והדעות לרס\"ג מ\"ב, פי\"ג. תניא פכ\"א ובמ\"מ הגהות והע\"ק לשם. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>. שם בהוספות נב, ג."],["1030","*20","<b>ז' מדות. . מ\"ט שע\"ב</b>: ראה גם לעיל הערה 17. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה עטרת תפארת שיבה ובהערה 46."],["1031","20","<b>שאני הוי' לא שניתי</b>: מלאכי ג, ו."],["1032","21","<b>לך ה' הממלכה</b>: דבהי\"א כט, יא."],["1033","22","<b>כפל לאמר פעם ב' לך</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ס\"ע תתפא ואילך. וש\"נ."],["1034","23","<b>בפסוק הראשון</b>: כ\"ה בהכת\"י."],["1035","24","<b>דאם</b>: כ\"ה בכ\"מ — ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["1036","25","<b>ב' בחי' בענין הביטול</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370514\" data-slug=\"torah-or\" data-id=\"3901370514\">תו\"א ויקהל קטו, ב</a>. לקמן המשך מצה זו פל\"ב."],["1037","26","<b>הביטול דמ\"ה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370347\" data-slug=\"torah-or\" data-id=\"3901370347\">תו\"א משפטים עח, ב</a>. לעיל המשך זאת חנוכת המזבח הערה 593."]]],[2000470183,"ממש בלתי שום מציאות ממש, כ\"א ששולל ממנו כל בחי' המציאות עד שאומר ע\"ע מה, היינו שלילה שאיננו שום דבר כלל כ\"א מ\"ה ביטול, אבל היש<sup data-n=\"1038\">*27</sup> הוא שהוא מכיר א\"ע ליש רק שהוא בטל ואינו מחשיב ישותו נגד האין המהוה, וה\"ז ג\"כ לך שהרי המהוה הוא אוא\"ס ב\"ה, שהרי אם מתכנשין כל באי עולם<sup data-n=\"1039\">27</sup> אינם יכולים לברוא אפי' כנף יתוש א', ונמצא כי הבריאה יש מאין ה\"ז בחיק הבורא לבד ולא בחיק הנבראי' ולזאת בחי' האין המהוה היש הוא ג\"כ לך, אבל אינו כמו בחי' לך דביטול המדות שהם בטלים לך היינו לבחי' אוא\"ס שקדוש ומובדל מגדר בחי' עולמות שהו\"ע בחי' לך ממש כו', ולכן חלקם הכתוב שבחי' הממלכה היינו מ\"ש מלכותך מל' כ\"ע<sup data-n=\"1040\">28</sup> מקור המהוה בי\"ע זה ג\"כ בטל לך אבל זהו בחי' ביטול היש לאין, אבל בחי' ב' בענין הביטול והוא בחי' ביטול אמיתי בחי' ביטול דמ\"ה שהוא בחי' ביטול לגמרי מכל וכל עד שאינו בבחי' מהות כלל וכלל כו', וזהו ב' בחי' הביטול שנת\"ל, וזהו בצלמנו וכדמותנו, כדמותנו הוא בחי' ביטול היש, ובצלמנו הוא בחי' ביטול אמיתי בחי' מ\"ה, וזהו בחי' יחו\"ע ויחו\"ת כו'.\n<b></b>קיצור. בצלמנו כדמותנו יחו\"ע ויחו\"ת ביטול היש וביטול אמיתי ב\"פ לך נגד ב' בחי' הביטול הנ\"ל.\n(ג) <b>והנה</b> אדם בגימ' מ\"ה<sup data-n=\"1041\">29</sup>, וזהו דכתי' ועל דמות הכסא<sup data-n=\"1042\">30</sup> דמות כמראה אדם עליו מלמעלה, ולכאו' צ\"ל הלא אין לו דמות הגוף<sup data-n=\"1043\">31</sup> ולא גוף, ולא נערוך אליו קדושתו<sup data-n=\"1044\">32</sup>, ואיך אמר דמות כמראה אדם, אך הענין הוא דכתי' זאת התורה אדם<sup data-n=\"1045\">33</sup> שבחי' תורה נק' בשם אדם למעלה, והיינו שכמו האדם הוא הכלול מרמ\"ח אברים ושס\"ה גידים<sup data-n=\"1046\">34</sup> כן בחי' תורה יש בה רמ\"ח מ\"ע<sup data-n=\"1047\">35</sup> כמנין אבריו של אדם<sup data-n=\"1048\">36</sup>, ושס\"ה ל\"ת כמנין גידים שבאדם<sup data-n=\"1049\">37</sup>, וזהו הנק' כמראה אדם, ופי' כמראה אדם ולא בחי' אדם ממש, והיינו כי בעצמיות אוא\"ס ב\"ה אינו נוגע כלל וכלל,",[["1038","*27","<b>היש</b>: אוצ\"ל: ביטול היש."],["1039","27","<b>אם מתכנשין כל באי עולם</b>: ראה ירושלמי סנהדרין ספ\"ז. ספרי ואתחנן ו, ה. ב\"ר פל\"ט, יד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261455\" data-slug=\"likkutei-sichot\" data-id=\"1300261455\">לקו\"ש משפטים כרך כו ע' 366</a>."],["1040","28","<b>מלכותך מל' כ\"ע</b>: תהלים קמה, יג."],["1041","29","<b>אדם בגימט' מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670152\" data-slug=\"torat-chaim\" data-id=\"2300670152\">תו\"ח בראשית ט, א</a> הערה 14."],["1042","30","<b>ועל דמות הכסא</b>: יחזקאל א, כו."],["1043","31","<b>אין לו דמות הגוף</b>: ע\"פ פיוט יגדל. פיה\"מ להרמב\"ם מס' סנהדרין פ\"י היסוד הג'. ראה גם סה\"מ תרל\"ח ע' צג. ע' ריז. וש\"נ. לקמן מאמר ד\"ה סמוכים לעד פ\"א (ובהנחת כ\"ק אדמו\"ר מהורש\"ב שם על יד הערה 18). לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כנשר יעיר קנו על יד הערה 7."],["1044","32","<b>ולא נערוך אליו קדושתו</b>: פיוט יגדל. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370280\" data-slug=\"torah-or\" data-id=\"3901370280\">תו\"א בשלח סב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380647\" data-slug=\"likkutei-torah\" data-id=\"4001380647\">לקו\"ת (מטות פא, ב</a>) <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540220\" data-slug=\"torat-chaim\" data-id=\"2300540220\">יו\"כ ע, א</a>. תו\"ח בשלח ח\"א קסג, א. וש\"נ."],["1045","33","<b>זאת התורה אדם</b>: חוקת יט, יד. ראה זהר רע\"מ משפטים קיז, ב. צו כט, ב."],["1046","34","<b>האדם. . מרמ\"ח אברים ושס\"ה גידים</b>: אהלות פ\"א, מ\"ח. תרגום יוב\"ע בראשית א, כז. זהר וישלח קע, ב."],["1047","35","<b>רמ\"ח מ\"ע. . ושס\"ה מל\"ת</b>: מכות כג, סע\"ב."],["1048","36","<b>רמ\"ח מ\"ע. . אדם</b>: מכות שם."],["1049","37","<b>ושס\"ה ל\"ת. . שבאדם</b>: ראה תיוב\"ע וזהר שבהערה 34."]]],[2000470184,"וכמארז\"ל וכי מאי איכפת לי' להקב\"ה אם שוחט מן העורף או שוחט מן הצואר אלא שלא ניתנו המצות אלא לצרף בהם את הבריות<sup data-n=\"1050\">38</sup>, וע\"ז אמרו כל מצותיך צדק<sup data-n=\"1051\">39</sup> שכל המצות דציוה לנו הקב\"ה ה\"ז בדרך צדקה לבד, ולכן נק' כמראה אדם, שכבי' הרי הוא מתלבש בבחי' אדם להיות נק' כמראה אדם כו', ונמצא מובן כי האדם המקיים תומ\"צ ה\"ה בצלמנו דבחי' כמראה אדם הנ\"ל, וכדמותנו קאי על בחי' המצות שנתלבשו בדברים גשמיי' שעלי' נא' הציבי לך ציונים<sup data-n=\"1052\">40</sup> שהם רק ציון וסימן על הדבר, עד\"מ תפילין שלמטה ה\"ה רק ציון וסימן על בחי' ד' מוחין<sup data-n=\"1053\">41</sup> דז\"א שזהו רק כדמותנו, ועכ\"ז ע\"י הצדקה שעשה לנו הקב\"ה האדם העושה אותם מצד בחי' כח המצוה שיש בהציווי דמצות נעשה בצלמנו ממש בחי' כמראה אדם הנ\"ל, וזהו רק<sup data-n=\"1054\">42</sup> זכור ושמור זכור לדכורא בחי' בצלמנו ושמור לנוק'<sup data-n=\"1055\">43</sup> בחי' כדמותנו, והנה ארז\"ל הוקשה כל התורה כולה לתפילין<sup data-n=\"1056\">44</sup> וזהו שאמר בתקונים שע\"י הנחת תפילין דרישא ובזרוע עי\"ז הוא בצלמנו כדמותנו להיות כי כל התורה הוקשה לתפילין כו', ובד\"פ תש\"ר זהו בצלמנו, ותש\"י זהו כדמותנו שתש\"י הוא בחי' מוחי' דנוק' ובחי' תש\"ר הם בחי' מוחי' דז\"א<sup data-n=\"1057\">45</sup>, וזהו זכור ושמור זו\"נ והם בחי' בצלמנו כדמותנו וע\"י הנחתם נעשה אדם שהוא בצלמנו כדמותנו, ולכן מצות הנחת תפילין כשנעשה י\"ג שנה ויום אחד<sup data-n=\"1058\">46</sup>, היינו כשנעשה איש<sup data-n=\"1059\">47</sup> בחי' אדם<sup data-n=\"1060\">48</sup>, ויום א' להמשיך בחי' אחד שהוא ג\"כ י\"ג<sup data-n=\"1061\">49</sup> כו'.",[["1050","38","<b>וכי מאי. . לצרף בהם את הבריות</b>: ראה תנחומא שמיני ז-ח. ב\"ר רפמ\"ד. אוה\"ת שמיני ע' נב ואילך. המשך מים רבים תרל\"ו ע' קטו. סה\"מ תרל\"ח ע' מח ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300171426\" data-slug=\"likkutei-sichot\" data-id=\"1300171426\">לקו\"ש אבות כרך יז ע' 415</a> הערה 53. שופטים כרך יט ע' 182 הערה 42."],["1051","39","<b>כל מצותיך צדק</b>: תהלים קיט, קעב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381217\" data-slug=\"likkutei-torah\" data-id=\"4001381217\">לקו\"ת שה\"ש כב, א</a>. סה\"מ תרל\"ח ע' נב. ראה גם (לקמן ח\"ב בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה הא' על יד הערה 47. ד\"ה אני לדודי הב' על יד הערה 30. (בחלק ההנחות) הנחה ד\"ה יפה שעה הא' על יד הערה 44. ד\"ה אני לדודי הב' על יד הערה 24."],["1052","40","<b>הציבי לך ציונים</b>: ירמי' לא, כ. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' על יד הערה 51."],["1053","41","<b>תפילין. . ד' מוחין</b>: ראה זהר ואתחנן רסב, א. סידור שער התפילין ז, א. אמרי בינה שער התפילין קיב, א ואילך. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשח ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ד ע' א'רמא. וש\"נ."],["1054","42","<b>רק</b>: כ\"ה בהכת\"י."],["1055","43","<b>זכור לדכורא. . ושמור לנוק'</b>: זהר בראשית מח, ב. רע\"מ יתרו צב, א."],["1056","44","<b>הוקשה כל התורה כולה לתפילין</b>: ראה קדושין לה, א. סידור ערב שבת קסד, ב. תו\"ח וארא ח\"א סט, ב הערה 423. סה\"מ תרכ\"ט ע' רכה. לקו\"ש חנוכה כרך ה ע' 226."],["1057","45","<b>שתש\"י. . מוחי' דנוק' ובחי' תש\"ר. . דז\"א</b>: ראה גם פע\"ח שער התפילין שער ד, פ\"א. פ\"ו. פ\"ז. אוה\"ת ואתחנן ע' שכג. ע' שכז. ע' שמא ואילך. המשך תער\"ב ח\"ג ע' א'שס."],["1058","46","<b>תפילין. . י\"ג שנה ויום אחד</b>: ראה שו\"ע אדה\"ז הל' תפילין סל\"ז, ס\"ג. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה בן פורת יוסף הא' על יד הערה 58."],["1059","47","<b>י\"ג שנה ויום אחד. . איש</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151302\" data-slug=\"likkutei-sichot\" data-id=\"1300151302\">לקו\"ש וישלח כרך טו ע' 289</a> ואילך. רשימות לפ' וישלח חוב' כא ע' 3 ואילך."],["1060","48","<b>בחי' אדם</b>: ראה לקו\"ש שם ס\"ב."],["1061","49","<b>אחד. . י\"ג</b>: פע\"ח הקדמה לשער השבת שי\"ח, פ\"א."]]],[2000470185,"<b></b>קיצור. מ\"ה אדם רמ\"ח פקודין ושס\"ה ל\"ת, והם כמראה אדם שכבי' מתלבש בהם, וזהו בצלמנו, וכדמותנו זהו המצות כמו שנתלבשו בגשמיות, והוקשה כל התו' לתפילין לכן ע\"י תפילין הוא בצלמנו כדמותנו.",[]],[2000470186,"<h3>סכמוני באשישות</h3>\n<b>בס\"ד. ויק\"פ</b>\n<b>סמכוני</b> באשישות<sup data-n=\"1062\">1</sup> רפדוני בתפוחים<sup data-n=\"1063\">2</sup> כי חולת אהבה אני, זהו מאמר כנס\"י<sup data-n=\"1064\">3</sup> בזמן חורבן בהמ\"ק<sup data-n=\"1065\">4</sup> שנק' חולת אהבה ע\"ש שחולי זה בא כשאינו יכול למלאות חפצו ורצונו וכענין הנז' בגמ' מעשה בא' שהעלה בלבו טינא<sup data-n=\"1066\">5</sup> כו', ושרש ענין החולי הוא מזה שהחיות בא בהעלם ובצמצום, ונמצא מובן שכשישראל אומרים פעמים בכי\"ת<sup data-n=\"1067\">6</sup> אחד ואהבת<sup data-n=\"1068\">7</sup>, שפי' ואהבת שרש התיבה הוא מלשון אבה<sup data-n=\"1069\">8</sup> שהוא לשון רצון ותשוקה נפלאה שהוי' יהי' אלקיך בבחי' הגילוי כו', וגילוי זה א\"א להיות ע\"כ מזה נעשה חולי, וחולי זה נק' חולת אהבה<sup data-n=\"1070\">9</sup> שהיא החולי הבא מבחי' האהבה והתשוקה<sup data-n=\"1071\">10</sup> כו', וכ\"ז הוא בחול, אבל בשבת הנה אמרו שמש בשבת צדקה לעניים<sup data-n=\"1072\">11</sup>",[["1062","1","<b>סמכוני באשישות</b>: לשון מאמר ד\"ה זה במאמרי אדה\"ז כתובים כרך ב ע' צ ואילך בשינויים והוספות. וראה גם שם ע' צח ואילך.\nלפיסקא ראשונה ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200224\" data-slug=\"or-hatorah-hb\" data-id=\"8159200224\">אוה\"ת שה\"ש ח\"א ע' ריא</a> ואילך (נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490245\" data-slug=\"or-hatorah-hb\" data-id=\"8316490245\">אוה\"ת</a> ויקרא כרך ג ע' תשפ].\nלפיסקא ב ג ד ראה גם אוה\"ת שם ע' רכד ואילך מיוסד על מאמרי אדה\"ז הנ\"ל ע' צט ואילך (נדפס גם באוה\"ת ויקרא שם ע' תשצב ואילך].\nהנחת<sup data-n=\"e62\">*</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו).\nבספר התולדות מאדמו\"ר מהר\"ש תש\"ז — ברשימת מאמרי שנה זו — ע' 51 אודות מאמר זה נרשם: ”תפוחים מאכל וריח — ב' קיצורים\""],["1063","2","<b>סמכוני באשישות רפדוני בתפוחים</b>: שה\"ש ב, ה."],["1064","3","<b>מאמר כנס\"י</b>: ראה גם רש\"י שם. זהר שמיני מ, א."],["1065","4","<b>בזמן חורבן בהמ\"ק</b>: לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן: בזמן החורבן. באוה\"ת שה\"ש כאן ע' ריא: בגלות. בספר החקירה ע' 168: בזמן שאין בהמ\"ק קיים. בסה\"מ תר\"ס ע' עז: בזה\"ג."],["1066","5","<b>מעשה בא'. . טינא</b>: סנהדרין עה, א."],["1067","6","<b>פעמים בכי\"ת</b>: תיבת תמיד לא הובא באוה\"ת שה\"ש כאן (ע' ריא). ראה שו\"ע אדה\"ז הל' ק\"ש רסנ\"ח."],["1068","7","<b>אחד ואהבת</b>: ואתחנן ו, ד. ה."],["1069","8","<b>ואהבת. . מלשון אבה</b>: ראה שרש ישע שרש אבה הובא בס' החקירה להצ\"צ מערכת אהב (צב, רע\"א — ובמהדורת תשס\"ג ע' צד). מאמרי אדה\"א הנחות תקע\"ז ע' רסד. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540947\" data-slug=\"torat-chaim\" data-id=\"2300540947\">תו\"ח בשלח ח\"א קצט, ב</a>. וש\"נ. סה\"מ תרכ\"ז ע' עב. וש\"נ."],["1070","9","<b>חולת אהבה. . בחול. . בשבת</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381116\" data-slug=\"likkutei-torah\" data-id=\"4001381116\">לקו\"ת ברכה צז, ב</a>. סידור שער הר\"ח ריא, ד. ריד, ד. מאמרי אדה\"ז נביאים ע' קצז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316500176\" data-slug=\"or-hatorah-hb\" data-id=\"8316500176\">אוה\"ת וירא ח\"א ע' 176</a>. סה\"מ תרל\"ב ח\"א ע' סד. וראה גם מאמרי אדה\"ז על פרשיות התורה ח\"א ס\"ע שעד ואילך."],["1071","10","<b>החולי הבא מבחי' האהבה והתשוקה</b>: ראה גם בהערה שלפנ\"ז. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע ערב ואילך (נו\"ש). ע' רעג (נו\"א). סה\"מ תר\"ס ע' עז."],["1072","11","<b>שמש בשבת צדקה לעניים</b>: תענית ח, ב. ראה סה\"מ תרצ\"ט ע' 232."],["e62","*","<b>ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז. </b>\n<b>*בשולי הע' נרשם</b>: כל המחלה כו' רופאך, והסירותי מחלה*."]]],[2000470187,"דכתי'<sup data-n=\"1073\">12</sup> וזרחה לכם יראי שמי<sup data-n=\"1074\">13</sup> שמש צדקה ומרפא, והיינו שכמו העני דלית לי' מגרמי' כלום וה\"ה תאוב<sup data-n=\"1075\">14</sup> לכל, וכאשר מאיר בחי' שמש הוי'<sup data-n=\"1076\">15</sup> ה\"ה מרפא להחולי הנעשה להעני מצד החסרון, ובאמת מאיר בשבת גם מלמעלה מש' הוי' כמ\"ש אז תתענג<sup data-n=\"1077\">16</sup> על הוי'<sup data-n=\"1078\">17</sup>, ולכן אומרים בשבת ישבעו ויתענגו מטובך<sup data-n=\"1079\">18</sup> שנמשך בחי' הענג מבחי' טוב העצמי, עד שמאיר בכאו\"א שהרי ארז\"ל אינו דומה מאור פניו של אדם<sup data-n=\"1080\">19</sup> בחול למאור פניו של אדם בשבת שמצד בחי' הענג שנמשך בשבת משתנה מאור פניו של אדם שזהו היפך החולי שבא מן ההעדר, ולכן על ימות החול הבקשה של כנס\"י סמכוני ורפדוני באשישות ותפוחים, שכמו החולי סומכי' אותו בריחות טובים לחזק ההרגש כך הנה הוא ית' סומך נופלים ורופא חולים<sup data-n=\"1081\">20</sup> כו'.\n<b>וביאור</b> הענין, הנה אשישות הם ענבי יין כמ\"ש ואוהבי אשישי ענבים<sup data-n=\"1082\">21</sup> שהיין כנוס ועצור בתוכם בהעלם, והוא בחי' יין המשמח אלקים ואנשים<sup data-n=\"1083\">22</sup> היינו להיות ישמח ישראל בעושיו<sup data-n=\"1084\">23</sup> כו', וצ\"ל אם אנשים משמח אלקים במה משמח<sup data-n=\"1085\">24</sup>, אך הענין יובן ע\"פ מ\"ש שמש ומגן ה' אלקים<sup data-n=\"1086\">25</sup>, שלהיות התהוות הנבראים יש מאין זהו ע\"י שם אלקים<sup data-n=\"1087\">26</sup> דוקא, בחי' מגן ונרתק להעלים אור הוי' וקדושתו, ולכן בכל מע\"ב לא נא' כ\"א ש' אלקים כמ\"ש בראשית ברא אלקים<sup data-n=\"1088\">27</sup> ויברא אלקי'<sup data-n=\"1089\">28</sup> שנז'",[["1073","12","<b>דכתי'</b>: וכ\"ה בהמשך תער\"ב ח\"ג ע' א'תסב. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות כאן על יד הערה 12: וכמ\"ש. בסה\"מ תרל\"ב ח\"א ע' סג: שנא' — וכ\"ה בתענית שם."],["1074","13","<b>וזרחה לכם יראי שמי</b>: מלאכי ג, כ."],["1075","14","<b>תאוב</b>: כ\"ה בהכת\"י."],["1076","15","<b>שמש הוי'</b>: נסמן לקמן הערה 25."],["1077","16","<b>בשבת. . אז תתענג</b>: ראה זהר יתרו פח, א. מאמרי אדה\"א שמות ח\"א ע' קצא ואילך (ובהנסמן שם ע' קפה)."],["1078","17","<b>אז תתענג על הוי'</b>: ישעי' נח, יד. ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'קי. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540164\" data-slug=\"torat-chaim\" data-id=\"2300540164\">תו\"ח וארא ח\"א נ, ב</a>. וש\"נ."],["1079","18","<b>ישבעו ויתענגו מטובך</b>: נוסח ”ישמחו במלכותך\" תפילת העמידה לשבת. ראה גם סה\"מ תרל\"ב ח\"א ע' סד."],["1080","19","<b>אינו דומה מאור פניו של אדם</b>: וכ\"ה בהקיצור כאן לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 26 סה\"מ תרכ\"ז ע' תכא ומציין לב\"ר דבסמוך. תרל\"ג ח\"ב ע' תסג. המשך מים רבים תרל\"ו פצ\"ב תרס\"ו ע' רלו וע' רלט. ראה ב\"ר פי\"א, ב. י<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1301470262\" data-slug=\"likkutei-sichot\" data-id=\"1301470262\">לקו\"ש</a> בראשית פ\"ב, ג (רמז טז בסופו). מכילתא וילקו\"ש יתרו כ, יא. אוה\"ת בראשית כרך ז ע' 2322. לקו\"ש תשא כרך לא ע' 194 הערה 28."],["1081","20","<b>סומך נופלים ורופא חולים</b>: נוסח שמו\"ע."],["1082","21","<b>ואוהבי אשישי ענבים</b>: הושע ג, א. ראה רד\"ק שם."],["1083","22","<b>יין המשמח אלקים ואנשים</b>: ס' שופטים ט, יג. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ושאבתם מים פ\"א."],["1084","23","<b>ישמח ישראל בעושיו</b>: תהלים קמט, ב."],["1085","24","<b>אם. . במה משמח</b>: ברכות לה, א."],["1086","25","<b>שמש ומגן ה' אלקים</b>: תהלים פד, יב. ראה (בנוסף להערה 1) שהיחוה\"א רפ\"ד. אוה\"ת (יהל אור) תהלים ס\"ע ש ואילך."],["1087","26","<b>התהוות. . שם אלקים</b>: ראה גם (בנוסף להערה 1). סה\"מ תרל\"ג ח\"ב ע' תל ואילך. וש\"נ. לעיל המשך זאת חנוכת המזבח פ\"י ובהערה 188."],["1088","27","<b>בראשית ברא אלקים</b>: בראשית א, א."],["1089","28","<b>ויברא אלקים</b>: בראשית א, כא. כז."]]],[2000470188,"ל\"ב פעמים ש' אלקים במע\"ב<sup data-n=\"1090\">29</sup> שהן ל\"ב נתיבות חכ'<sup data-n=\"1091\">30</sup> להיות התהוות מציאות הנבראי' נשמות ומלאכים שרפים בבריאה חיות ביצי' ואופנים בעשי'<sup data-n=\"1092\">31</sup> עד בריאת אדם התחתון בגוף ונפש הבהמי שהוא ירידה היותר גדולה ורחוקה, והכל ע\"י ש' אלקי' כמ\"ש ויאמר אלקי' נעשה אדם<sup data-n=\"1093\">32</sup>, והנה ירידה הגדולה הזאת היא צורך עלי'<sup data-n=\"1094\">33</sup> להיות בחי' ביטול היש לאין בבחי' אתכפי' ואתהפכא, ולכאו' צ\"ל ענין עלייה זו אחרי שגם קודם ירידתה והתלבשותה בגוף היתה בטילה בבחי' האין וכמ\"ש חי ה' אשר עמדתי לפניו<sup data-n=\"1095\">34</sup>, וכמ\"ש בכ\"ד שענין העמידה היינו בחי' הביטול<sup data-n=\"1096\">35</sup> בבחי' האין, וא\"כ גם אחר בחי' ביטול היש לאין שנעשה ע\"י ירידתה, היינו הך ומהו העליה כו'. והענין הוא ע\"פ מ\"ש סלסלה ותרוממך<sup data-n=\"1097\">36</sup> ולא הוי ידעי רבנן<sup data-n=\"1098\">37</sup> מאי סלסלה, חזי' דהוה מהפך במזי' והיינו להפריד השערות א\"ל עד מתי אתה מסלסל בשערך, פי' דהנה יניקת השערות הוא מן המוח שבראש<sup data-n=\"1099\">38</sup> ועכ\"ז מקומן וצמיחתן הוא על עצם הגולגולת החופה על המוח, כך התורה בעיון להפריד ההלכות ורמינהו, לא קשי', עי\"ז ותרוממך בעילוי אחר עילוי עד אין קץ, דהנה כתי' והחכמה מאין תמצא<sup data-n=\"1100\">39</sup> ששרש התהוות בחי' החכ' הוא מבחי' האין היינו בחי' האין של הע\"ס והתכללותן במקורם כמ\"ש לך ה' הגדולה והגבורה<sup data-n=\"1101\">40</sup> בבחי' ביטול, אבל עצמותו ית' הוא רם ונשא ונעלה עד אין קץ מגדר וערך הספירות וכמ\"ש בזהר שכל הע\"ס הם רזא דשמא קדישא<sup data-n=\"1102\">41</sup>, רזא דמהימנותא<sup data-n=\"1103\">42</sup> פי' כמו עד\"מ שם האדם אשר יקראו לו אין לו שייכות לעצמיות האדם<sup data-n=\"1104\">43</sup> חכמתו ומדותיו, וז\"ש אני הוי' הוא שמי<sup data-n=\"1105\">44</sup> שפי' במד\"ר שמי שקרא לי אדה\"ר<sup data-n=\"1106\">45</sup> שבשעה שקרא האדם שמות לכל הבהמה והחי', א\"ל הקב\"ה ואני מה שמי א\"ל לך נאה לקרות הוי'<sup data-n=\"1107\">46</sup>, פי'",[["1090","29","<b>ל\"ב פעמים ש' אלקים במע\"ב</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["1091","30","<b>ל\"ב נתיבות חכ'</b>: ראה ס\"י פ\"א, מ\"א. הנסמן במאמרי אדה\"א בראשית ע' ג."],["1092","31","<b>שרפים בבריאה חיות ביצי' ואופנים בעשי'</b>: ראה סידור שער האלול רל, א. מאמרי אדה\"א ויקרא ח\"א ע' מד. וש\"נ. שע\"ת נח, א ובהערה 3."],["1093","32","<b>ויאמר אלקי' נעשה אדם</b>: בראשית א, כו."],["1094","33","<b>ירידה. . צורך עלי'</b>: ראה הנסמן באוה\"ת עקב ע' תפא."],["1095","34","<b>חי ה' אשר עמדתי לפניו</b>: מל\"ב ה, טז. ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 60."],["1096","35","<b>העמידה. . הביטול</b>: ראה סוטה לט, א. וראה גם לעיל שם ובהערה 61."],["1097","36","<b>סלסלה ותרוממך</b>: משלי ד, ח. ראה גם (בנוסף להערה 1) המשך תרס\"ו ע' תט ואילך. לעיל המשך זאת חנוכת המזבח פי\"א ובהערה 221."],["1098","37","<b>ולא הוי ידעי רבנן</b>: ראה מגילה יח, א."],["1099","38","<b>יניקת השערות. . המוח שבראש</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370367\" data-slug=\"torah-or\" data-id=\"3901370367\">תו\"א תצוה פב, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370490\" data-slug=\"torah-or\" data-id=\"3901370490\">קי, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380526\" data-slug=\"likkutei-torah\" data-id=\"4001380526\">לקו\"ת קרח נג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380871\" data-slug=\"likkutei-torah\" data-id=\"4001380871\">תצא לח, סע\"ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380874\" data-slug=\"likkutei-torah\" data-id=\"4001380874\">לט, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381275\" data-slug=\"likkutei-torah\" data-id=\"4001381275\">שה\"ש לו, ד</a>."],["1100","39","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["1101","40","<b>לך ה' הגדולה והגבורה</b>: דבהי\"א כט, יא."],["1102","41","<b>הע\"ס הם רזא דשמא קדישא</b>: ראה זהר יתרו סז, ב ובמפרשים שם. מאמרי אדה\"א הנחות תקע\"ז ע' שנ. וש\"נ."],["1103","42","<b>הע\"ס הם רזא. . דמהימנותא</b>: ראה זהר יתרו שם. שער היחוה\"א ספ\"ט. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380593\" data-slug=\"likkutei-torah\" data-id=\"4001380593\">לקו\"ת בלק סח, ד</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550108\" data-slug=\"torat-chaim\" data-id=\"2300550108\">תו\"ח יתרו ח\"ב רסט, ג</a>."],["1104","43","<b>שם האדם. . האדם</b>: ראה גם לעיל המשך זאת חנוכת המזבח פ\"ד ובהערה 58."],["1105","44","<b>אני הוי' הוא שמי</b>: ישעי' מב, ח."],["1106","45","<b>שמי שקרא לי אדה\"ר</b>: ראה ב\"ר פי\"ז, ד. ראה גם לקמן המשך מצה זו על יד הערה 1445."],["1107","46","<b>הוי'</b>: בב\"ר שם בדפוסים הנפוצים: אדני. אבל בכ\"מ בדא\"ח הובא כבפנים — ראה ב\"ר דפוס אמשטרדם שנת ת\"א-ב ושם: ה'. וכ\"ה במדב\"ר פי\"ט, ג. תנחומא שמיני ו. חוקת ו. ראה גם לקמן המשך מצה זו על יד הערה 1448 ואילך. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 60. מאמרי אדה\"ז כאן ע' צא וע' קא. אוה\"ת שה\"ש כאן ע' רכו (פסח ס\"ע תשצד ואילך). יתרו כרך ז ע' ב'תשכא. סה\"מ תרס\"ג ח\"ב ע' קנא. המשך תרס\"ו כאן ע' תיד. סה\"מ תש\"ט ע' 85 ובהערה לשם. תרל\"ח ע' קסב. וש\"נ."]]],[2000470189,"ששם הוי' יו\"ד חכ'<sup data-n=\"1108\">47</sup> שבסדר ההשתל' ה' בינה כו', אבל עצמותו ית' רם ונשא, וז\"ע הירידה צורך עלי' שהנשמה קודם התלבשותה בגוף היתה כלולה בבחי' האין של הע\"ס והוא כמשל זיו השמש כמו שהוא במקורו, אור הנכלל במאור, אמנם ע\"י בחי' אתכפי' ואתהפכא שהוא בחי' ביטול היש הנה באתעדל\"ת אתעדל\"ע<sup data-n=\"1109\">48</sup> מעורר בחי' ביטול העליון דכולא קמי' כלא חשיב<sup data-n=\"1110\">49</sup> ממש, וליכלל וליבטל בבחי' קדש העליון, וכמ\"ש ואנשי קדש תהיון לי<sup data-n=\"1111\">50</sup>, והיינו לאשתאבא בגופא דמלכא<sup data-n=\"1112\">51</sup> שקדוש ומובדל לגמרי, בחי' אוא\"ס עצמותו שהוא רם ונשא, ואז גם הארת האור יהי' באופן אחר ממש, וכמ\"ש ואור החמה יהי' שבעתים<sup data-n=\"1113\">52</sup> כאור שבעת הימים כו', וז\"ע נכנס יין יצא סוד<sup data-n=\"1114\">53</sup>, כי התורה נתלבשה בדברים גשמיי' ועי\"ז יצא סוד הוא בחי' האהבה המוסתרת שיש בכל נפש מישראל, וז\"ע יין המשמח אלקים פי' כי התהוות הנבראים יש מאין הכל הוא ע\"י שם אלקים כנ\"ל, וע\"י שנכנס יין הוא בחי' יינה ש\"ת<sup data-n=\"1115\">54</sup> שנתלבש בדברים גשמי' כמו שהיין כנוס הוא בענבים עי\"ז יצא סוד בחי' ביטול היש לאין שעי\"ז ותרוממך ליכלל בקדש העליון ממש כנ\"ל, וז\"ע המשמח אלקי' שהשמחה לאלקי' הוא שיוצא מבחי' הצמצומים כו'.\n<b></b>קיצור. חולת אהבה זהו הבא מבחי' האהבה והתשוקה, וכ\"ז בחול, אבל בשבת ישבעו ויתענגו, עד שאינו דומה מאור פניו של אדם כו', ולזאת הבקשה סמכוני באשישות הם ענבים בחי' יין המשמח אלקים ואנשים, והיינו כי הבריאה היא מש' אלקים והמכוון שע\"י יבוא לבחי' ביטול היש לאין, וע\"י התורה ותרוממך ליכלל בקדש העליון ממש, וזהו המשמח הצמצומים דש' אלקי', וזהו נכנס יין יינה ש\"ת יצא סוד בחי' סוד הוי' ליריאיו<sup data-n=\"1116\">55</sup>. ",[["1108","47","<b>יו\"ד חכ'</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["1109","48","<b>באתעדל\"ת אתעדל\"ע</b>: ראה זהר לך פח, א. מאמר ד\"ה לרוקע נדפס במאמרי אדה\"ז תקס\"ב ח\"א ע' קצד [ובמקביליו ובהנסמן במ\"מ לשם]. מאמרי אדה\"א דברים ח\"א ע' קצח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540430\" data-slug=\"torat-chaim\" data-id=\"2300540430\">תו\"ח שמות ח\"א מא, א</a> ובהערה 189."],["1110","49","<b>דכולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה ש\"א, פ\"ז [ז, רע\"א]. מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["1111","50","<b>ואנשי קדש תהיון לי</b>: משפטים כב, ל. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380432\" data-slug=\"likkutei-torah\" data-id=\"4001380432\">לקו\"ת בהעלותך ל, סע\"ג</a> ואילך. יו\"כ סט, ב."],["1112","51","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670390\" data-slug=\"torat-chaim\" data-id=\"2300670390\">תו\"ח בראשית מ, ב</a> הערה 25. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"י על יד הערה 248. מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 139 ואילך. מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' ס."],["1113","52","<b>ואור החמה יהי' שבעתים</b>: ישעי' ל, כו."],["1114","53","<b>נכנס יין יצא סוד</b>: ערובין סה, סע\"א. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680053\" data-slug=\"torat-chaim\" data-id=\"2300680053\">תו\"ח ויחי רלו, ב</a>."],["1115","54","<b>יינה ש\"ת</b>: ע\"ז לה, א."],["1116","55","<b>סוד הוי' ליריאיו</b>: תהלים כה, יד."]]],[2000470190,"רפדוני בתפוחים, יובן ע\"פ מ\"ש וריח אפך כתפוחים<sup data-n=\"1117\">56</sup>, שמעלת ריח התפוח שהוא מאכל המריח ע\"כ גדלה מעלתו גם מבחי' משקה המריח וכמ\"ש בזהר ע\"פ אכלו ריעים<sup data-n=\"1118\">57</sup> לעילא חו\"ב שהארת אור החכ' בבינה להיות התהוות יש מאין נק' אכילה, שזהו לעילא, משא\"כ שתו ושכרו דודים הם לתתא זו\"נ, וכמ\"ש בזהר במ\"א ג\"כ שמיעה בהאי אתר תלי'<sup data-n=\"1119\">58</sup> הכוונה על בחי' מל' עשי' לעילא כו'.\n<b>והנה</b> הריח הוא בחי' מקיף וכמארז\"ל איזהו דבר שהנשמה נהנה<sup data-n=\"1120\">59</sup> ממנה ולא הגוף זה הריח, ולכן הריח אינו נפסק משא\"כ הטעם, ובעבודה זהו שרש ענין מעשה המצות<sup data-n=\"1121\">*60</sup> כמו שהן בשרשן למעלה תרי\"ג מצות דאורייתא<sup data-n=\"1122\">60</sup> וז'<sup data-n=\"1123\">63</sup> מצות דרבנן<sup data-n=\"1124\">62</sup> שהם תר\"ך<sup data-n=\"1125\">61</sup> עמודי אור<sup data-n=\"1126\">64</sup> בחי' כת\"ר ומקיף, וכלליות המצות נק' בשם צדקה כמ\"ש וצדקה תהי' לנו<sup data-n=\"1127\">65</sup> כי נשמור לעשות את כל המצוה, אשר בצדקה נא' וצדקה תרומם<sup data-n=\"1128\">66</sup> כו', ולכן רפדוני בתפוחים כו'.\n<b>אך</b> להבין כפל הסמיכה באשישות ותפוחים, יובן ע\"פ מ\"ש שמאלו תחת לראשי<sup data-n=\"1129\">67</sup> וימינו תחבקני, וכנודע בענין שהם וישפה<sup data-n=\"1130\">68</sup> שיש ב' בחי' ממטה למעלה",[["1117","56","<b>וריח אפיך כתפוחים</b>: שה\"ש ז, ט."],["1118","57","<b>אכלו ריעים</b>: שה\"ש ה, א. זהר ויקרא ד, א."],["1119","58","<b>שמיעה בהאי אתר תלי'</b>: ראה זהר בהר קח, ב. ביאוה\"ז בהר פב, סע\"ב ואילך. מאמרי אדה\"ז תקס\"ב ח\"ב ע' תעא ואילך. סה\"מ תרל\"ח ע' רלג ואילך. תרע\"ח ע' שצו ואילך."],["1120","59","<b>איזה דבר שהנשמה נהנה</b>: ראה ברכות מג, ב. ראה גם (בנוסף להערה 1) לעיל המשך זאת חנוכת המזבח פ\"ח ובהערה 134."],["1121","*60","<b>הריח. . מעשה המצות</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 78."],["1122","60","<b>תרי\"ג מצות דאורייתא</b>: ראה מכות כג, סע\"ב. כללי המצות לר\"י גיקטיליא מערכת שש מאות [צפת תשנ\"ב ע' 208]. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300261512\" data-slug=\"likkutei-sichot\" data-id=\"1300261512\">לקו\"ש יתרו כרך כו ס\"ע 424</a> ואילך. אג\"ק שלו ח\"ג ע' רג."],["1123","63","<b>וז' מצות דרבנן</b>: ראה אגה\"ק סכ\"ט. דרך חיים פנ\"ו. פס\"ד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300291104\" data-slug=\"likkutei-sichot\" data-id=\"1300291104\">לקו\"ש שופטים כרך כט ע' 104</a> ואילך. וש\"נ."],["1124","62","<b>וז' מצות דרבנן</b>: וסימנם: נ\"ע בשמח\"ה — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300211410\" data-slug=\"likkutei-sichot\" data-id=\"1300211410\">לקו\"ש יתרו כרך כא ע' 401</a>. אג\"ק שלו ח\"ב ע' שכ."],["1125","61","<b>תרי\"ג. . וז'. . תר\"ך</b>: ראה תורת העולה להרמ\"א ח\"ג פל\"ח (לב, א). של\"ה יתרו שיו, א. מאו\"א מערכת תר\"ך סנ\"ו. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"א לע' שלח."],["1126","64","<b>תר\"ך עמודי אור</b>: ראה לקו\"ת להאריז\"ל חבקוק. מאמרי אדה\"א ויקרא ח\"ב ע' תסא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670571\" data-slug=\"torat-chaim\" data-id=\"2300670571\">תו\"ח בראשית מה, ג</a> הערה 32."],["1127","65","<b>וכלליות המצות. . וצדקה תהי' לנו</b>: ואתחנן ו, כה. ראה מאמרי אדה\"א ויקרא ח\"ב ע' עדרת. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540914\" data-slug=\"torat-chaim\" data-id=\"2300540914\">תו\"ח שמות ח\"א יד, א</a> ובהערה 628. סה\"מ תרל\"ח ע' שמט. וש\"נ. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 85. ד\"ה הנה אנכי כורת ברית על יד הערה 52. ד\"ה וירא העם וינועו על יד הערה 60. ד\"ה כי טובים דודיך מיין על יד הערה 17. (בחלק ההנחות) הנחה ד\"ה הנה אנכי כורת על יד הערה 55. לקמן ח\"ב (בחלק המאמרים) המשך יונתי ובהערה 27."],["1128","66","<b>וצדקה תרומם</b>: וכ\"ה בהקיצור כאן — משלי יד, לד [ושם צדקה — אבל כ\"ה בכ\"מ ומהם (בנוסף להערה 1): <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450572\" data-slug=\"or-hatorah-hb\" data-id=\"8316450572\">אוה\"ת חנוכה ח\"ב ע' 572</a>. לקמן ח\"ב (בחלק המאמרים) המשך יונתי ספ\"כ על יד הערה 487. מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 132. ד\"ה עשה צדקה ומשפט על יד הערה 19. (בחלק ההנחות) הנחה ד\"ה יפה שעה אחת על יד הערה 89. מאמרי אדה\"א ויקרא ח\"ב ע' תשא. וש\"נ. סה\"מ תרל\"ח ע' פד. וש\"נ]."],["1129","67","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."],["1130","68","<b>שהם וישפה</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380827\" data-slug=\"likkutei-torah\" data-id=\"4001380827\">לקו\"ת ראה כז, ד</a>. תו\"א תשא קיב, ג. מאמרי אדה\"א דברים ח\"ב ע' תע."]]],[2000470191,"ומלמעלה למטה, וכמשל ב' אנשים<sup data-n=\"1131\">69</sup> א' עומד בראש ההר והשני בתחתיות ההר שיש ב' אופנים באופן יחודם אם שהתחתון יעלה למעלה או שהעליון ירד למטה, וז\"ע תורה ומצות, תורה היא המשכה מלמעלה למטה שעי\"ז יומשך ההעלאה מלמטלמ\"ע שז\"ע שמאלו תחת לראשי הוא בחי' התורה שהיא בחי' שמאל דוחה<sup data-n=\"1132\">70</sup>, כי אורייתא מחכ' נפקת<sup data-n=\"1133\">71</sup> ובחכ' אתברירו<sup data-n=\"1134\">72</sup> להבדיל בין הטמא לטהור<sup data-n=\"1135\">73</sup>, מתניתא מלכתא<sup data-n=\"1136\">74</sup> כמלך שגוזר אומר כו' כ\"ה<sup data-n=\"1137\">75</sup> אלו כשרות ואלו טרפות<sup data-n=\"1138\">76</sup>, אסור פירושו שאסור וקשור בידי החיצוני'<sup data-n=\"1139\">77</sup> וא\"א להעלותו שיוכלל באחד וע\"י הדבור וקריאה בפה שפוסק בד\"ת אלו אסורים הוא דוחה אותם, ולכן מצות ת\"ת בקריאה בפה<sup data-n=\"1140\">78</sup> דוקא, כדי לדחות החיצוני' ועי\"ז נעשה עלי' מלמטה למעלה שכל מה שיוכל להתעלות יתעלה וע\"י בירור זה מתרומם נפש האדם כמ\"ש סלסלה ותרוממך עד שהתורה נק' על שמו כמ\"ש כ\"א בתורת ה' חפצו, ואח\"כ ובתורתו יהגה<sup data-n=\"1141\">79</sup> שנק' על שמו, ונק' מארי דאורייתא<sup data-n=\"1142\">80</sup>, א\"ת מורשה אלא מאורסה<sup data-n=\"1143\">81</sup> כו', ושמאל זה הוא תחת לראשי שמגביה הראש כו', וימינו תחבקני הוא ענין רמ\"ח מ\"ע<sup data-n=\"1144\">82</sup> בחי' חסדים<sup data-n=\"1145\">83</sup> שרמ\"ח מ\"ע הם רמ\"ח המשכות מלמעלה ע\"י מצות סוכה<sup data-n=\"1146\">84</sup> ושופר<sup data-n=\"1147\">85</sup> כו' ולכן המקיים את המצות נק' צדיק<sup data-n=\"1148\">86</sup> ע\"ש הצדקה שעשה פי' שכמו שהצדקה היא להחיות רוח שפלים<sup data-n=\"1149\">87</sup>, כך ע\"י המצות ממשיך חיות ואור אלקי מלמעלה למטה כו'.",[["1131","69","<b><a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540861\" data-slug=\"torat-chaim\" data-id=\"2300540861\">וכמשל ב</a>' אנשים</b>: מובא בכ\"מ בדא\"ח ומהם — לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 89. מאמרי אדה\"ז תקס\"ג ח\"ב ע' תרסז. תו\"ח בשלח ח\"א קצו, ג. מאמרי אדה\"א הנחות תקע\"ז ע' רסח. וש\"נ. שע\"ת ק, ב ובהערה 18. סה\"מ תרל\"ב ח\"א ע' קיח. וש\"נ."],["1132","70","<b>שמאל דוחה</b>: סוטה מז, א."],["1133","71","<b>אורייתא מחכ' נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["1134","72","<b>ובחכ' אתברירו</b>: ראה אגה\"ק סכ\"ח. זהר היכלות פקודי רנד, סע\"ב. ע\"ח שער דרושי נקודות ש\"ח, פ\"ו. לעיל המשך זאת חנוכת המזבח פכ\"ג הערה 657."],["1135","73","<b>להבדיל בין הטמא לטהור</b>: ע\"פ שמיני יא, מז."],["1136","74","<b>מתניתא מלכתא</b>: כתובות סא, ב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370128\" data-slug=\"torah-or\" data-id=\"3901370128\">תו\"א וישב כז, ב</a>. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קפט."],["1137","75","<b>כ\"ה</b>: במאמרי אדה\"ז כאן ע' קה: כך המשנה גוזרת."],["1138","76","<b>אלו כשרות ואלו טרפות</b>: וכ\"ה במאמרי אדה\"ז כאן ע' צב (אבל שם ע' קה: אלו טריפות אלו כשירות). לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה להבין שרש ענין מקיפים דבינה רפ\"ג. וש\"נ. ראה חולין פ\"ג, מ\"ב. מ\"א."],["1139","77","<b>שאסור. . החיצוני'</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא</a> פ\"ז. אגה\"ק סכ\"ו (קמג, ב)."],["1140","78","<b>מצות ת\"ת בקריאה בפה</b>: ראה גם (בנוסף למאמרי אדה\"ז כאן). לעיל המשך זאת חנוכת המזבח פכ\"ג ובהערה 667."],["1141","79","<b>כ\"א בתורת. . יהגה</b>: תהלים א, ב. ע\"ז יט, א."],["1142","80","<b>מארי דאורייתא</b>: ראה זהר ויחי רמב, ב. ויקרא כא, א. כה, ב. רע\"מ פינחס רטז, א. לקו\"ת שלח מז. ג."],["1143","81","<b>א\"ת מורשה אלא מאורסה</b>: ברכה לג, ד. ברכות נז, א."],["1144","82","<b>רמ\"ח מ\"ע</b>: מכות כג, סע\"ב."],["1145","83","<b>רמ\"ח מ\"ע בחי' חסדים</b>: ראה זח\"ב תוספות רעו, א. ת\"ז בהקדמה ה, א. ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ד."],["1146","84","<b>המשכות. . סוכה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370359\" data-slug=\"torah-or\" data-id=\"3901370359\">תו\"א תרומה פ, ד</a>. מאמרי אדה\"ז תקס\"ט ע' קסא."],["1147","85","<b>המשכות. . ושופר</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370322\" data-slug=\"torah-or\" data-id=\"3901370322\">תו\"א יתרו עב, סע\"ג</a>. תרומה שם."],["1148","86","<b>המקיים את המצות נק' צדיק</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381195\" data-slug=\"likkutei-torah\" data-id=\"4001381195\">לקו\"ת שה\"ש טז, ג</a>. סה\"מ תרל\"ח ע' תז. וש\"נ."],["1149","87","<b>להחיות רוח שפלים</b>: ישעי' נז, טו. ראה גם סה\"מ תרל\"ג ח\"ב ע' תסה ובהנסמן שם."]]],[2000470192,"<b>ועפ\"ז</b> יובן מה שת\"י<sup data-n=\"1150\">88</sup> על סמכוני<sup data-n=\"1151\">89</sup> באשישות שמשה ואהרן יסמכו בנ\"י בדברי תורה שהוא דת אש<sup data-n=\"1152\">90</sup>, ועי\"ז יתרפאו מחולת אהבה והיינו ע\"ד אש אוכלה אש<sup data-n=\"1153\">91</sup>, כי התורה היא בחי' שמאלו כנ\"ל שעי\"ז ירום ראש, ובחי' רפדוני בתפוחי' זהו בחי' ריח זהו בחי' ימינו תחבקני דמעשה המצות כו'.\n<b></b>קיצור. תפוח הוא מאכל וגם ריח, אכלו רעים, והריח הוא בחי' מקיף שרש המצות, תר\"ך, כתר, וצדקה תרומם גוי, וכפל הסמיכה זהו כמו שמאלו תורה אשישות אש אוכלה אש, ועי\"ז ירום ראש, וימינו תחבקני מעהמ\"צ בחי' רפדוני בתפוחים.",[["1150","88","<b>שת\"י</b>: וכ\"ה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 101 ובהנחה ד\"ה גן נעול הב' על יד הערה 65. אוה\"ת שה\"ש ע' תלה. [הובא לקמן ב] המשך מצה זו על יד הערה 489. ראה מגילה ג, א. שו\"ת זכר יהוסף — לר' יוסף זכרי' שאוועל — סקכ\"א."],["1151","89","<b>שת\"י על סמכוני</b>: כאן (שה\"ש ב, ה). הועתק ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316640209\" data-slug=\"or-hatorah-hb\" data-id=\"8316640209\">אוה\"ת שה\"ש ח\"א ע' רט</a>."],["1152","90","<b>תורה שהוא דת אש</b>: ברכה לג, ב וברמב\"ן שם."],["1153","91","<b>אש אוכלה אש</b>: יומא כא, ב."]]],[2000470193,"<h3>[גדולה תשובה] ואמנם כו'</h3>\n<b>פ' ויקרא</b>\n<b></b>כל המחלה כו' נופת תטופנה כו' ענין רופאיך כו' רפואה לעולם - ב' קיצורים\nויקרא\n<b>ואמנם</b> יש עוד בחי' חולה<sup data-n=\"1154\">1</sup> שעז\"נ כל המחלה<sup data-n=\"1155\">2</sup> אשר שמתי במצרים לא אשים עליך, כי אני ה' רופאיך, ובגמ' פ\"ט דב\"מ דק\"ז ע\"ב מחלה זו מרה כו', והענין הוא כמ\"ש כי נופת תטופנה שפתי זרה כו' ואחריתה מרה כלענה (במשלי סי'",[["1154","1","<b>ואמנם יש עוד בחי' חולה</b>: בספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e63\">א</sup> נרשם אודות מאמר זה: ”נופת תטופנה כו' ענין רופאיך כו' רפואה לעולם — ב' קיצורים\"\nהמאמר<sup data-n=\"e64\">ב</sup> הוא לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600552\" data-slug=\"or-hatorah-hb\" data-id=\"8316600552\">אוה\"ת בשלח ס\"ע תקפג</a> ואילך (בשינויים והוספות וכו'). ונמצא גם באוה\"ת משפטים ע' א'רמז ואילך (ומסיום פ\"ב ואילך ליתא שם).\nפ\"א ממאמר זה נמצא בתוס' הגהות וכו' בקונט' עץ החיים פ\"ג ע' 21 ואילך<sup data-n=\"e65\">ג</sup>.\nלפ\"ב ראה גם אוה\"ת משלי כרך א ע' תקנב ד\"ה בספר.\nמאמר זה הוא המשך להמאמר שנדפס לפנ\"ז.\nהנחת כ\"ק אדמו\"ר מהורש\"ב ממאמר זה נדפסה לקמן (בחלק הנחותיו) ושם הפתיחה: גדולה תשובה<sup data-n=\"e66\">ד</sup>."],["1155","2","<b>כל המחלה</b>: בשלח טו, כו.\n\n<b>א</b>  קה\"ת תש\"ז — ברשימת מאמרי שנה זו — ע' 52.\n\n<b>ב</b>  פרט להקיצורים.\n\n<b>ג</b>  <b>בסה\"מ ה'תש\"ח ע' 133 הערה ח (ובקונט' ומעיין ע' 137) כותב</b>: ”וכנראה מיוסד על דרוש הצ\"צ בס' שמות פ' יתרו ד\"ה ויאמר אם שמוע\" ואולי צ\"ל: פ' בשלח (והוא הנדפס באוה\"ת הנ\"ל).\n\n<b>ד</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470194,"ה'<sup data-n=\"1156\">3</sup> ) ופי' בזח\"ב ויקהל דף ר\"ג ע\"ב דקאי על ק\"נ, והיינו כמ\"ש בסש\"ב פ\"ז שהיא כלולה מטו\"ר ובעשייה רובה ככולה רע רק מעט טוב מעורב בה כו' וממנה נמשכים תאוות התענוגים גשמיים שאסרתם התורה כמובן מדין בן סורר ומורה<sup data-n=\"1157\">4</sup> כו', וע' בס' החינוך ס\"פ שלח לך סי' שפ\"ז וכן מי שתר<sup data-n=\"1158\">5</sup> אחר עיניו כלומר שהוא רודף אחר תאוות העולם כו' עובר על לאו זה, היינו לאו דולא תתורו<sup data-n=\"1159\">6</sup> כו', והבחיי ר\"פ קדושים האריך בזה. וזהו לתאוה יבקש נפרד (משלי סי' י\"ח<sup data-n=\"1160\">7</sup> ) כי מי שנמשך אחר התאוה הוא בחי' נפרד, וע' ברבות לך לך פמ\"א<sup data-n=\"1161\">8</sup> ע\"פ הפרד נא מעלי<sup data-n=\"1162\">9</sup>, הבדל אין כתי' כאן אלא הפרד, הרי שבחי' נפרד גרוע יותר מובדל<sup data-n=\"1163\">10</sup> מל' כסוס כפרד<sup data-n=\"1164\">11</sup>, ובאמת צ\"ל ותורתך בתוך מעי<sup data-n=\"1165\">12</sup> שדוד שיבח א\"ע שכל מה שבתוך מעיו זהו ע\"פ דרכי התורה והנהגת פרישותה כמ\"ש הבחיי ר\"פ קדושים, ועז\"נ צדיק אוכל לשובע נפשו<sup data-n=\"1166\">13</sup>, וכ\"ש בשאר התאוות כו', וזהו נופת תטופנה שהמשיל תאוות העולם המתוקים בראשונה לנופת, ואחריתם וסופם מרה כו', וכמ\"ש בפ' בהעלותך גבי התאוו תאוה<sup data-n=\"1167\">14</sup> דלבסוף כתי' והי' לכם לזרא<sup data-n=\"1168\">15</sup>, והוא בחי' אחריתה של נופת דשפתי זרה שנהפך לזרא והיינו ואחריתה מרה חדה כחרב פיות, וכדפי' רש\"י זרא חרב, וע\"כ נק' מחלה כי מחלה אם<sup data-n=\"1169\">16</sup> היות שפירושו חולה יש בו פי' ג\"כ לשון מתיקות כמו חורפי' מחלי' לי' לשבח<sup data-n=\"1170\">17</sup>, והיינו ק\"נ שכלולה מטו\"ר ע\"כ מצד הטוב שבה יש בה מתיקות ומצד הרע היא מר.\n<b>וברבות</b> פ' מצורע ס\"פ ט\"ז<sup data-n=\"1171\">18</sup> והסיר ה' ממך כל חולי<sup data-n=\"1172\">19</sup>, זה היצה\"ר שתחילתו מתוק וסופו מר, וכ' המ\"כ שדרש חולי מל' מחליי' לי' שפירושו ממתיק וסופו מר<sup data-n=\"1173\">20</sup>, ויש לפרש זה בשני דרכים הא' כפשוטו שממתיק לו איך שמתוק הוא לעשות כן, ואחריתו מרה כלענה, הב' יש לפרש באופן אחר כי לפי שאין פתגם<sup data-n=\"1174\">21</sup>",[["1156","3","<b>כי נופת תטופנה. . ואחריתה. . במשלי סי' ה'</b>: פסוק ג. ד."],["1157","4","<b>בן סורר ומורה</b>: תצא כא, כ. סנהדרין ע, א."],["1158","5","<b>שתר</b>: בחינוך: שהוא תר. וכ\"ה בקונט' עה\"ח."],["1159","6","<b>לאו דולא תתורו</b>: שלח טו, לט."],["1160","7","<b>לתאוה יבקש. . משלי סי' י\"ח</b>: פסוק א. ראה (בנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/torah-or/3901370230\" data-slug=\"torah-or\" data-id=\"3901370230\">תו\"א שמות נא, ב</a>. תו\"ח תצוה ח\"ב שמג, ריש ע\"ב. המשך מים רבים תרל\"ו ריש ע' ב. ע' ה."],["1161","8","<b>פמ\"א</b>: ס\"ו."],["1162","9","<b>הפרד נא מעלי</b>: לך יג, ט."],["1163","10","<b>מובדל</b>: באוה\"ת כאן: מבחי' הבדלה. בקונט' עה\"ח כאן: מנבדל."],["1164","11","<b>מל' כסוס כפרד</b>: מתנות כהונה שם — תהלים לב, ט. ראה קונט' עה\"ח כאן ע' 23."],["1165","12","<b>ותורתך בתוך מעי</b>: תהלים מ, ט."],["1166","13","<b>צדיק אוכל לשובע נפשו</b>: משלי יג, כה. ראה גם לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה על יד הערה 98. לקמן ח\"ב (בחלק המאמרים) המשך יונתי ובהערה 173. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת על יד הערה 89. קונט' עה\"ח כאן ע' 23."],["1167","14","<b>התאוו תאוה</b>: בהעלותך יא, ד."],["1168","15","<b>והי' לכם לזרא</b>: בהעלותך שם, כ."],["1169","16","<b>אם</b>: במקומות המובאים בהערה 1: עם. אבל כ\"ה בכ\"מ — ראה גם סה\"מ תרל\"ח ע' ה. וש\"נ."],["1170","17","<b>חורפי' מחלי' לי' לשבח</b>: ראה ע\"ז לט, א. מת\"כ לשמו\"ר פמ\"ג, ג."],["1171","18","<b>ס\"פ ט\"ז</b>: סי' ח."],["1172","19","<b>והסיר ה' ממך כל חולי</b>: עקב ז, טו."],["1173","20","<b>וסופו מר</b>: במת\"כ שם: וסוף בא לידי חולי כמשמעו."],["1174","21","<b>פתגם</b>: וכ\"ה בקונט' עה\"ח כאן ע' 24. באוה\"ת כאן: פגם."]]],[2000470195,"העונש נמשך במהרה ע\"כ תחילת היצה\"ר מתוק וכמ\"ש מים גנובים ימתקו<sup data-n=\"1175\">22</sup>, וסופו מר בבוא העונש, והנה תיבת מר עולה מספרו ב\"פ ק\"ך, והיינו ב\"פ ק\"ך צירופי אלקי'<sup data-n=\"1176\">23</sup>, והיינו כי יש ק\"ך צירופי' אלקי' בקדושה ע\"ב הראשונים הם גבורות ממותקים, ומ\"ח האחרונים קשים<sup data-n=\"1177\">*25</sup>, ואמנם כשמתחברים עוד ק\"ך צירופי' דק\"נ לינק מהם אז נעשים דינים קשים ביותר לנתוש ולנתוץ ולהאביד<sup data-n=\"1178\">25</sup> כו', והנה ארז\"ל ברבות פ' ראה<sup data-n=\"1179\">26</sup>, ובאיכה<sup data-n=\"1180\">27</sup> ע\"פ מפי עליון<sup data-n=\"1181\">28</sup> א\"ר אלעזר<sup data-n=\"1182\">29</sup> מיום שאמר<sup data-n=\"1183\">30</sup> הקב\"ה ראה נתתי לפניך את החיים ואת הטוב כו' לא יצאת טובה לעושי רעה ולא רעה לעושי טובה, אלא טובה<sup data-n=\"1184\">31</sup> כו', א\"כ הנמשך אחר יצה\"ר הוא בעצמו ממשיך עליו הרע והמות ח\"ו, וזהו הגם שתחלתו מתוק עכ\"ז סופו מר, וזהו שארז\"ל והסיר ה' ממך כל חולי, ממך הוא<sup data-n=\"1185\">34</sup> שלא יבואו חליים עליך כו', וזהו כל המחלה אשר שמתי במצרים, מצרים לשון מצרים וגבולים<sup data-n=\"1186\">35</sup> היינו מן הארץ לרקיע<sup data-n=\"1187\">36</sup> מהלך ת\"ק שנה, גם מצרים נק' תאוות גופניות כו', וק\"נ הנק' מחלה זו מרה היא מקור שממנה נמשך בג\"ק<sup data-n=\"1188\">37</sup> שמהם שרש כל האיסורים<sup data-n=\"1189\">38</sup> כו', וז\"ש הוא ענין<sup data-n=\"1190\">39</sup> רע נתן האלקי'<sup data-n=\"1191\">24</sup> לבנה\"א לענות בו פי' רע הוא היצה\"ר כמ\"ש כי יצר לב האדם רע<sup data-n=\"1192\">40</sup>, ועז\"נ ובורא רע<sup data-n=\"1193\">41</sup>, ראה נתתי<sup data-n=\"1194\">32</sup> לפניך<sup data-n=\"1195\">33</sup> כו' ואת הרע, ופי' לענות בו יש לפרש שיהי' היצה\"ר מלאך רע עונה אמן בע\"כ<sup data-n=\"1196\">42</sup> והיינו כמ\"ש ואהבת בכל לבבך בשני יצריך<sup data-n=\"1197\">43</sup> כו', אך ע\"י אם שמוע תשמע",[["1175","22","<b>מים גנובים ימתקו</b>: משלי ט, יז."],["1176","23","<b>מר. . ב\"פ ק\"ך. . אלקי'</b>: ראה לקו\"ת להאריז\"ל בשלח עה\"פ ויבאו מרתה (טו, כג). (שם בסופו ד\"ה עמלק). מאו\"א מערכת מר סצ\"ב. (ובנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת מסעי ע' א'שפ</a>. (וראה גם) <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450566\" data-slug=\"or-hatorah-hb\" data-id=\"8316450566\">אוה\"ת תשא ע' ב'יא</a>. איכה כרך ב ס\"ע א'לו."],["1177","*25","<b>ומ\"ח האחרונים קשים</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גן נעול הב' ובהערה 50."],["1178","25","<b>לנתוש ולנתוץ ולהאביד</b>: ירמי' א, י. יח, ז."],["1179","26","<b>ברבות פ' ראה</b>: ראה שם פ\"ד, ג. ראה סה\"מ תרל\"ו ח\"ב ע' רסט (ומציין לשינויים). המשך תער\"ב ח\"ג ס\"ע א'תכט ואילך."],["1180","27","<b>ובאיכה</b>: ראה שם פ\"ג אות מ. באוה\"ת כאן אינו מביאו, אף שלכאורה מעתיק לשונו."],["1181","28","<b>מפי עליון</b>: איכה ג, לח."],["1182","29","<b>א\"ר אלעזר</b>: באוה\"ת כאן: א\"ר אחא."],["1183","30","<b>מיום שאמר</b>: וכ\"ה באוה\"ת ובקונט' עה\"ח כאן. ובמדרש: (משאמר) משעה שאמר — וכ\"ה בהדרושים שבהערה 26."],["1184","31","<b>הקב\"ה. . אלא טובה</b>: ל' איכ\"ר שם בשינוי."],["1185","34","<b>והסיר. . ממך הוא</b>: ויק\"ר שם (פט\"ז, ח). ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450511\" data-slug=\"or-hatorah-hb\" data-id=\"8316450511\">אוה\"ת עקב ס\"ע תקיא</a> ואילך."],["1186","35","<b>מצרים לשון מצרים וגבולים</b>: ראה (בנוסף להערה 1) <a class=\"ft-cite\" href=\"#/read/torah-or/3901370287\" data-slug=\"torah-or\" data-id=\"3901370287\">תו\"א בשלח סד, ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">סע\"ג. יתרו סז, סע\"ב</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370318\" data-slug=\"torah-or\" data-id=\"3901370318\">עא, ג</a>."],["1187","36","<b>מן הארץ לרקיע</b>: ראה חגיגה יג, א."],["1188","37","<b>וק\"נ. . שממנה נמשך בג\"ק</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316450559\" data-slug=\"or-hatorah-hb\" data-id=\"8316450559\">אוה\"ת עקב ע' תקנט</a> ס\"ח. סה\"מ תרל\"ח ע' רב."],["1189","38","<b>בג\"ק. . האיסורים</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310011\" data-slug=\"tanya\" data-id=\"3401310011\">תניא פ\"ו</a>. פ\"ח."],["1190","39","<b>הוא ענין. . האלקי'</b>: וכ\"ה באוה\"ת ובקונט' עה\"ח כאן — קהלת א, יג [ושם: אלקים]."],["1191","24","<b>ק\"ך צירופי אלקי'</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות ובהערה 73."],["1192","40","<b>כי יצר לב האדם רע</b>: נח ח, כא. סוכה נב, א."],["1193","41","<b>ובורא רע</b>: ישעי' מה, ז."],["1194","32","<b>ראה נתתי</b>: נצבים ל, טו."],["1195","33","<b>לפניך את</b>: בחומש ובאיכ\"ר: לפניך היום את. אבל כ\"ה בהדרושים הנ\"ל פרט לסה\"מ תרל\"ו."],["1196","42","<b>מלאך רע עונה אמן בע\"כ</b>: שבת קיט, ב."],["1197","43","<b>ואהבת בכל לבבך בשני יצריך</b>: ואתחנן ו, ה [בדילוג] ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9. לעיל המשך זאת חנוכת המזבח פט\"ז."]]],[2000470196,"לקול<sup data-n=\"1198\">44</sup> כו' מזה יהי' נמשך שלא אשים עליך מחלה דק\"נ וכמו שפי' רז\"ל להדיא ע\"פ והסיר ה' ממך כל חולי זה יצה\"ר כנ\"ל.\n<b></b>קיצור. מחלה זו מרה ק\"נ שממנה נמשכים תאוות תענוגי' גשמיי' שאסרם התורה, ועובר על לאו דולא תתורו, ונק' נפרד שגרע מנבדל, כ\"א צ\"ל ותורתך בתוך מעי, וחולי זה יצה\"ר שסופו מ\"ר ב\"פ ק\"ך והאחרוני' דינים קשים, ועל רע זה נא' לענות בו שיהי' מלאך רע עונה בע\"כ אמן, וע\"ד בכל לבבך בשני יצריך.\nועדיין צ\"ל מ\"ש כי אני ה' רופאך דמאחר שלא ישים מחלה הנ\"ל א\"כ מה צריך לרפואה, והגם שי\"ל שמאחר שאני רופאך לכן לא אשים עליך המחלה בכדי שלא תצטרך לרפואה, עכ\"ז צ\"ל מהו ענין רופאך. אך הנה כתי' רפאות תהי לשרך<sup data-n=\"1199\">45</sup>, ופי' הר\"נ ז\"ל<sup data-n=\"1200\">46</sup> בס' מ\"ע<sup data-n=\"1201\">47</sup> כי הנה מאמר המין מפלגא ולעילא כו' ספ\"ד דסנהדרין<sup data-n=\"1202\">48</sup>, ונמצא באמת צריך האדם לראות שלא יהי' מפלגא ולתתא פי' שלא יהא פוגם בברית כו', וזהו רפאות תהי לשרך שאפי' מטבור ולמטה מרפא שיהי' שלם עכ\"ל ודפח\"ח. וביאור ענין זה יובן ממ\"ש ע\"פ ששים המה מלכות<sup data-n=\"1203\">49</sup> דהנה ענין מפלגא ולתתא זהו מ\"ש ומשם יפרד כו' והרי בבחי' יפרד כתי' לתאוה יבקש נפרד כנ\"ל, והסיבה לבחי' ומשם יפרד זהו לפי שההמשכה היא מבחי' ונהר יוצא<sup data-n=\"1204\">50</sup> כו' שהוא בחי' יש נהרא מכיפי' מבריך<sup data-n=\"1205\">52</sup> ומתרבה ונתפס ליש והוא ההשגה שהיא בחי' בינה<sup data-n=\"1206\">51</sup> כו', אבל ומעיין מבית ה' יצא<sup data-n=\"1207\">53</sup> בחי' והחכמה<sup data-n=\"1208\">54</sup> מאין תמצא<sup data-n=\"1209\">55</sup> אזי והשקה את נחל השטים<sup data-n=\"1210\">56</sup> ג\"כ שהוא מקור התאוות כמ\"ש ברבות פ' בלק<sup data-n=\"1211\">57</sup>, ומעין זה מתגלה בתורה, ולכן עשו ארון עצי שטים<sup data-n=\"1212\">58</sup> שע\"י בחי' אור<sup data-n=\"1213\">59</sup>",[["1198","44","<b>אם שמוע תשמע לקול</b>: התחלת הכתוב כל המחלה — בשלח טו, כו."],["1199","45","<b>רפאות תהי לשרך</b>: משלי ג, ח."],["1200","46","<b>הר\"נ ז\"ל</b>: הרב מנחם נחום מטשארנביל."],["1201","47","<b>בס' מ\"ע</b>: בספר מאור עינים פ' בשלח עה\"פ ויאמר אם שמוע תשמע בסופו. ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600552\" data-slug=\"or-hatorah-hb\" data-id=\"8316600552\">אוה\"ת משלי כרך א ע' תקנב</a>."],["1202","48","<b>מאמר המין מפלגא. . ספ\"ד דסנהדרין</b>: ראה שם לט, א."],["1203","49","<b>ששים המה מלכות</b>: שה\"ש ו, ח. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381284\" data-slug=\"likkutei-torah\" data-id=\"4001381284\">לקו\"ת שה\"ש לט, רע\"א</a>."],["1204","50","<b>ומשם יפרד. . ונהר יוצא</b>: בראשית ב, י."],["1205","52","<b>נהרא מכיפי' מבריך</b>: שבת סה, ב. ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381284\" data-slug=\"likkutei-torah\" data-id=\"4001381284\">לקו\"ת שה\"ש לט, א</a> ואילך. אמ\"ב שער התפילין קכא, סע\"ג ואילך."],["1206","51","<b>ונהר יוצא. . בינה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א משפטים עה, ד</a>: כמ\"ש בזהר פ' אמור [צט, א]."],["1207","53","<b>ומעיין מבית ה' יצא</b>: יואל ד, יח."],["1208","54","<b>ומעיין. . והחכמה</b>: ראה זהר בא מב, ב. מאמרי אדה\"א דברים ח\"ג ע' תתצב. וש\"נ. שה\"א צ, א הערה 12."],["1209","55","<b>והחכמה מאין תמצא</b>: איוב כח, יב."],["1210","56","<b>והשקה את נחל השטים</b>: המשך הכתוב ומעיין מבית ה'."],["1211","57","<b>השטים. . התאוות. . ברבות פ' בלק</b>: פ\"כ, כב. ראה גם תנחומא שם יז. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת חוקת ע' תשצו</a>: בזח\"ג ס\"פ עקב דף ער\"ה ע\"ב כרך ה' ע' א'תרכה<sup data-n=\"e67\">ה</sup>: בזהר ס\"פ עקב — וצ\"ל כבאוה\"ת מסעי ע' א'שצ: בזוהר ואתחנן דף ע\"ר ע\"ב."],["1212","58","<b>עשו ארון עצי שטים</b>: תרומה כה, י. ויקהל לז, א. ראה שמו\"ר פ\"נ, ג. תנחומא שם ח. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת תרומה ע' א'תמד</a> ואילך (ס\"ח). ויקהל ע' ב'ריז<sup data-n=\"e68\">ו</sup>. מסעי ע' א'שצ."],["1213","59","<b>ארון. . אור</b>: ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830010\" data-slug=\"or-hatorah-hb\" data-id=\"8158830010\">אוה\"ת</a> ויקהל שם: כמ\"ש ברבות שם — ראה שם ס\"א ובמת\"כ שם. וראה גם סה\"מ תרל\"ח ע' קמח.\n\n<b>ה</b>  ובמהדורת תשנ\"ח ע' 17.\n\n<b>ו</b>  <b>ושם מציין</b>: כמ\"ש מזה בפ' בשלח גבי ויבואו מרתה [כנראה הכוונה להנדפס באוה\"ת מסעי שנרשם בפנים ההערה] וע\"פ רפאני [אוה\"ת ירמי' כרך א ע' שסב]"]]],[2000470197,"התורה גם בחי' שטים נהפך לטוב, וכמארז\"ל אם פגע בך מנוול זהו היצה\"ר<sup data-n=\"1214\">60</sup>, והתורה נק' תבלין<sup data-n=\"1215\">61</sup> בדרז\"ל, וזהו כי אני ה' רופאך דאע\"ג שכבר נא' כל המחלה כו' לא אשים, מ\"מ מפלגא ולתתא ששם נא' ומשם יפרד, והיינו משום דאית קרומא דפסיק במעוי דב\"נ<sup data-n=\"1216\">62</sup> כו' ומ\"מ ע\"י התורה נא' רפאות תהי לשרך, והיינו ע\"י שררך אגן הסהר<sup data-n=\"1217\">63</sup> כו', וזהו כי אני ה' רופאך כו'. ולתוס' ביאור בענין כל המחלה כו' לא אשים כו' י\"ל ע\"ד בשבת ק\"נ נמתקת<sup data-n=\"1218\">64</sup> והרע נדחה והטוב נהפך לקדושה כו' ולכן לא נאמר פרש שבתכם<sup data-n=\"1219\">65</sup> כו' ועד\"ז יובן ענין כל המחלה לא אשים כו'.\n<b></b>קיצור. מאחר שהמחלה לא ישים מה צריכי' לרפואה, ופי' הר\"נ ז\"ל שזהו גם מפלגא ולתתא היינו פגם הברית, ויש לבאר כי ע\"י הקרומא דפסיק, נא' ומשם יפרד, והיינו לפי שההמשכה הוא מהנהר, אבל ומעיין מבית ה' יוצא<sup data-n=\"1220\">66</sup> והשקה גם נחל השטים, ועד\"ז בתורה, ולכן הארון הי' מעצי שטים ועז\"נ כי אני ה' רופאך.\nובכ\"ז יובן מארז\"ל גדולה תשובה<sup data-n=\"1221\">67</sup> שמביאה רפואה לעולם, ולכאו' צ\"ל מה צריך העולם לרפואה דלכאו' ענין הרפואה אינו שייך רק במדבר ובע\"ח, אך כי ראה נתתי לפניך את החיים כו', וכמבואר בלק\"ת פ' ואתחנן<sup data-n=\"1222\">68</sup> בד\"ה שמע ישראל שז\"ע יהי רקיע ויהי מבדיל<sup data-n=\"1223\">69</sup>, ומה שמעל לרקיע נק' חיים כו' וההיפוך מה שלמטה הוה ונפסד, וע' בד\"ה האזינו השמים<sup data-n=\"1224\">70</sup>, ועיקר בחי' מות היינו ג\"ק שנמשכו מזמ\"ל דתהו שמתו<sup data-n=\"1225\">71</sup>, ומהם כל האיסורים, ולכן רשעים בחייהם<sup data-n=\"1226\">72</sup> כנז' בלק\"ת פ' עקב<sup data-n=\"1227\">73</sup> סד\"ה ויאכילך את המן, והחולי מפריש בין חיים כו' והוא ק\"נ תאוות היתר, וחולי קרוב ללשון חול<sup data-n=\"1228\">74</sup>, חולין<sup data-n=\"1229\">75</sup> שהיא בעשייה וע\"כ העולם",[["1214","60","<b>אם פגע. . היצה\"ר</b>: ראה סוכה נב, ב וברש\"י שם."],["1215","61","<b>והתורה נק' תבלין</b>: קדושין ל, ב."],["1216","62","<b>דאית קרומא דפסיק במעוי דב\"נ</b>: ראה זהר בראשית לב, ב."],["1217","63","<b>שררך אגן הסהר</b>: שה\"ש ז, ג."],["1218","64","<b>בשבת ק\"נ נמתקת</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ו. זהר\"ק משפטים צד, ב (ע' נז). אגה\"ק סכ\"ו (קמג, ב). מאמרי אדה\"ז תקס\"ה ח\"א ע' שסב ואילך. ביאורי הזהר להצ\"צ כרך ב ויקהל ע' תתמה. אוה\"ת בשלח כאן ע' תקפה. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן בסופה."],["1219","65","<b>פרש שבתכם</b>: ראה זהר יתרו פח, ב. מאמרי אדה\"א דברים ח\"ג ע' א'קיח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540565\" data-slug=\"torat-chaim\" data-id=\"2300540565\">תו\"ח בא ח\"א קכ, ג</a> הערה 291."],["1220","66","<b>יוצא</b>: לעיל על יד הערה 53: יצא."],["1221","67","<b>גדולה תשובה</b>: יומא פו, סע\"א."],["1222","68","<b>בלק\"ת פ' ואתחנן</b>: יא, ב."],["1223","69","<b>יהי רקיע ויהי מבדיל</b>: בראשית א, ו [בדילוג]."],["1224","70","<b>בד\"ה האזינו השמים</b>: לק\"ת שם עב, ב."],["1225","71","<b>מזמ\"ל דתהו שמתו</b>: ראה גם לעיל המשך זאת חנוכת המזבח פי\"ט ובהערה 468."],["1226","72","<b>רשעים בחייהם</b>: ברכות יח, ב."],["1227","73","<b>בלק\"ת פ' עקב</b>: יד, א ספ\"ב."],["1228","74","<b>וחולי קרוב ללשון חול</b>: ראה גם אוה\"ת משפטים ע' א'רכח."],["1229","75","<b>וחולי. . חולין</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010166\" data-slug=\"or-hatorah-hb\" data-id=\"8159010166\">אוה\"ת כאן ע' תקפה</a>. משפטים ע' א'רמ."]]],[2000470198,"כשמקבל מק\"נ אינו בבריאותו, ועמ\"ש בד\"ה זכור<sup data-n=\"1230\">76</sup> את יום השבת לקדשו, והיינו כי בתחלת בריאת העולם נא' ברא, לשון בריאה, ולשון בריאות<sup data-n=\"1231\">77</sup> שלא הי' ק\"נ הנק' מחלה שולטת, וע\"י חטא עה\"ד נעשו שי\"ב חול והוא ענין מחלה וע\"כ העולם צריך לרפואה שיהי' בריא כמו בעת הבריאה, וכתי' בוראך יעקב<sup data-n=\"1232\">78</sup> שע\"י יהי' נמשך הרפואה והבריאות, שיהי' בעולם גילוי החיים והטוב, וכמ\"ש גם את העולם נתן בלבם<sup data-n=\"1233\">79</sup>, שתלוי בריאות ורפואות העולם בלב האדם כו', והיינו ע\"י התשובה שממשיך מאריך אנפין<sup data-n=\"1234\">80</sup> שע\"י גילוי זה יומשך ארוכה ורפואה לעולם כו', והגם שארז\"ל בירושלמי<sup data-n=\"1235\">81</sup> ע\"פ אלה תולדות השמים והארץ בהבראם<sup data-n=\"1236\">82</sup> שהם חזקים כיום הבראם, עכ\"ז א\"א לכחד שאינו כמו שנברא שהרי העולם על מלואו נברא<sup data-n=\"1237\">83</sup>, וע\"י חטא עה\"ד חסרו וא\"ו דברים<sup data-n=\"1238\">84</sup> הרי העולם חסר כמו החולי שחסר לו, וכשבא יום השבת אז נק' ששת ימי המעשה בשם חול ל' חולה, והיינו מפני כי בשבת הוא אחר חטא עה\"ד שכבר נעשה העולם חולה ע\"י שליטת ק\"נ, רק כי בשבת נמתקת ק\"נ כנ\"ל משא\"כ בחול ל' חולה שחסר ושולט ק\"נ הנק' מחלה, ולכן הגם כי בעצם חזקים הם כיום הבראם עכ\"ז העולם חולה מצד החסרון ושליטת ק\"נ, וע\"י התשובה נמשך רפואה לעולם כו'.",[["1230","76","<b>בד\"ה זכור</b>: וכ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460112\" data-slug=\"or-hatorah-hb\" data-id=\"8316460112\">אוה\"ת</a> כאן. ראה גם אוה\"ת יתרו ע' תתקכז. סה\"מ תרכ\"ו ע' ב."],["1231","77","<b>ברא. . בריאות</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010142\" data-slug=\"or-hatorah-hb\" data-id=\"8159010142\">אוה\"ת</a> שבהערה 75. נצבים ע' א'רכו. ע' א'רכח. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 70."],["1232","78","<b>בוראך יעקב</b>: ישעי' מג, א. ראה גם לקמן שם על יד הערה 71."],["1233","79","<b>גם את העולם נתן בלבם</b>: קהלת ג, יא. ראה גם לעיל המשך זאת חנוכת המזבח ספט\"ז ובהערה 397."],["1234","80","<b>התשובה שממשיך מאריך אנפין</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380614\" data-slug=\"likkutei-torah\" data-id=\"4001380614\">לקו\"ת בלק עד, א</a>. אוה\"ת בשלח כאן ס\"ע תקפה. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן בסופה."],["1235","81","<b>בירושלמי</b>: ראה שם ברכות פ\"א, ה\"א. ראה גם דרך אמונה לר\"מ בן גבאי קה\"ת ספ\"ד. ס' החקירה ע' קג ואילך. המשך תרל\"ו פל\"ג ובהערה שם. הגהת כ\"ק אדמו\"ר מהר\"ש באוה\"ת בראשית כרך ו ע' 2040. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101182\" data-slug=\"likkutei-sichot\" data-id=\"1300101182\">לקו\"ש בראשית כרך י' ע' 182</a>."],["1236","82","<b>אלה תולדות השמים והארץ בהבראם</b>: בראשית ב, ד."],["1237","83","<b>העולם על מלואו נברא</b>: ראה ב\"ר פי\"ד, ז. וראה שם פי\"ב, ו. פי\"ג, ג (וביפ\"ת שם). ראה גם תו\"ח ח\"ש קלד, א. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300251014\" data-slug=\"likkutei-sichot\" data-id=\"1300251014\">לקו\"ש בראשית כרך כה ע' 14</a> ואילך."],["1238","84","<b>וע\"י חטא עה\"ד חסרו וא\"ו דברים</b>: ראה ב\"ר פי\"ב, וה. תנחומא בראשית ו. יל\"ש בראשית ב, ד (רמז יז). במד\"ר פי\"ג, יב. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ובחודש השביעי על יד הערה 62: ה' דברים."]]],[2000470199,"<h3>סמוכים לעד כו'</h3>\n<b></b><b>בס\"ד. ש\"פ צו תר\"ם לפ\"ק</b>\nזו\"ן כו' וסמך ידו - ג\"פ\n[צו]\n<b>סמוכים</b> לעד<sup data-n=\"1239\">1</sup> לעולם<sup data-n=\"1240\">2</sup>, פי' בזח\"א בראשית דל\"ה א' דקאי על זו\"נ שהם סמוכים לעד כו', ובפרד\"ס<sup data-n=\"1241\">3</sup> בערה\"כ אות סמך<sup data-n=\"1242\">4</sup> פי' שהמל' נסמך בת\"ת, וכמ\"כ הת\"ת נסמך ע\"י המל', וצ\"ל ענין סמיכתם. ויובן בהקדם ענין הסמיכה בקרבנות דכתי' וסמך ידו על ראש העולה<sup data-n=\"1243\">5</sup> ונרצה לו לכפר עליו, וארז\"ל בפ\"ב דחגיגה דט\"ז ע\"ב אמר רמי בר חמא ש\"מ סמיכה בכל כחו בעינן כו', ובמנחות ס\"פ שתי מדות שנינו על הראש בשתי ידים<sup data-n=\"1244\">6</sup> כו' נמצא סמיכה בשתי ידיו בכל כחו, והנה פי' וסמך קאי אדלעיל מיני' דכתיב אדם כי יקריב<sup data-n=\"1245\">7</sup> מכם קרבן לה' מן הבהמה כו', וצ\"ל מה\"ע שמביאים קרבן בהמה ע\"ג המזבח שעי\"ז יתכפר נפש האדם שחטא, וכי מה ענין בהמה לאדם. אך הענין דהנה נודע שבכדי שיומשך סליחת העוונות צ\"ל המשכה יותר גבוה מאם לא הי' חוטא כלל, שכדי למלאות הפגם צ\"ל נמשך מבחי' אור א\"ס דלאו מכל אינון מדות<sup data-n=\"1246\">8</sup> איהו כלל שלהיות שבשם אינו תופס מקום כלל, ולכן נמשך משם להיות נושא עון ועובר על פשע<sup data-n=\"1247\">9</sup> כו'.",[["1239","1","<b>סמוכים לעד</b>: בספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e69\">א</sup> אודות מאמר זה נרשם: ”זו\"ן כו' וסמך ידו\".\nמאמר זה הוא מאמר ד\"ה וסמך ידו שנדפס בסה\"מ תרל\"ד ע' קמט ואילך (והפתיחה: ”סמוכים. . המל'\" נדפס בסה\"מ שם ע' קנב).\nהנחת<sup data-n=\"e70\">ב</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו). ומשם נעתקה הכותרת המופיע בריש המאמר כאן (פרט לתיבת בס\"ד)."],["1240","2","<b>סמוכים לעד לעולם</b>: תהלים קיא, ח. מובא גם באוה\"ת ויקרא ע' רכג. ראה גם מאמר ד\"ה זה באוה\"ת (יהל אור) תהלים ע' תלד סה\"מ פר\"ת ע' קמח ואילך תש\"ל בתחילתו."],["1241","3","<b>ובפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["1242","4","<b>ובפרד\"ס בערה\"כ אות סמך</b>: וכ\"ה (בסה\"מ תרל\"ד כאן ו) באוה\"ת ויקרא שם.\nבאוה\"ת תהלים שם מעתיק לשון הזהר (שהוזכר בקיצור בפנים) וכו' ואח\"כ ממשיך: וזה המאמר הביאו בפרד\"ס שער מהות והנהגה. . ”וז\"ש בפרד\"ס ערך סמוכים\".\nבסה\"מ פר\"ת שם: מעתיק ל' הזהר ומציין ועמ\"ש הפרדס ש\"ח פי\"ח. . (ומסיים): ”והיינו כמ\"ש הפרדס שם שהמל' נסמך בת\"ת ות\"ת במל'\".\nבלקו\"ת שמע\"צ צ, סע\"א ואילך כותב: ”ובפרדס בשער כ\"ז שער האותיות פרק י\"ח באות סמ\"ך פי' ענין סמוכים כי תפארת נסמך במלכות ומלכות נסמך בת\"ת\"."],["1243","5","<b>וסמך ידו על ראש העולה</b>: ויקרא א, ד."],["1244","6","<b>ובמנחות ס\"פ שתי מדות. . ידים</b>: מנחות צג, א (במשנה). שם ב."],["1245","7","<b>אדם כי יקריב</b>: ויקרא א, ב. ראה גם דרך חיים כו, א ואילך. ש\"א ט, ב. המשך והחרים תרל\"א ע' יט. סה\"מ תרנ\"ח ע' קנז וע' רכז ואילך. לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 8. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת ו(בחלק ההנחות) בהנחה שם."],["1246","8","<b>דלאו מכל אינון מדות</b>: ת\"ז בהקדמה יז, ב."],["1247","9","<b>נושא עון ועובר על פשע</b>: מיכה ז, יח.\n\n<b>א</b>  קה\"ת תש\"ז — ברשימת מאמרי שנה זו — ע' 52.\n\n<b>ב</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470200,"<b>והנה</b> שרש האדם הוא מעולם התיקון<sup data-n=\"1248\">10</sup> שז\"ע מ\"ש נעשה אדם בצלמנו<sup data-n=\"1249\">11</sup> כו' שבצלם אלקים עשה את האדם<sup data-n=\"1250\">12</sup>, וכדכתי' ועל דמות הכסא<sup data-n=\"1251\">13</sup> דמות כמראה אדם עליו מלמעלה, פי' וענין בחי' אדם הלא אין לו דמות הגוף<sup data-n=\"1252\">14</sup> ולא גוף אלא שז\"ע זיווג והתכללות המדות שיהי' החסד סובל מדת הגבו' והגבורה תסבול הנהגת החסד, והת\"ת היא בחי' רחמים<sup data-n=\"1253\">15</sup> היא מייחדת אותם להיות כי ע\"י מדת החסד הוא טוב לכל להשפיע גם למי שאינו ראוי וכמו שא' אברהם לו ישמעאל יחי' לפניך<sup data-n=\"1254\">16</sup> שזהו לעומת מדת הגבורה שהוא בחי' הצמצום לדקדק בדקדוק אחר דקדוק אם ראוי לאותו דבר, ומדת הת\"ת נותן מקום למדת הגבו' דהן אמת איננו ראוי שיעשה לו הדבר הנ\"ל מ\"מ צריכים לרחם עליו להיות חסר לו הדבר ההוא וצריכים לרחם עליו להשפיע לו מטובו ית', וכללות המדות מתנהגי' ע\"י השכל כמ\"ש ע\"פ שכלו יהולל איש<sup data-n=\"1255\">17</sup>, שהשכל הוא מנהיג המדות ומושל עליהם, והאדם הנעשה בצלם ודמות ניתן לו כל הכחות להתנהג עפ\"י זיווגי והתכללות המדות בבחי' חו\"ג ומדת הרחמים לרחם על זולתו, וכולם יתנהגו עפ\"י השכל המשכיל ומתבונן בהשכלה הדק היטב בכל פרטי פרטיות כו'. וזהו שאה\"כ ואהבת כו' בכל לבבך וארז\"ל בשני יצריך<sup data-n=\"1256\">18</sup>, ולכאו' יפלא איך היצה\"ר שהוא המסית ומדיח יבא לבחי' אהבת אלקות<sup data-n=\"1257\">19</sup>, אלא מפני שניתן כח במוח להיות שליט על הלב<sup data-n=\"1258\">20</sup> הוא בחי' חמימות התאוה, ובפרט בחי' האש זרה הנמשך מתגבורת נה\"ב שזהו מבחי' מדות הרעות דיצה\"ר, הנה ע\"י שיתבונן היטב בשכלו איך שהוי' הוא האלקי'<sup data-n=\"1259\">21</sup> בשמים ממעל ועל הארץ מתחת אין עוד ממילא יפלו ויתבטלו כל הרצונות זרות מחמימות תאוות עוה\"ז אפי' תאוות היתר וכ\"ש להקל באיזהו שמץ איסור אפי' איסור קל של ד\"ס, ובאמת חמורים ד\"ס<sup data-n=\"1260\">22</sup> כמ\"ש במ\"א באריכות, ועי\"ז מתעלה נפשו האלקי' ג\"כ<sup data-n=\"1261\">23</sup> כמ\"ש במ\"א.",[["1248","10","<b>שרש האדם. . התיקון</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370293\" data-slug=\"torah-or\" data-id=\"3901370293\">תו\"א בשלח סה, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380236\" data-slug=\"likkutei-torah\" data-id=\"4001380236\">לקו\"ת אמור לז, ג</a>."],["1249","11","<b>נעשה אדם בצלמנו</b>: בראשית א, כו."],["1250","12","<b>שבצלם אלקים עשה את האדם</b>: נח ט, ו."],["1251","13","<b>ועל דמות הכסא</b>: יחזקאל א, כו."],["1252","14","<b>אין לו דמות הגוף</b>: ע\"פ פיוט יגדל. ראה גם לעיל מאמר ד\"ה נעשה אדם ובהערה 31."],["1253","15","<b>והת\"ת. . רחמים</b>: ראה זח\"א בהשמטות רנא, ריש ע\"ב. פרדס שעה\"כ שכ\"ג, פ\"כ מערכת רחמים."],["1254","16","<b>לו ישמעאל יחי' לפניך</b>: לך יז, יח. ראה גם לעיל מאמר ד\"ה גור ארי' ספ\"ב ובהנסמן שם."],["1255","17","<b>ע\"פ שכלו יהולל איש</b>: משלי יב, ח."],["1256","18","<b>ואהבת. . בשני יצריך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9. לעיל המשך זאת חנוכת המזבח פט\"ז."],["1257","19","<b>היצה\"ר. . אהבת אלקות</b>: ראה גם לעיל המשך זאת חנוכת המזבח ספ\"א ואילך."],["1258","20","<b>במוח להיות שליט על הלב</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא פי\"ב</a>. מאמרי אדה\"א דברים ח\"ב ע' תצ. וש\"נ. ראה גם מאמרי אדה\"ז על ענינים ע' תיט ואילך. עט\"ר ע' 38 ואילך."],["1259","21","<b>שהוי' הוא האלקי'</b>: ואתחנן ד, לט."],["1260","22","<b>חמורים ד\"ס</b>: ראה ערובין כא, ב. סנהדרין פי\"א, מ\"ג (סנהדרין פח, ב). ירושלמי ברכות פ\"א, ה\"ד. ראה אגה\"ק סכ\"ג. אוה\"ת שלח ס\"ע תצא ואילך. סה\"מ תרל\"ד ע' קלט."],["1261","23","<b>מתעלה נפשו האלקי' ג\"כ</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תשמה. וש\"נ. סה\"מ תרל\"ד כאן הערה 18."]]],[2000470201,"ב) <b>ואמנם</b> הנה כ\"ז הוא כשפועל ישועות בנפשו לברר את נה\"ב ולהעלותה ועי\"ז מתעלה נפשו האלקי', אבל כשנמשך אחר שרירות לבו בעצת יצרו הרע המסיתו ומדיחו מדרך הטוב ומכשיל נפשו האלקי' ג\"כ עד שחוטא, ולא די במה שלא בירר את הנה\"ב אלא שגם נה\"א נפגמה בהעשותו הרע בעיני הוי' ואז מפיל נפשו האלקי' ג\"כ ומורידה מגדולתה וצריכים להעלותה ולתקנה, וע\"ז אמר אדם כי יקריב מכם פי' אם יתחיל בסדר עבודתו להקריב הנפש ולקרבה מנפילתה, מן הבהמה כו' תקריבו כו'. והענין הוא כי הנה הבהמה בשרשה גבוה מן האדם<sup data-n=\"1262\">24</sup> שהרי שרשה מעולם התהו שקדמה לעולם התיקון, רק שנפלה בשבירה, וע\"י שמעלים אותה ומקריבים אותה ע\"ג המזבח ונכללת באש שלמעלה עד שמגעת לשרשה הוא בחי' פני שור<sup data-n=\"1263\">25</sup> שבמרכבה, ועי\"ז והחיות נושאות את הכסא<sup data-n=\"1264\">26</sup> עם בחי' אדם שעל הכסא לבחי' אוא\"ס בחי' כי לא אדם הוא<sup data-n=\"1265\">27</sup>, וע\"י בירור התהו עי\"ז נמשך מאוא\"ס שלמעלה מתהו ותיקון ולכן עי\"ז מתמלאים כל הפגמים כו', ועכשיו תפלה במקום קרבנות תקנו<sup data-n=\"1266\">28</sup>, וע\"ז נתקן כל סדר התפלה כי האדם בקומו משנתו הנה הוא נעשה ברי' חדשה<sup data-n=\"1267\">29</sup>, וביצירת האדם נא' וייצר ה' אלקי'<sup data-n=\"1268\">30</sup> שם מלא, וכתי' וייצר בשני יודי\"ן שרומז ליצ\"ט ויצה\"ר וכמארז\"ל בתרין יצרין<sup data-n=\"1269\">31</sup>, ושרשם מב' שמות כי שרש נה\"א הוא מש' הוי' כמ\"ש כי חלק הוי'<sup data-n=\"1270\">32</sup> כו', והנה\"ב משתלשל מק\"ך צירופי<sup data-n=\"1271\">*34</sup> אלקים<sup data-n=\"1272\">33</sup> כמ\"ש במ\"א, ואז מיד בקומו משנתו שנעשה ברי' חדשה הרי אין לו עדיין במה להגביר נפשו האלקי' על נה\"ב כי הגם שהמוח שליט על הלב מ\"מ הרי עדיין לא התבונן כלל, ולכן ראשית כל מתחיל מודה אני<sup data-n=\"1273\">34</sup> שענין ההודאה היא הגם כי אינו משיג בשכלו שכן הוא מ\"מ הוא מודה על האמת, וכן",[["1262","24","<b>הבהמה בשרשה גבוה מן האדם</b>: ראה לעיל הערה 10."],["1263","25","<b>הבהמה בשרשה. . פני שור</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"ח. מאמרי אדה\"א שמות ח\"א ע' כח. וש\"נ. סה\"מ תרל\"ח ע' יח. וש\"נ."],["1264","26","<b>והחיות נושאות את הכסא</b>: ראה בחיי תרומה כה, י בשם הפדר\"א ספ\"ד. הנסמן במאמרי אדה\"א בראשית ע' שעג."],["1265","27","<b>כי לא אדם הוא</b>: שמואל-א טו, כט. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370317\" data-slug=\"torah-or\" data-id=\"3901370317\">תו\"א יתרו עא, ב</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370322\" data-slug=\"torah-or\" data-id=\"3901370322\">עב, ג</a>."],["1266","28","<b>תפלה במקום קרבנות תקנו</b>: ברכות כו, א-ב. ראה מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ. אוה\"ת תשא ע' א'תתפג."],["1267","29","<b>האדם. . ברי' חדשה</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי פכ\"ג ובהערה 593."],["1268","30","<b>וייצר ה' אלקי'</b>: בראשית ב, ז."],["1269","31","<b>וייצר בשני יודי\"ן. . בתרין יצרין</b>: בראשית ב, ז וראה בתרגום יוב\"ע שם. ברכות סא, א. זהר תזריע מו, ב. אוה\"ת בראשית כרך ג ע' 1046 ואילך. ע' תקכה."],["1270","32","<b>נה\"א. . כי חלק הוי'</b>: האזינו לב, ט. ראה גם לקמן (בחלק ההנחות) הנחה ד\"ה כמים הפנים סוף פיסקא א. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ד ד\"ה וככל. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואהבת את ה' אלקיך הא'."],["1271","*34","<b>מק\"ך צירופי אלקים</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה סמכוני באשישות ובהערה 73."],["1272","33","<b>והנה\"ב משתלשל. . אלקים</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830233\" data-slug=\"or-hatorah-hb\" data-id=\"8158830233\">אוה\"ת בלק ע' תתקיט</a>. ע' תתקנח. סה\"מ תרל\"ג ח\"ב ע' תפג."],["1273","34","<b>מיד בקומו. . מודה אני</b>: ראה שו\"ע אדה\"ז חאו\"ח מהדו\"ק ס\"א, ס\"ה. מהדו\"ת ס\"א, ס\"ו. סידור אדה\"ז במקומו. נדפס גם בהוספות לשו\"ע מהדורת קה\"ת. ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר כו' לך לך על יד הערה 59 ואילך. המשך תער\"ב ח\"א ע' תריט."]]],[2000470202,"בנוסח התפלה תקנו תחלה לאמר הודו לה'<sup data-n=\"1274\">35</sup> קראו בשמו, שהו\"ע ההודאה בכלל, ואח\"כ מתחיל בהתבוננות ואומר ב\"ש<sup data-n=\"1275\">36</sup> והי' העולם שבאמירת ע\"מ נבראו כל הנבראים והנוצרים והנעשים, ולהיות כן מובן כי אין ערוך הנברא לגבי הבורא<sup data-n=\"1276\">37</sup>, וכתי' כי עמך מקור חיים<sup data-n=\"1277\">38</sup>, שמקור החיים ומקור התענוגי' הוא עמך שהוא בטל וטפל לך, ואי לזאת באיזהו מהם יחפוץ, הלא דעת לנבון נקל<sup data-n=\"1278\">39</sup> כי למה לו לחפוץ בדבר הטפל ובטל, ואח\"כ מתחיל בהתבוננות מהנבראי' והנוצרים והנעשים איך שהם בטלים לגמרי ומהללים ומשבחים לשמו ית', כמ\"ש הללו את ה' מן השמים<sup data-n=\"1279\">40</sup> הללוהו במרומים הללוהו כל מלאכיו<sup data-n=\"1280\">41</sup> כו' וכל המזמור שחשיב ברואים שבשמים וברואים שבארץ ואח\"כ אומר לך ה' הגדולה<sup data-n=\"1281\">42</sup> כו' ואתה מחי' את כולם<sup data-n=\"1282\">43</sup>, ואי לזאת א\"א לו להיות כפוי טובה<sup data-n=\"1283\">44</sup> למי שבראו ויצרו ועשאו, וברא מזונותיו והצטרכותו בכל פרטי פרטיהם, עד שבברכת ק\"ש מתבונן איך שהשרפי' אומרים קדוש<sup data-n=\"1284\">45</sup>, והחיות והאופנים הם ברעש גדול על העדר השגתם<sup data-n=\"1285\">47</sup> שמשיגי' רק שיש מה שהוא קדוש ומובדל, אבל אינם משיגים את בחי' קדוש, ואי לזאת הם בבחי' רעש גדול ואומרים ברוך<sup data-n=\"1286\">46</sup> שיתברך ויומשך להם ג\"כ בחי' השגה זו ממקומו ממקורו ושרשו<sup data-n=\"1287\">48</sup> כו', ונודע כי הנה\"ב היא משמרי האופנים<sup data-n=\"1288\">49</sup>, ולכן כאשר מעמיק דעתו בהתבוננות זו תגיע גם אליה החפץ או הרצון עכ\"פ בדבר זה, עד שאח\"כ בק\"ש כשמתבונן איך שהוי' אלקינו הוי' אחד בז' רקיעים וארץ וד\"ר העולם<sup data-n=\"1289\">50</sup> ואין עוד זולתו עי\"ז גם הנה\"ב ישוב לאהבת השם עד שיפעול בנפשו להיות בבחי' תשוקת האהבה בכל לבבך בשני יצריך שגם היצה\"ר ישוב לאהבת ה', וזהו שאה\"כ וידעת היום<sup data-n=\"1290\">51</sup> והשבות אל לבבך כי הוי' הוא האלקי', שלכאו' יפלא מה\"ע מה שהוי' הוא האלקים למה שישוב אל לבבו, אך הענין הוא כנ\"ל ששרש היצ\"ט",[["1274","35","<b>תקנו תחלה לאמר הודו לה'</b>: דהי\"א טז, ח. ראה גם מאמרי אדה\"ז תקס\"ג ח\"א ע' קכד ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540173\" data-slug=\"torat-chaim\" data-id=\"2300540173\">תו\"ח וארא ח\"א עג, ב</a> ואילך."],["1275","36","<b>תחלה לאמר הודו. . ואומר ב\"ש</b>: נוסח ספרד ואריז\"ל."],["1276","37","<b>אין ערוך הנברא לגבי הבורא</b>: ראה גם שע\"ת עג, א ובהערה 2."],["1277","38","<b>כי עמך מקור חיים</b>: תהלים לו, י. ראה גם לעיל מאמר ד\"ה ואעשך לגוי גדול ובהערה 50."],["1278","39","<b>דעת לנבון נקל</b>: ע\"פ משלי יד, ו."],["1279","40","<b>הללו את ה' מן השמים</b>: תהלים קמח, א."],["1280","41","<b>הללוהו כל מלאכיו</b>: תהלים שם, ב."],["1281","42","<b>לך ה' הגדולה כו'</b>: דבהי\"א כט, יא."],["1282","43","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["1283","44","<b>כפוי טובה</b>: ראה ע\"ז ה, סע\"א. רש\"י נח יא, ה."],["1284","45","<b>שהשרפי' אומרים קדוש</b>: ישעי' ו, ג. ראה חולין צא, ב. ובתוד\"ה ברוך (שם צב, רע\"א)."],["1285","47","<b>והחיות והאופנים. . העדר השגתם</b>: ראה גם לעיל המשך זאת חנוכת המזבח פ\"ד."],["1286","46","<b>והחיות והאופנים. . ברוך</b>: יחזקאל ג, יב. ראה חולין צב, רע\"א ובתוד\"ה ברוך. ראה גם סה\"מ תרל\"ד ע' רנד."],["1287","48","<b>ממקומו ממקורו ושרשו</b>: ראה גם לעיל שם ספ\"ז ובהערה 126."],["1288","49","<b>הנה\"ב היא משמרי האופנים</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380083\" data-slug=\"likkutei-torah\" data-id=\"4001380083\">לקו\"ת ויקרא ב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381021\" data-slug=\"likkutei-torah\" data-id=\"4001381021\">האזינו עד, ג</a>."],["1289","50","<b>בק\"ש. . אחד בז'. . וד\"ר העולם</b>: ואתחנן ו, ד. ראה שו\"ע אדה\"ז הל' ק\"ש סס\"א, ס\"ו. ראה גם לקו\"ת תזריע כג, ג<sup data-n=\"e71\">ג</sup>. שמע\"צ פח, ב<sup data-n=\"e72\">ד</sup>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370248\" data-slug=\"torah-or\" data-id=\"3901370248\">תו\"א וארא נה, ב</a> ואילך. סהמ\"צ להצ\"צ ע' קכד ואילך. סה\"מ תרכ\"ט ע' קסד."],["1290","51","<b>וידעת היום</b>: ואתחנן ד, לט.\n\n<b>ג</b>  ראה גם לקמן המשך מצה זו פנ\"א.\n\n<b>ד</b>  ראה גם לקמן שם פכ\"ט."]]],[2000470203,"והיצה\"ר הם מב' שמות הוי' ואלקי' שיצה\"ר נשתלשל מצירופי' אחרונים דשם אלקי'<sup data-n=\"1291\">*52</sup>, ולכן ע\"י שישוב אל לבבו להיות בכל לבבך בשני יצריך עי\"ז יתחזק אצלו הידיעה איך כי הוי' הוא האלקי' כולא חד<sup data-n=\"1292\">52</sup> בלא פרודא כלל, וצ\"ל בבחי' דעת והכרה שזהו הציווי וידעת<sup data-n=\"1293\">53</sup> בבחי' דעת והכרה ולא בדרך העברה בעלמא כ\"א להתבונן ולקשר דעתו בחוזק<sup data-n=\"1294\">54</sup> כאומרו דע את אלקי אביך<sup data-n=\"1295\">55</sup> והיינו ע\"י שיעבדהו בלב שלם היינו בכל לבבך בשני יצריך כו'. והנה ע\"י בירור נה\"ב והבאתו שיבא לאהבה את ה' הנה עי\"ז מתעלית הנה\"א בעילוי אחר עילוי כי הנה\"ב גדולה ורב כחה להעלות הנה\"א בעילוי אחר עילוי כו', וכמ\"ש מזה בת\"א ד\"ה ונתתי לך מהלכים<sup data-n=\"1296\">56</sup> ובכ\"ד.\nג) <b>ואמנם</b> כדי שיוכל להעלות את הבהמה צריכה תחלה לסמיכה שז\"ע מ\"ש וסמך ידו על ראש העולה, פי' העולה היא נפש הבהמה העולה מנפילתה בשבה\"כ צריכה להיות נסמכת מהאדם, ע\"י שסומך שתי ידיו עליו בכל כחו. והענין הוא דהנה אנו רואים שיש כח ביד להעלות את האבן עד\"מ היפך טבעו ורגילותו, שטבע האבן הוא ליפול למטה ולא שיעלה במעלות ברום שמים, ואמנם כשזורקו בידו הרי אנו רואים שעולה מעלה מעלה היפך טבעו, והיינו מפני שנמשך אור מקיף מהיד ע\"ג האבן ומקיפו ונושאו ברום שמים עד שתכלה כח היד ואז נופל לארץ, כמש\"נ מזה בד\"ה ועתה יגדל נא כח אד' שלא נדפס<sup data-n=\"1297\">57</sup>, ועד\"ז יובן בהקרבת הבהמה להיות כי הבהמה בעצם הנה נפש הבהמה היא היורדת למטה לארץ<sup data-n=\"1298\">58</sup> ובכדי שיהי' בה כח לעלות צריכה סמיכה מבחי' אדם, וזהו וסמך ידו על ראש העולה, והסמיכה צ\"ל בכל כחו בשתי ידיו, כח בגימ' ב\"פ יד<sup data-n=\"1299\">59</sup>.\n<b>ועפ\"ז</b> יובן ג\"כ ענין הסמיכה מה שהמל' נסמכת בת\"ת ז\"ע וסמך את ידו, וסמיכה בשתי ידיו היינו שמאלו תחת לראשי<sup data-n=\"1300\">60</sup> וימינו תחבקני להעלותה,",[["1291","*52","<b>מצירופי' אחרונים דשם אלקי'</b>: ראה לקמן (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גן נעול הב' הערה 50."],["1292","52","<b>הוי' הוא האלקי' כולא חד</b>: ראה זהר בהקדמה יב, א. תרומה קסא, א ואילך. מאמרי אדה\"א דברים ח\"א ע' קעה ובהנסמן בריש המאמר שם. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540095\" data-slug=\"torat-chaim\" data-id=\"2300540095\">תו\"ח וארא ח\"א ס, א</a>. וש\"נ. סה\"מ תרל\"ג ח\"ב ע' תה ואילך. וש\"נ."],["1293","53","<b>הציווי וידעת</b>: ראה גם שע\"ת סג, א ובהערה 3."],["1294","54","<b>ולקשר דעתו בחוזק</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא פ\"ג</a>. וראה גם סה\"מ תש\"ד ע' 163."],["1295","55","<b>דע את אלקי אביך</b>: דבהי\"א כח, ט."],["1296","56","<b>בת\"א ד\"ה ונתתי לך מהלכים</b>: ל, סע\"א ואילך."],["1297","57","<b>בד\"ה ועתה יגדל נא. . שלא נדפס</b>: ראה גם מאמרי אדה\"ז תקס\"ו ע' רמח. מאמרי אדה\"א במדבר ח\"ג ע' א'נו. ולהעיר מאוה\"ת ויקרא ע' רכב שמציין סד\"ה ועתה יגדל נא כח אד' — <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380469\" data-slug=\"likkutei-torah\" data-id=\"4001380469\">לקו\"ת שלח לט, ב</a>. ראה גם מאמרי אדה\"א נ\"ך ע' קעז. וש\"נ."],["1298","58","<b>נפש הבהמה היא היורדת למטה לארץ</b>: ראה קהלת ג, כא."],["1299","59","<b>כח בגימ' ב\"פ יד</b>: ראה גם ספר סדר היום בכוונת הקדיש (ע' 12). ביאוה\"ז ויחי לו, סע\"א. אוה\"ת ויקרא שם."],["1300","60","<b>שמאלו תחת לראשי</b>: שה\"ש ב, ו."]]],[2000470204,"וע\"י עליה זו הוא המעלה אותו ג\"כ ע\"ד והחיות נושאות את הכסא לבחי' כי לא אדם הוא כו' כנ\"ל, א\"כ נסמך הת\"ת ע\"י המל' כו', וזהו בבחי' מל' שרש כנס\"י כו', וכמו\"כ בפרט בכאו\"א קודם התפלה שהוא עיקר ההעלאה אומרים תהלות לאל עליון<sup data-n=\"1301\">61</sup>, שאז יורד המשכה מבחי' אור אבא לצורך ההעלאה, וכמו הכהן המקריב את הקרבן צריך קידוש ידים<sup data-n=\"1302\">62</sup> כן האדם בקומו משנתו צריך נט\"י<sup data-n=\"1303\">63</sup>, וגם נט\"י לתפלה<sup data-n=\"1304\">64</sup>, ולובש טלית<sup data-n=\"1305\">65</sup> ותפילין<sup data-n=\"1306\">66</sup> שהם המצות המסייעין אותו לצורך הגבהת נה\"ב, גם ארז\"ל אלמלא עוזרו<sup data-n=\"1307\">67</sup> לא הוה יכול לו ה\"ז הסיוע הנמשך מלמעלה, גם לימוד התורה שקודם התפלה<sup data-n=\"1308\">68</sup> מסייע לבירור נה\"ב ע\"ד עוז ותושי'<sup data-n=\"1309\">69</sup> שנותן כח לנה\"א, ומתיש כח הנה\"ב שירצה בבחי' הבירור. וזהו וסמך ידו על ראש העולה כו', ושתי ידיו הם תושב\"כ ותושבע\"פ, ובכל כחו ע\"ד שארז\"ל אם ערוכה בכל<sup data-n=\"1310\">70</sup> שמורה<sup data-n=\"1311\">71</sup> אם ערוכה ברמ\"ח אברים<sup data-n=\"1312\">72</sup> שמורה שז\"ע בשני ידיו בכל כחו כו'.",[["1301","61","<b>קודם התפלה. . תהלות לאל עליון</b>: סיום פיסקא עזרת אבותינו. ראה פע\"ח שער הק\"ש פכ\"ט. שער הכוונות שם דרוש ז קרוב לסופו. מאמרי אדה\"ז על מארז\"ל ע' נז. אוה\"ת ויקהל ע' ב'קיח. ויקרא שם."],["1302","62","<b>הכהן. . קידוש ידים</b>: ראה רמב\"ם הל' ביאת מקדש פ\"ה, ה\"א."],["1303","63","<b>הכהן. . כן האדם בקומו משנתו צריך נט\"י</b>: ראה שו\"ע אדה\"ז חאו\"ח מהדו\"ק ומהדו\"ת רס\"ד. סידור אדה\"ז במקומו (סדר הנטילה). נדפס גם בהוספות לשו\"ע מהדורת קה\"ת."],["1304","64","<b>נט\"י לתפלה</b>: ראה שו\"ע אדה\"ז שם (במהדו\"ק שם, ס\"ג). סידור שם."],["1305","65","<b>ולובש טלית</b>: ראה גם מאמרי אדה\"א במדבר ח\"ד ס\"ע א'שיג ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550878\" data-slug=\"torat-chaim\" data-id=\"2300550878\">תו\"ח ויקהל ח\"ב תלו, ג</a>. בהערה הבאה."],["1306","66","<b>ולובש טלית ותפילין</b>: ראה גם מאמרי אדה\"א בראשית ע' שצד. שמות ח\"ב ע' תרטו."],["1307","67","<b>אלמלא עוזרו</b>: קדושין ל, ב. סוכה נב, ב. ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310018\" data-slug=\"tanya\" data-id=\"3401310018\">תניא רפי\"ג</a>."],["1308","68","<b>לימוד התורה שקודם התפלה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380891\" data-slug=\"likkutei-torah\" data-id=\"4001380891\">לקו\"ת תבוא מג, ג</a>. סה\"מ תרנ\"ח ע' רלה. קונט' עה\"ח פכ\"ה ס\"ע 52. וש\"נ. וראה סה\"מ תרל\"ח ע' תמח."],["1309","69","<b>התורה. . עוז ותושי'</b>: ראה מכילתא דרשב\"י יתרו פי\"ט, טז. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380099\" data-slug=\"likkutei-torah\" data-id=\"4001380099\">לקו\"ת ויקרא ו, ב</a>. מאמרי אדה\"א ויקרא ח\"ב ע' תקעח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300541054\" data-slug=\"torat-chaim\" data-id=\"2300541054\">תו\"ח בשלח ח\"א קפד, א</a>. וש\"נ."],["1310","70","<b>אם ערוכה בכל</b>: ראה עירובין נד, רע\"א."],["1311","71","<b>ערוכה בכל שמורה</b>: שמואל-ב כג, ה [ושם: ושמורה]."],["1312","72","<b>ברמ\"ח אברים</b>: אהלות פ\"א, מ\"ח. ערובין שם."]]],[2000470205,"<h3>מצה זו</h3>\n<b>בס\"ד. חגה\"פ. מ\"ם</b>\n&lt;1&gt;\nּ <b>מצה</b> זו<sup data-n=\"1313\">1</sup> שאנו אוכלים ע\"ש מה ע\"ש שלא הספיק כו' עד שנגלה עליהם<sup data-n=\"1314\">2</sup> ממה\"מ הקב\"ה וגאלם, וצ\"ל איזהו קשר וחיבור יש למצה זו<sup data-n=\"1315\">3</sup> דעכשיו למה שנגלה עליהם ממה\"מ, מלבד מה שגם אכילת מצה שבמצרים שנצטוו בערב תאכלו מצות<sup data-n=\"1316\">4</sup> זה הי' קודם חצות, ומה שנגלה עליהם ממה\"מ זה הי' לאחר חצות, הנה הציווי שלדורות חיוב אכילת מצה לילה הראשונה זהו מצוה מתרי\"ג מצות<sup data-n=\"1317\">5</sup> ומהו הקישור וחיבור למה שנגלה עליהם ממה\"מ דמשמע גם אם לא הי' הציווי דאכילת כזית מצה<sup data-n=\"1318\">6</sup> בלילי פסח הנה מחמת שנגלה עליהם ממה\"מ ע\"ש זה אנו אוכלים מצה, ובאמת הטעם דאכילת מצה בלילי פסח זהו מטעם ציווי דמצוה זו, אלא שצ\"ל שעם",[["1313","1","<b>מצה זו</b>: מכאן ועד סד\"ה וביאור ענין משתשקע הוא המשך הנודע בשם ”מצה זו — תר\"ם\" ונדפס בשם: לקו\"ת תורת שמואל ש\"ז (ספר התולדות של כ\"ק אדמו\"ר מהר\"ש<sup data-n=\"e73\">א</sup> ע' 52 הערה 10).\nהמשך זה הכולל כ [כב] מאמרים (שהם ס\"ד פרקים), נאמר מליל ב' דחגה\"פ עד שבת פ' דברים.\nראה גם סה\"ש תש\"נ ח\"ב ע' 420 הערה 43.\nמאמר דידן כפי שמופיע לפנינו הנה הוא כולל ד' פרקים. אמנם בבוך 224 נמצא חלוקה אחרת והוא, שמאמר הראשון כולל רק ג\"פ, וקודם פרק ד נרשמה כותרת: ב' דפסח. ועפ\"ז הנה המאמר כפי שהוא לפנינו נאמר בב' פעמים, היינו שג\"פ נאמרו בליל ב' דחה\"פ. ופ\"ד נאמר ביום ב' דפסח<sup data-n=\"e74\">ב</sup>. ולקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב ישנו גם פתיחא חדשה להמאמר השני והיא: משה קבל.\nמאמר זה פ\"א (לאחרי ההתחלה) — ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770441\" data-slug=\"or-hatorah-hb\" data-id=\"8316770441\">אוה\"ת שה\"ש ח\"ב ע' תמא</a> ואילך (והוא לשונו).\nפ\"ב — ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770429\" data-slug=\"or-hatorah-hb\" data-id=\"8316770429\">אוה\"ת שה\"ש ח\"ב ע' תכט</a> (והוא לשונו עם הוספות וכו'). אגה\"ק ס\"ה קז, א.\nפ\"ג — ראה אוה\"ת שה\"ש ח\"ב ע' תכט ואילך (והוא לשונו בשינויים והוספות). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381260\" data-slug=\"likkutei-torah\" data-id=\"4001381260\">לקו\"ת שה\"ש לב, סע\"ד</a> ואילך (והוא לשונו בשינויים קלים).\nפ\"ד — ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381103\" data-slug=\"likkutei-torah\" data-id=\"4001381103\">לקו\"ת ברכה</a> (ביאור ע\"פ תורה צוה) צד, סע\"א ואילך (והוא לשונו בשינויים והוספות). אוה\"ת ח\"ש כרך ז ע' 2419. אגה\"ק סי\"ט.\nהנחות<sup data-n=\"e75\">ג</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסו לקמן (בחלק הנחותיו<sup data-n=\"e76\">ד</sup>)."],["1314","2","<b>מצה זו. . עד שנגלה עליהם</b>: נוסח ההגדה. ראה גם להבא בסמוך <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380122\" data-slug=\"likkutei-torah\" data-id=\"4001380122\">לקו\"ת צו יא, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380125\" data-slug=\"likkutei-torah\" data-id=\"4001380125\">יב, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380128\" data-slug=\"likkutei-torah\" data-id=\"4001380128\">יג, א</a>. ב. אוה\"ת בא ע' שז. לקמן רפמ\"א."],["1315","3","<b>זו</b>: ניתוסף בפנים ע\"פ המשך הנדפס."],["1316","4","<b>בערב תאכלו מצות</b>: בא יב, יח. ראה גם לקמן רפמ\"א."],["1317","5","<b>אכילת מצה. . מתרי\"ג מצות</b>: ראה רמב\"ם הל' חו\"מ רפ\"ו. בהכותרת לשם מצוה ז במנין המצות שבריש ספרו ובסהמ\"צ מ\"ע קנח."],["1318","6","<b>מצה</b>: בהמשך הנדפס ליתא.\n\n<b>א</b>  מהדורת קה\"ת תש\"ז.\n\n<b>ב</b>  ראה בסמוך הערה ד אות *ב ובהערה 1.\n\n<b>ג</b>  ויש להוסיף הנחות אלו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז.\n\n<b>ד</b>  <b>להלן באה רשימת הדרושים כפי שמופיעה בספר התולדות הנ\"ל ובחצאי ריבוע ניתוספו בריש הדרוש פתיחת הדרושים כפי שהם מופיעים בהנחות כ\"ק אדמו\"ר מהורש\"ב. </b>\n<b>א) מצה זו — (פרקים א-ד), </b>[ליל ב' ד]<b>חגה\"פ. </b>\n[*ב) משה קבל]<b> וביאור הענין הנה תושב\"כ [פ\"ד]. בבוך 224 שי, ב נרשם כותרת</b>: ב' דפסח1].\nב) אז ישיר — (פרקים ה-יו\"ד), שש\"פ.\n[*ג) ועוי\"ל פי' למען יזמרך [פרקים ח-יו\"ד), בבוך 224 שיג, ב נרשם כותרת: שמיני ש\"פ].\nג) [גן נעול] והנה כו' גן נעול — (פרקים יא-יג), פ' שמיני.\nד) [גן נעול] והנה בתרגום פי' גן נעול — (פרקים יד-טז), פ' תזו\"מ.\nה) גל נעול מעין חתום — (פרקים יז-יט), פ' אחו\"ק.\nו) [אל יתהלל החכם] ויובן כו' בינה יתרה — (פרקים כ-כא), ל\"ג בעומר.\nז) ויובן כו' בינה יתרה כו' חכמות בחוץ — (פרקים כב-כד), פ' אמור.\nח) צאינה וראינה כו' וע\"ד שנת\"ל בבחי' הדבור — (פרקים כה-כז), פ' בהו\"ב.\nט) וירא העם וינועו כו' בינה יתרה — (פרקים כח-למד), פ' במדבר.\nי) וביום הבכורים כו' והנה כאשר נמשך — (פרקים לא-גל), חה\"ש.\nיא) ויאמר כו' אל תיראו כו' ויובן בהקדם — (פרקים לד-לו), חה\"ש.\nיב) [כי טובים דודיך מיין] והנה בתושבע\"פ כו' ערבים עלי — (פרקים לז-טל), פ' נשא.\nיג) המזבח עץ כו' וביאור ענין ערבים — (פרקים מ-מב), פ' בהעלתך.\nיד) [ערבים עלי דברי דודיך] ויובן כו' ענין נט\"י — (פרקים מג-מה), פ' שלח.\nטו) ועפי\"ז כו' ויפוזו זרועי ידיו — (פרקים מו-מח), פ' קרח.\nטז) וכמו כו' במצות ערובין — (פרקים מט-נא), פ' חקת.\nיז והנה כו' יושב אוהלים — (פרקים נב-נד), פ' בלק.\nחי) וזהו דכתיב מגיד דבריו ליעקב — (פרקים נה-נח), פנחס. בבוך 224 שלט, ב בכותרת: על ברית מילה2 ובפ' פנחס.\nיט) [ואלא עלמא אמאי קאים] ועד\"ז יובן ג\"כ בנ\"ח — (פרקים נט-סא), פ' מטו\"מ.\nכ) [ר\"א פתח והמה כאדם] וביאור ענין משתשקע החמה — (פרקים סב-סד), פ' דברים.\nועפ\"ז מובן בפשטות מה שלאחרי הקיצור לפ\"ג בא הפיסקא ועפ\"ז יובן שהוא הסיום להתחלת המאמר הראשון — מצה זו.\nהברית מילה שנזכר כאן הוא כנראה של נכדו כ\"ק אדמו\"ר מהוריי\"צ שנולד יום ב' י\"ב תמוז תר\"מ פ' בלק. והברית הי' ביום ב' פ' פנחס י\"ט תמוז. וראה גם לקמן הערה *1585 שהמאמר נאמר ב\"פ."]]],[2000470206,"היות שאכילת מצה הוא מפני הציווי שנצטוינו לדורות, עכ\"ז יש קישור וחיבור לאכילת מצה עם מה שנגלה עליהם ממה\"מ כו' וצ\"ל מהו. ויובן בהקדם ענין גן נעול אחותי כלה גל נעול<sup data-n=\"1319\">7</sup> מעין חתום, וארז\"ל ברבות<sup data-n=\"1320\">8</sup> בא פט\"ו דקל\"א ע\"ב<sup data-n=\"1321\">9</sup> ע\"פ ויאמר ה' אל משה<sup data-n=\"1322\">10</sup> ואל אהרן באמ\"צ לאמר, מה הקב\"ה עושה במצרים בשביל ישראל א\"ר יצחק נפחא משל למטרונה שהיתה מקטרגת<sup data-n=\"1323\">11</sup> למלך נתנה בפילקי (בבית הסוהר<sup data-n=\"1324\">12</sup> ) והלך לו, הי' המלך עמה<sup data-n=\"1325\">13</sup> בפילקי, אמרו לו מה איכפת לך אמר להם כל ימים<sup data-n=\"1326\">14</sup> שאני עמה אינה נוטלת שם רע, כך נשתעבדו ישראל במצרים ונגלה<sup data-n=\"1327\">15</sup> הקב\"ה<sup data-n=\"1328\">16</sup> עמהם שנא' אנכי ארד עמך מצרימה<sup data-n=\"1329\">17</sup> ואנכי אעלך כו'<sup data-n=\"1330\">18</sup>, וכן",[["1319","7","<b>גן נעול. . גל נעול</b>: שה\"ש ד, יב. וכן צ\"ל בהמשך הנדפס."],["1320","8","<b>ברבות</b>: מכאן עד סיום הפרק הועתק מ<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770441\" data-slug=\"or-hatorah-hb\" data-id=\"8316770441\">אוה\"ת שה\"ש ח\"ב ע' תמא</a> ואילך."],["1321","9","<b>ברבות בא פט\"ו דקל\"א ע\"ב</b>: בדפוס אמשטרדם ת\"א, ולפנינו פט\"ו, טז."],["1322","10","<b>ויאמר ה' אל משה</b>: בא יב, א."],["1323","11","<b>מקטרגת</b>: וכ\"ה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן. בהמשך הנדפס: מקנטרת."],["1324","12","<b>בבית הסוהר</b>: מתנות כהונה שם."],["1325","13","<b>המלך עמה</b>: במדרש ובאוה\"ת שם: עמה המלך."],["1326","14","<b>ימים</b>: שם לקמן בהנחה כאן המשך תער\"ב ח\"ב ע' א'קלח: הימים."],["1327","15","<b>ונגלה</b>: באוה\"ת לקמן בהנחה כאן: וגלה. וכ\"ה ביפ\"ת שם."],["1328","16","<b>הקב\"ה</b>: במדרש: הקב\"ה כביכול."],["1329","17","<b>אנכי ארד עמך מצרימה</b>: ויגש מו, ד."],["1330","18","<b>ואנכי אעלך כו'</b>: וכ\"ה לקמן בהנחה כאן [ושם: ואנכי אעלך גם עלה]. במדרש ובאוה\"ת שם ליתא. בהמשך תער\"ב: כו'."]]],[2000470207,"בבבל שנא' למענכם שולחתי<sup data-n=\"1331\">20</sup> בבלה<sup data-n=\"1332\">19</sup> כו' א\"ל להקב\"ה כל כך למה אמר להם כל הימים שאני עמהם אין נוטלים שם רע, במצרים הייתי עמהם ונמצאת שלימה שנא' גן נעול אחותי כלה עכ\"ל. והיינו שע\"י השראת קדושתו ית' עליהם הי' להם לשומר ולהגין שלא יבואו לידי עבירה, וזהו הנה לא ינום<sup data-n=\"1333\">21</sup> ולא יישן שומר ישראל, והגם כי הכל בידי שמים<sup data-n=\"1334\">22</sup> חוץ מיראת שמים עכ\"ז הרי מקרא מלא כתי' גבי אבימלך ואחשוך גם אנכי<sup data-n=\"1335\">23</sup> אותך מחטו לי, ועמ\"ש ע\"פ מי יתן והי' לבבם זה להם ליראה אותי<sup data-n=\"1336\">24</sup> כו', היינו מי יתן שבחי' זו נמשך מבחי' מי, וזשארז\"ל הי' להם לומר תן אתה<sup data-n=\"1337\">25</sup>, והיינו בחי' מי הנז'<sup data-n=\"1338\">26</sup>, ועד\"ז ארז\"ל פ\"ג דסוטה מצוה מגינא ומצלא שלא יבא לידי עבירה כו', וכ\"ש תורה<sup data-n=\"1339\">27</sup> כו', א\"כ לפ\"ז י\"ל הפירוש שזה שהי' גן נעול, נמשך מלמעלה, והיינו ג\"כ ע\"י גן היינו ג\"ן סדרים דאורייתא<sup data-n=\"1340\">28</sup> שהיו ראוים לקבל כו', לכן אורות ג\"ן סדרים הגינו עליהם שיהי' גן נעול.\n<b></b>קיצור. ע\"י שאני עמהם כו' במצרים הייתי עמהם ונמצאת שלימה שנא' גן נעול, שהוא ית' שומר ישראל, והגם כי הכל כו' חוץ כו' אך מי יתן ועד\"ז מצוה מגינא וכ\"ש תורה, א\"כ ע\"י אורות ג\"ן סדרים, נעשה גן נעול.\n(ב) <b>והנה</b><sup data-n=\"1341\">29</sup> בת\"ז תיקון י\"ט פי' שהשכינה נק' גן<sup data-n=\"1342\">30</sup> ע\"ש שכלולה מג\"ן סדרים דאורייתא וזהו ענין &lt;2&gt;\nּ גן נעול כו', ויש לפרש זה על תושבע\"פ שנק' כלה ע\"ש שמקבלת הכל מתושב\"כ כן פי' רבינו בד\"ה ומשוש חתן על כלה ויצא תקס\"ח<sup data-n=\"1343\">31</sup>, והיינו שתושבע\"פ אין בה כ\"א פי' על תושב\"כ לכן תושב\"כ נק' חתן ותושבע\"פ נק' כלה<sup data-n=\"1344\">32</sup>, וזהו שנקראת גן שהיא מקבלת מג\"ן סדרים דאורייתא שבתושב\"כ.",[["1331","20","<b>שולחתי</b>: וכ\"ה לקמן בהנחה כאן. בכל הנ\"ל: שלחתי — ראה יפ\"ת ופי' מהרז\"ו לשמו\"ר שם."],["1332","19","<b>למענכם שולחתי בבלה</b>: ישעי' מג, יד."],["1333","21","<b>הנה לא ינום</b>: תהלים קכא, ד."],["1334","22","<b>הכל בידי שמים</b>: ברכות לג, ב."],["1335","23","<b>ואחשוך גם אנכי</b>: וירא כ, ו."],["1336","24","<b>מי יתן. . ליראה אותי</b>: ואתחנן ה, כו. ראה אוה\"ת ואתחנן ע' קצה ואילך."],["1337","25","<b>הי' להם לומר תן אתה</b>: ע\"ז ה, סע\"א."],["1338","26","<b>והיינו. . הנז'</b>: באוה\"ת שה\"ש כאן ליתא."],["1339","27","<b>מצוה מגינא. . וכ\"ש תורה</b>: ראה סוטה כא, א. ש\"א יב, א ובהערה 6."],["1340","28","<b>ג\"ן סדרים דאורייתא</b>: ראה זהר מדהנ\"ע וירא קד, ב. מאמרי אדה\"א דברים ח\"ד ע' א'רג. וש\"נ."],["1341","29","<b>והנה</b>: מכאן עד להלן על יד הערה 43 הוא לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770429\" data-slug=\"or-hatorah-hb\" data-id=\"8316770429\">אוה\"ת שה\"ש ח\"ב ע' תכט</a>."],["1342","30","<b>בת\"ז. . שהשכינה נק' גן</b>: לט, א."],["1343","31","<b>בד\"ה ומשוש חתן על כלה ויצא תקס\"ח</b>: נדפס במאמרי אדה\"ז הנחות הר\"פ ע' סג. ראה לעיל המשך זאת חנוכת המזבח פכ\"א ובהערה 569."],["1344","32","<b>תושב\"כ נק' חתן ותושבע\"פ נק' כלה</b>: ראה גם לעיל שם הערה 570."]]],[2000470208,"<b>גם</b> יש לפרש זה על השכינה מקור נש\"י, כי הנה ס\"ר נשמות כלליים<sup data-n=\"1345\">33</sup> שרשן<sup data-n=\"1346\">35</sup> מס\"ר אותיות התורה<sup data-n=\"1347\">36</sup>, וכמ\"ש מזה<sup data-n=\"1348\">37</sup> בלק\"ת בד\"ה את שבתותי תשמורו פ\"א<sup data-n=\"1349\">34</sup>, והנה האותיות מקבלים מבחי' חו\"ב, וזהו ונהר יוצא מעדן<sup data-n=\"1350\">38</sup> להשקות<sup data-n=\"1351\">39</sup> את הגן הוא בחי' ג\"ן<sup data-n=\"1352\">40</sup> סדרים דאורייתא שהם אותיות התורה אשר נהר הוא הבינה<sup data-n=\"1353\">41</sup> שהוא יוצא מעדן חכ' עילאה<sup data-n=\"1354\">42</sup> להשקות את האותיות<sup data-n=\"1355\">43</sup>, ואמנם הנה זהו רק להשקות את האותיות<sup data-n=\"1356\">44</sup>, היינו לאחר שהם נעשים מציאות אותיות<sup data-n=\"1357\">45</sup>, אז להשקותם זהו נמשך מבחי' הנהר דבינה שהוא בחי' ההשגה והבנה, שבחי' השגה והבנה זו יוצא מעדן בחי' ח\"ע, אבל עצם מציאות האותיות הנה שרשם הם מבחי' ח\"ע עצמה שנק' קדמות השכל כמ\"ש באגה\"ק סי' ה' ד\"ה<sup data-n=\"1358\">46</sup> ויעש דוד שם, דהנה יש ב' בחי' באותיות התורה, הא' הוא עצם בחי' האותיות, והב' הוא בחי' אור ההשכלה המלובש בהאותיות, ועד\"מ התהוות<sup data-n=\"1359\">47</sup> אותיות הדבור היוצאות<sup data-n=\"1360\">48</sup> מה' מוצאות הפה אינם דבר מושכל ולא מוטבע בטבע מוצאות הללו<sup data-n=\"1361\">49</sup> להוציא מבטא האותיות ע\"י הבל וקול<sup data-n=\"1362\">50</sup> המכה<sup data-n=\"1363\">51</sup> בהן ע\"פ דרך הטבע ולא ע\"פ השכל<sup data-n=\"1364\">52</sup> כגון השפתים עד\"מ שאותיות בומ\"ף יוצאות מהן אין הטבע ולא השכל נותן ליציאת<sup data-n=\"1365\">53</sup> ארבע חלקי שינוי ביטוי אותיות אלו ע\"פ שינוי תנועת השפתים שמתנוענעות בהבל א' וקול א' הפוגע בהן בשוה<sup data-n=\"1366\">54</sup>, ובמ\"א נת' שאל\"כ הי' צריך להיות שהיות זמן<sup data-n=\"1367\">55</sup> עד שיצאו האותיות, וכמו המכה",[["1345","33","<b>ס\"ר נשמות כלליים</b>: ראה רמב\"ן בדרשת תורת ה' תמימה [כתבי הרמב\"ן ח\"א ירושלים תשכ\"ד ע' קסב]: וקבלת רז\"ל כי לא נבראו בשנוי פרצופים אלא בששים ריבוא. תניא פל\"ז. מאמרי אדה\"ז תקס\"ו ס\"ע קצ ואילך. תק\"ע ע' קד. סה\"מ תרמ\"ד ע' רסה. תרע\"ח ע' שיב."],["1346","35","<b>שרשן</b>: וכ\"ה באוה\"ת שה\"ש כאן. בהמשך הנדפס: שרשים ועד\"ז בלקו\"ת דלעיל: שרשיים."],["1347","36","<b>מס\"ר אותיות התורה</b>: ראה ז\"ח שה\"ש עד, ד. מג\"ע אופן קפו. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201432\" data-slug=\"likkutei-sichot\" data-id=\"1300201432\">לקו\"ש</a> טו\"ב כסלו תשמ\"א כרך כ ע' 419 בהערה. שו\"ת הצ\"צ חאבהע\"ז סרמ\"ט (צה, א)."],["1348","37","<b>מזה</b>: ניתוסף בפנים ע\"פ המשך הנדפס. וכ\"ה באוה\"ת שה\"ש כאן."],["1349","34","<b>ס\"ר נשמות כלליים. . התורה. . בלק\"ת. . פ\"א</b>: בהר מא, ב."],["1350","38","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["1351","39","<b>ונהר. . להשקות. . ג\"ן סדרים דאורייתא</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540658\" data-slug=\"torat-chaim\" data-id=\"2300540658\">תו\"ח שמות ח\"א ז, ד</a>. וש\"נ."],["1352","40","<b>הוא בחי' ג\"ן</b>: באוה\"ת שה\"ש כאן ליתא."],["1353","41","<b>נהר הוא הבינה</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">תו\"א משפטים עה, ד</a>: כמ\"ש בזהר פ' אמור [צט, א]."],["1354","42","<b>מעדן חכ' עילאה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540332\" data-slug=\"torat-chaim\" data-id=\"2300540332\">תו\"ח בשלח ח\"א קמא, א</a> ובהערה 98."],["1355","43","<b>האותיות</b>: ע\"כ הועתק מאוה\"ת שה\"ש. ראה לעיל הערה 29."],["1356","44","<b>רק להשקות את האותיות</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770088\" data-slug=\"or-hatorah-hb\" data-id=\"8316770088\">אוה\"ת שה\"ש ח\"ב ע' תנד</a>."],["1357","45","<b>אותיות</b>: בהמשך הנדפס: יש."],["1358","46","<b>קדמות השכל. . סי' ה' ד\"ה</b>: שם: סד\"ה. ראה שם (קז, ב). (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה כי הנה יוצר הרים הערה 23."],["1359","47","<b>התהוות</b>: מכאן עד להלן על יד הערה 54 הוא לשון אגה\"ק ס\"ה קז, א."],["1360","48","<b>היוצאות</b>: בהמשך הנדפס: היוצאי'. באגה\"ק כבפנים."],["1361","49","<b>בטבע מוצאות הללו</b>: שם: מוצאות. באגה\"ק כבפנים."],["1362","50","<b>הבל וקול</b>: באגה\"ק: ההבל והקול."],["1363","51","<b>המכה</b>: בהמשך הנדפס: המשכה. באגה\"ק כבפנים."],["1364","52","<b>השכל</b>: באגה\"ק: דרך השכל."],["1365","53","<b>ליציאת</b>: שם: ליציאת מבטא. אבל כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200218\" data-slug=\"or-hatorah-hb\" data-id=\"8159200218\">אוה\"ת ויקרא כ\"ג ע' תתקלד</a>."],["1366","54","<b>בשוה</b>: ע\"כ לשון האגה\"ק. ראה לעיל הערה 47."],["1367","55","<b>ובמ\"א. . שהיות זמן</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200219\" data-slug=\"or-hatorah-hb\" data-id=\"8159200219\">אוה\"ת ויקרא כ\"ג ע' תתקלה</a>. סה\"מ תרל\"ג ח\"ב ע' שנו ואילך. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן."]]],[2000470209,"בחוטי הכנור שצריך זמן עד שיכה בידיו על החוטי' להוציא הקול, ואדרבה<sup data-n=\"1368\">56</sup> שינוי התנועות שבשפתים הוא לפי שינוי ביטוי האותיות שברצון הנפש לבטא בשפתים כרצונה לומר אות ב' או וא\"ו או מ\"ם או פ', ולא להיפך שיהי' רצון הנפש וכוונתה לעשות שינוי תנועות השפתים, כמו שהם מתנוענעות<sup data-n=\"1369\">57</sup> בביטוי ד' אותיות אלו כו', ויותר נראה כן בביטוי הנקודות שכשהנפש רצונה להוציא מפיה נקודת קמץ אזי ממילא יקמצו<sup data-n=\"1370\">58</sup> השפתים, ובפתח נפתחו<sup data-n=\"1371\">59</sup> השפתים, ולא שרצון הנפש לקמוץ ולא לפתוח כלל וכלל, ואין להאריך בדבר הפשוט ומובן ומושכל לכל משכיל שמבטא אותיות הנקודות<sup data-n=\"1372\">60</sup> הוא למעלה משכל<sup data-n=\"1373\">61</sup> המושג ומובן אלא משכל הנעלם וקדמות השכל שבנפש המדברת, ולכן אין התינוק יכול לדבר הגם שמבין הכל<sup data-n=\"1374\">62</sup> שלא בהבנת השכל תלוי ענין הדבור &lt;3&gt;\nּ כו' וכמובן, וזהו עצם בחי' האותיות, וז\"ע אבא יסד ברתא<sup data-n=\"1375\">63</sup>, והנה בחי' קדמות השכל הוא קודם לכל גילוי השגה והבנה רק עדיין הוא בבחי' הסתר והעלם רק שמעט מזעיר שופע ונמשך משם לבחי' בינה להבין ולהשיג בחי' שכל הנעלם, וז\"ע בחי' הנהר שיוצא מעדן שמעט מזעיר נמשך מבחי' עדן להיות בחי' התפשטות הנהר שהוא השגה והבנה כו', וגם זהו להשקות את הגן שיומשך בחי' אור ההשכלה לבחי' האותיות הנ\"ל שעצם מקורם והתהוותן הוא בחי' הח\"ע עצמה כנ\"ל, ונמצא כי יש ב' בחי' באותיות התורה עצם בחי' האותיות שמקורן ושרשן מהחכ' שז\"ע אבא יסד ברתא, וגם אח\"כ האותיות מקבלים מהשכל שנמשך משם לאותיות המחשבה ומשם לאותיות הדבור, והגם שבשכל אינו נראה ונרגש בחי' אותיות כלל עכ\"ז נמשך ומתהוה משם למטה<sup data-n=\"1376\">64</sup> בחי' אותיות, והיינו מבחי' הרצון שבקדמות השכל.\n(ג) <b>והנה</b> עדן הוא בחי'<sup data-n=\"1377\">66</sup> חכמה עילאה חכים ולא בחכ' ידיעא<sup data-n=\"1378\">67</sup>, וזהו בעדן מקדם<sup data-n=\"1379\">68</sup> הוא בחי' תענוג העליון ומשם נמשך הנהר להשקות<sup data-n=\"1380\">65</sup>, וכנ\"ל שבחי' הארה נמשך מקדמות השכל להיות התפשטות הנהר כו' רק שהוא הארה בעלמא, וזהו ביו\"ד נברא העוה\"ב<sup data-n=\"1381\">69</sup> שכל בחי' ההשגה שמושג בעוה\"ב הוא מהארה המלובשת באות יו\"ד לבד, שהוא הארה מצומצמת מאד וגם מעצם היו\"ד דהיינו",[["1368","56","<b>ואדרבה</b>: מכאן עד להלן על יד הערה 62 הוא המשך לשון אגה\"ק ס\"ה קז, א."],["1369","57","<b>מתנענעות</b>: באגה\"ק שם: מתנענעות עתה. באוה\"ת ויקרא שם כבפנים."],["1370","58","<b>יקמצו</b>: באגה\"ק שם: נקמצים. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200220\" data-slug=\"or-hatorah-hb\" data-id=\"8159200220\">אוה\"ת ויקרא שם ע' תתקלו</a> כבפנים."],["1371","59","<b>נפתחו</b>: בהמשך הנדפס: יפתחו. באגה\"ק שם: נפתחים. באוה\"ת ויקרא שם כבפנים."],["1372","60","<b>אותיות הנקודות</b>: באגה\"ק שם: האותיות והנקודות. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200221\" data-slug=\"or-hatorah-hb\" data-id=\"8159200221\">אוה\"ת ויקרא שם ע' תתקלז</a>: אותיות והנקודות."],["1373","61","<b>משכל</b>: באגה\"ק שם: מהשכל."],["1374","62","<b>הכל</b>: ע\"כ לשון האגה\"ק. ראה לעיל הערה 56."],["1375","63","<b>אבא יסד ברתא</b>: נסמן לעיל בהמשך זאת חנוכת המזבח פט\"ז הערה 396."],["1376","64","<b>למטה</b>: בהמשך הנדפס: ולמטה."],["1377","66","<b>בחי'</b>: באוה\"ת כאן ליתא."],["1378","67","<b>חכים ולא בחכ' ידיעא</b>: ז\"ח יתרו לד, ד. ת\"ז בהקדמה יז, ב."],["1379","68","<b>בעדן מקדם</b>: בראשית ב, ח."],["1380","65","<b>והנה. . להשקות</b>: לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770429\" data-slug=\"or-hatorah-hb\" data-id=\"8316770429\">אוה\"ת שה\"ש ע' תכט</a>."],["1381","69","<b>ביו\"ד נברא העוה\"ב</b>: ראה מנחות כט, ב."]]],[2000470210,"מאות יו\"ד ג\"כ, וכנ\"ל שעצם האותיות והברתם אינם לא מוטבע בטבע ולא בשכל, כ\"א מבחי' קדמות השכל שברצון הנפש שלמעלה משכל הגלוי כו', ולפ\"ז י\"ל שבחי' אור ההשכלה שבעוה\"ב זהו מבחי' אור ההשכלה שבאות יו\"ד כו', אך בחי' הענג שבעוה\"ב זהו מבחי' עצם האות יו\"ד ששרשו מבחי' ח\"ע עצמה שבבחי' קדמות השכל שלמעלה מידי גילוי הארתה בבחי' השכלה מורגשת באור השכל כ\"א בבחי' ענג כו', אך הנה כ\"ז הוא בבחי' צמצום עצום וכמשל אות יו\"ד שהיא נקודה חדא<sup data-n=\"1382\">70</sup> כו', אמנם הנה ע\"י העסק בתורה לשמה לשם התורה<sup data-n=\"1383\">72</sup>, והיינו ע\"י העיון בתורה למצוא אור החכמה המלובש באותיות התורה איש לפי ערכו הרי עי\"ז ממשיך תוס' אור בבחי' נהר יוצא שז\"ע המשכת יסו\"א בהאותיות, ועי\"ז ממשיכים ג\"כ תוס' אור בג\"ע<sup data-n=\"1384\">71</sup> כו'<sup data-n=\"1385\">73</sup><sup data-n=\"e1\">*</sup>, כי הנה פי' לשמה הוא להמשיך הארה היוצא מיסוד אבא להמתיק דיני לאה כמ\"ש בפע\"ח שער י\"ז ריש שער הנהגת הלימוד<sup data-n=\"1386\">76</sup>, והיינו ע\"י הלימוד בעיון ובהעמקה, כי לאה הוא<sup data-n=\"1387\">77</sup> בחי' אותיות המחשבה<sup data-n=\"1388\">78</sup> מל' דתבונה<sup data-n=\"1389\">79</sup> תחתית המדריגה דתבונה והתגלותה בחי' אותיות המגלים כל דבר, ולכן נק' דינים וגבורות מחמת שהם מגבילים השכל לבלי יתפשט בלי גבול, וגם הם לבדם אין בהם שום שכל, והראי' שיוכל לחשוב אותיות מבלי שידע השכל שבהם, והנה ידוע &lt;4&gt;\nּ שמוחין שבעולם התחתון הם בחי' אותיות לגבי עולם העליון וכמ\"ש מזה בלק\"ת בד\"ה ועתה יגדל נא גבי כאשר דברת לאמר<sup data-n=\"1390\">80</sup>, וכשלומד תורה אף שהוא מבין אך שהוא",[["1382","70","<b>יו\"ד שהיא נקודה חדא</b>: זהר בראשית ל, ב."],["1383","72","<b>לשמה לשם התורה</b>: ראה פע\"ח שער הנהגת הלימוד [מובא בסמוך בפנים]. מאמרי אדה\"א דברים ח\"א ע' רמ. וש\"נ. שה\"א סט, ב ובהערה 26. סה\"מ תרכ\"ז ס\"ע רסח ואילך. וש\"נ."],["1384","71","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770429\" data-slug=\"or-hatorah-hb\" data-id=\"8316770429\">ע\"י</a>. . בג\"ע</b>: לשון אוה\"ת שה\"ש ע' תכט (בשינויים והוספות)."],["1385","73","<b>כו'</b>: ניתוסף בפנים ע\"פ המשך הנדפס."],["1386","76","<b>בפע\"ח שער י\"ז ריש שער הנהגת הלימוד</b>: ”השער הי\"ז שער תיקון חצות ויתחלק לארבעה פרקים\". ולאח\"ז<sup data-n=\"e77\">א</sup> בא שער הנהגת הלימוד<sup data-n=\"e78\">ב</sup>, בלי ציון המספר."],["1387","77","<b>הוא</b>: בהמשך הנדפס ובלקו\"ת : היא."],["1388","78","<b>לאה. . אותיות המחשבה</b>: ראה סידור שחרית ס, ג. סט, א. מאמרי אדה\"א נ\"ך ע' קג. וש\"נ."],["1389","79","<b>לאה. . מל' דתבונה</b>: ראה ע\"ח שער לאה ורחל של\"ח, פ\"ג. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380274\" data-slug=\"likkutei-torah\" data-id=\"4001380274\">לקו\"ת</a> להאריז\"ל ס\"פ תולדות. לקו\"ת בחוקותי מו, א. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקצד. תקס\"ה ח\"א ע' טז."],["1390","80","<b>שמוחין שבעולם התחתון. . בלק\"ת. . לאמר</b>: ראה שם שלח לט, סע\"ב."],["e1","*","<b>בשולי היריעה נרשם</b>: ענין שע\"י המשכת יסו\"א נמתקי' דיני לאה ע' ביאור באתי לגני ספ\"א<sup data-n=\"5925\">74</sup>.\n\n<b>א</b>  במהדורת קארעץ תקמ\"ב א) שער ת\"ח שער הטבת חלום שער הנהגת הלימוד. ב) ללא ציון מספרים להשערים. ג) לא צויין בריש כל שער כמה פרקים נמצאים.\n\n<b>ב</b>  במהדורת קארעץ תקמ\"ב דובראוונא תקס\"ד לבוב תרכ\"ה. ואילו במהדורת קארעץ תקמ\"ה תקמ\"ו קארעץ תקע\"ט? (ואולי זהו רק בתוספת שער מ) הרובשוב תקע\"ט אינו מופיע."],["5925","74","<b>ביאור באתי לגני ספ\"א</b>: ציון זה ללקו\"ת נמצא גם באוה\"ת כאן, ונעתק לשון הלקו\"ת כאן בפנים המאמר."]]],[2000470211,"שלא בעיון הוא נק' בחי' אותיות ואין בו התגלות כ\"כ, וכדי להמתיק דיני לאה להביא מוחין בתוך האותיות צריך להמשיך הארה מיסו\"א. והענין ידוע שמוח העיון ומוח הזכרון הוא בחי'<sup data-n=\"1391\">81</sup> חכ'<sup data-n=\"1392\">82</sup> שלמעלה מהבינה ונק' משכיל שמשם בא השכל, וצריך ללמוד בעיון עד שיומשך שכל מבחי' חכ' שבו מה שהי' תחלה צפון ונעלם ונעשו מוחין להאותיות ונמתקו דיני לאה ונעשה כן בכל העולמות מוחין להאותיות, ולכן עיקר ההמשכה צ\"ל מבחי' חכ' יסו\"א כי בחכ' שורה<sup data-n=\"1393\">83</sup> אוא\"ס<sup data-n=\"1394\">75</sup>, ובחי' החכ' אינה מסתרת על בחי' חכ' דא\"ק המלובשת בה כו'<sup data-n=\"1395\">84</sup>, ונמצא מובן איך ע\"י לימוד התורה בעיון לשמה נמשך תוס' אור בג\"ע, כי מצד<sup data-n=\"1396\">85</sup> עצם הג\"ע הרי ארז\"ל ביו\"ד נברא העוה\"ב שהוא המשכת הארה לבד כנ\"ל, שהוא הארה כל שהוא כמו היו\"ד שהיא נקודה אחת, וע\"י עיון הלימוד לשמה ממשיכים בבחי' ונהר יוצא שיומשך גם בג\"ע מכל האותיות, היינו אור כל האותיות שנמתקי' דיני לאה כנ\"ל ע\"י ההמשכה מיסו\"א, וגם עצם האותיות ממקור האותיות ומקור נש\"י ששרשן מבחי' ח\"ע אבא יסד ברתא ולפי הנ\"ל נמשך תוס' עצום הן בהשגת עוה\"ב והן בבחי' הענג כו'.\n<b>ובזה</b> יובן מה שכנס\"י נק' כלה<sup data-n=\"1397\">86</sup> לשון כלתה נפשי<sup data-n=\"1398\">87</sup>, כי מחמת שהנשמות שרשן מאותיות התורה והאותיות שרשן מבחי' עדן לכן תשוקת כל א' מישראל ליכלל באחד וחפצו ורצונו להיות ואהבת את ה' אלקיך<sup data-n=\"1399\">88</sup> כו', וז\"ע לסוסתי ברכבי פרעה<sup data-n=\"1400\">89</sup> כי סוסים היינו אותיות<sup data-n=\"1401\">90</sup> כמ\"ש כי תרכב על סוסיך<sup data-n=\"1402\">91</sup>, ולפי שנש\"י שרשן מאותיות התורה ע\"כ נמשלו לסוסתי, וכמ\"ש בת\"א פ' בשלח<sup data-n=\"1403\">92</sup> בד\"ה לסוסתי בענין סוסי' נוקבין וסוסים דוכרין.",[["1391","81","<b>שמוח העיון<sup data-n=\"e79\">ג</sup>. . בחי' חכ'</b>: ראה אגרות קודש אדמו\"ר מהוריי\"צ חי\"ד ע' שיח."],["1392","82","<b>ומוח הזכרון. . חכ'</b>: ראה לעיל המשך זאת חנוכת המזבח פי\"ג ובהערה 269."],["1393","83","<b>בחכ' שורה אוא\"ס</b>: ראה תניא פי\"ח<sup data-n=\"e80\">ד</sup>. פל\"ה בהג\"ה. לקו\"ת במדבר יד, ב<sup data-n=\"e81\">ה</sup>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540658\" data-slug=\"torat-chaim\" data-id=\"2300540658\">תו\"ח שמות ח\"א ז, ד</a> הערה 333. סה\"מ תרנ\"ח ע' יב."],["1394","75","<b>פי'. . אוא\"ס</b>: לשון <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381260\" data-slug=\"likkutei-torah\" data-id=\"4001381260\">לקו\"ת שה\"ש לב, סע\"ד</a> ואילך (בשינויים קלים). וראה גם אוה\"ת על ענינים ע' שלח ואילך. וש\"נ."],["1395","84","<b>ובחי'. . כו'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381261\" data-slug=\"likkutei-torah\" data-id=\"4001381261\">לקו\"ת שה\"ש שם לג, א</a>."],["1396","85","<b>מצד. . כלה</b>: לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770429\" data-slug=\"or-hatorah-hb\" data-id=\"8316770429\">אוה\"ת שה\"ש ע' תכט</a> ואילך (בהוספות ושינויים)."],["1397","86","<b>שכנס\"י נק' כלה</b>: ראה פסדר\"כ פכ\"ב (שוש אשיש). וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540060\" data-slug=\"torat-chaim\" data-id=\"2300540060\">תו\"ח וארא ח\"א עב, ג</a> ובהערה 7."],["1398","87","<b>כלתה נפשי</b>: תהלים פד, ג. ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540075\" data-slug=\"torat-chaim\" data-id=\"2300540075\">תו\"ח בשלח ח\"א רח, א</a> ובהערה 19."],["1399","88","<b>ואהבת את ה' אלקיך</b>: ואתחנן ו, ה. ראה גם לקמן פכ\"ט."],["1400","89","<b>לסוסתי ברכבי פרעה</b>: שה\"ש א, ט."],["1401","90","<b>סוסים היינו אותיות</b>: נסמן לעיל בהמשך זאת חנוכת המזבח פכ\"ג ובהערה 669."],["1402","91","<b>כי תרכב על סוסיך</b>: חבקוק ג, ח."],["1403","92","<b>בת\"א פ' בשלח</b>: סג, ד ואילך. סד, ג.\n\n<b>ג</b>  במאמרי אדה\"ז הקצרים ע' תקסז: העליון. באוה\"ת שבהערה 75 (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן כבפנים.\n\n<b>ד</b>  ובמ\"מ הגהות והע\"ק שם.\n\n<b>ה</b>  <b>ושם מציין</b>: ”בע\"ח שער מ\"ז פ\"ג\" ולפנינו הוא פ\"ב ”ושער ב במה\"ב פ\"א פ\"ג\" ולפנינו הוא בשער סדר אצי' ש\"ג."]]],[2000470212,"<b>והנה</b> בחי' ונהר יוצא מעדן זהו בחי' חתן כי נהר היינו יסוד ז\"א<sup data-n=\"1404\">93</sup> ויסוד אבא<sup data-n=\"1405\">94</sup>, וכמ\"ש כנהר שלום<sup data-n=\"1406\">95</sup> והיא התורה שנא' וכל נתיבותי' שלום<sup data-n=\"1407\">96</sup> ותורה נק' חתן<sup data-n=\"1408\">97</sup>, ועמ\"ש ע\"פ במלך שלמה שהשלום שלו<sup data-n=\"1409\">98</sup> בד\"ה שה\"ש אשר לשלמה<sup data-n=\"1410\">99</sup>, ועמ\"ש בד\"ה ואלה שמות בנ\"י<sup data-n=\"1411\">100</sup> בענין והאתנים מוסדי ארץ<sup data-n=\"1412\">101</sup>, אתנים אותיות תנאים<sup data-n=\"1413\">102</sup> שע\"י שהם מתחלה אתנים ע\"ד משכיל לאיתן<sup data-n=\"1414\">103</sup> הם מוסדי ארץ תושבע\"פ<sup data-n=\"1415\">104</sup> שנק' ג\"כ כלה שמקבלת מתושב\"כ, והממשיכים המשכה זו הם נש\"י ועמ\"ש מזה בד\"ה תורה צוה לנו משה בלק\"ת פ' הברכה<sup data-n=\"1416\">105</sup>.\n<b></b>קיצור אות ב\"ג. שכינה ג\"ן סדרים דאורייתא, כי ס\"ר נשמות הם ס\"ר אותיות התו', ולכן כלה כלתה נפשי לשרשן לבחי' עדן, וחתן הוא בחי' ונהר יוצא מעדן להשקות את הג\"ן, גם תושבע\"פ נק' כלה. \n&lt;5&gt;\nּ ועפ\"ז יובן ענין מצה זו כו' שנגלה עליהם ממה\"מ, פי' ממה\"מ<sup data-n=\"1417\">106</sup> מלכים הם בחי' כי הנה המלכים נועדו<sup data-n=\"1418\">107</sup> שקאי על יהודה ויוסף זו\"נ דאצי' מלכי חו\"ב מלך מלכי הוא בחי' הכתר, וכשנתגלה בחי' זו אזי לא הי' מקום לחמץ כלל<sup data-n=\"1419\">108</sup> כמ\"ש מזה במ\"א, ועכשיו יש בחי' זו בעבודה זהו המשכת אור אבא שנת\"ל, ובמצות יש בחי' זו והוא ענין הציווי דאכילת מצה שהיא בחי' קטנות אבא<sup data-n=\"1420\">109</sup>, וכמשנ\"ת בד\"ה",[["1404","93","<b>נהר היינו יסוד ז\"א</b>: ראה זהר מקץ קצד, א — דרושים שבהערה הבאה."],["1405","94","<b>נהר. . ויסוד אבא</b>: ראה ביאוה\"ז וירא יא, ב. אוה\"ת וירא כרך ד ע' 1508 רס\"ב המשך מים רבים תרל\"ו פע\"ז. וש\"נ."],["1406","95","<b>כנהר שלום</b>: ישעי' סו, יב."],["1407","96","<b>וכל נתיבותי' שלום</b>: משלי ג, יז."],["1408","97","<b>ותורה נק' חתן</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381103\" data-slug=\"likkutei-torah\" data-id=\"4001381103\">לקו\"ת ברכה צד, א</a>. מאמרי אדה\"א קונטרסים ע' רעג. וש\"נ."],["1409","98","<b>במלך שלמה שהשלום שלו</b>: שה\"ש ג, יא. ראה שהש\"ר פ\"א, א [יא]. פ\"ג, יא [א]. שבועות לה, ב."],["1410","99","<b>בד\"ה שה\"ש אשר לשלמה</b>: כ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770430\" data-slug=\"or-hatorah-hb\" data-id=\"8316770430\">אוה\"ת שה\"ש</a> כאן ריש ע' תל. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381136\" data-slug=\"likkutei-torah\" data-id=\"4001381136\">לקו\"ת שה\"ש א, ד</a> ואילך."],["1411","100","<b>בד\"ה ואלה שמות בנ\"י</b>: <a class=\"ft-cite\" href=\"#/read/torah-or/3901370222\" data-slug=\"torah-or\" data-id=\"3901370222\">תו\"א שמות מט, ב</a>."],["1412","101","<b>והאתנים מוסדי ארץ</b>: מיכה ו, ב."],["1413","102","<b>אתנים אותיות תנאים</b>: זהר סבא משפטים קי, ב. רע\"מ תצא רעח ב. ת\"ז תכ\"א מג, סע\"ב."],["1414","103","<b>משכיל לאיתן</b>: תהלים פט, א."],["1415","104","<b>ארץ תושבע\"פ</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370004\" data-slug=\"torah-or\" data-id=\"3901370004\">תו\"א בראשית א, ג</a>. סה\"מ תרל\"ח ע' קמט. וש\"נ."],["1416","105","<b>בלק\"ת פ' הברכה<sup data-n=\"e82\">ו</sup></b>: צד, ב ואילך."],["1417","106","<b>פי' ממה\"מ</b>: ברכות כח, ב. ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770252\" data-slug=\"or-hatorah-hb\" data-id=\"8316770252\">אוה\"ת שה\"ש ע' רנב</a> ואילך<sup data-n=\"e83\">ז</sup>. המשך מים רבים תרל\"ו פקל\"ב. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן. לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הב' על יד הערה 91. (בחלק ההנחות) הנחה ד\"ה אני לדודי הב' על יד הערה 74."],["1418","107","<b>כי הנה המלכים נועדו</b>: תהלים מח, ה. זהר ויגש רו, א."],["1419","108","<b>לא הי' מקום לחמץ כלל</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381188\" data-slug=\"likkutei-torah\" data-id=\"4001381188\">לקו\"ת שה\"ש יד, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381189\" data-slug=\"likkutei-torah\" data-id=\"4001381189\">טו, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380125\" data-slug=\"likkutei-torah\" data-id=\"4001380125\">צו יב, ב</a>."],["1420","109","<b>מצה. . קטנות אבא</b>: ראה סידור סדר הגדה חצר, סע\"א ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540710\" data-slug=\"torat-chaim\" data-id=\"2300540710\">תו\"ח בא ח\"א צד, ד</a> הערה 393.\n\n<b>ו</b>  וכ\"ה ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380304\" data-slug=\"likkutei-torah\" data-id=\"4001380304\">לקו\"ת ויקרא בהוספות נג, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381142\" data-slug=\"likkutei-torah\" data-id=\"4001381142\">שה\"ש ג, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381212\" data-slug=\"likkutei-torah\" data-id=\"4001381212\">כ, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381241\" data-slug=\"likkutei-torah\" data-id=\"4001381241\">כח, א</a>. ב. ואילו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380244\" data-slug=\"likkutei-torah\" data-id=\"4001380244\">לקו\"ת אמור לט, ג</a>. (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381106\" data-slug=\"likkutei-torah\" data-id=\"4001381106\">ואתחנן ד, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381107\" data-slug=\"likkutei-torah\" data-id=\"4001381107\">ברכה צד, ד</a>. צה, א) פ' וזאת הברכה.\n\n<b>ז</b>  נדפס גם ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200057\" data-slug=\"or-hatorah-hb\" data-id=\"8159200057\">אוה\"ת ויקרא כרך ג' ע' תשסט</a> ואילך."]]],[2000470213,"וככה באריכות<sup data-n=\"1421\">110</sup> שבחי' קטנות אבא זהו מהות בחי' אור אבא אלא שהוא בבחי' הקטנות וגם הנה היא מצוה ששרשה מרצה\"ע שזהו כמו בחי' עדן מקדם, וע\"י בחי' חפץ ורצון העליון נתלבשה להיות אכילה גשמי' שעלי' יחי' האדם והיא אכילה שהיא בעצם בחי' ביטול ושפלות, וכנודע שחמץ הוא הגבהה והתנשאות ובעבודה ז\"ע גה\"ר וכעס<sup data-n=\"1422\">112</sup>, ומצה ביטול ושפלות<sup data-n=\"1423\">111</sup> ולכן ע\"י שהאדם ניזון מאכילה שיש בה ביטול הרי בנקל יותר לבוא בעבודה ג\"כ לבחי' הביטול, וזהו מצה כו' ע\"ש מה, היינו ע\"ש לפעול בחי' הביטול דמ\"ה דחכ' בעבודה בנפש האדם, וכמו במצרים שנגלה עליהם ממה\"מ, וא\"כ גם אכילת מצה דעכשיו היא כמו בעת שנגלה עליהם ממה\"מ, ולכן מצה זו דמצוה שנצטוינו היא ע\"ש בחי' המ\"ה ע\"ש שנגלה עליהם ממה\"מ כו' כן פועל ברוחני' גם בחי' מצה זו דעכשיו.",[["1421","110","<b>בד\"ה וככה באריכות</b>: תרל\"ז פנ\"ה ואילך."],["1422","112","<b>שחמץ. . גה\"ר וכעס</b>: ראה גם לקו\"ת צו שם. סה\"מ תרל\"ח ע' תכג. וש\"נ."],["1423","111","<b>שחמץ. . והתנשאות. . ומצה. . שפלות</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380130\" data-slug=\"likkutei-torah\" data-id=\"4001380130\">לקו\"ת צו יג, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381188\" data-slug=\"likkutei-torah\" data-id=\"4001381188\">שה\"ש יד, ד</a>. לקמן רפמ\"א."]]],[2000470214,"<h3>[משה קבל] וביאור הענין הנה תושב\"כ</h3>\n<b></b><b>[יום ב' של חגה\"פ<sup data-n=\"1424\">113</sup>]</b>\n(פ\"ד)\nיום ב' של חגה\"פ\n(ד) <b>וביאור</b> הענין הנה<sup data-n=\"1425\">114</sup> תושב\"כ הוא בחי' חכ' כי אורייתא מח\"ע נפקת<sup data-n=\"1426\">115</sup>, ועכ\"ז התורה אינה רק בחי' נובלות חכ' שלמעלה כמארז\"ל בבראשית רבה פי\"ז<sup data-n=\"1427\">116</sup> ג' נובלות הן<sup data-n=\"1428\">117</sup> נובלות חכמה שלמעלה תורה, פי' חכ' עילאה דאצי' חכים ולא בחכ' ידיעא למעלה מן השגה ונק' בחי' אין שהוא בחי' ביטול בתכלית שלזאת התלבשות אוא\"ס בבחי' קירוב הוא רק בחכמה כמ\"ש בכהאריז\"ל שבכתר ובחכ' מאיר אור א\"ס בבחי' קירוב<sup data-n=\"1429\">118</sup> מקום, וע' בסש\"ב פל\"ה בהג\"ה שלכן נק' החכ' אחד האמת כו', ומה שנמשך מבחי' חכ\"ע הנ\"ל להתהוות אותיות התורה אינה אלא מבחי' אחוריים וחיצוניות החכ' שהיא נובלות חכמה כו', כי הנה<sup data-n=\"1430\">119</sup> בלק\"ת",[["1424","113","<b>יום ב' של חגה\"פ</b>: הוספת המו\"ל ע\"פ בוך 224. ראה לעיל הערה 1 שפרק זה הוא מאמר חדש שנאמר ביום ב' דפסח בפתיחה: משה קבל."],["1425","114","<b>הנה</b>: מכאן לשון <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381107\" data-slug=\"likkutei-torah\" data-id=\"4001381107\">לקו\"ת ברכה</a> (ביאור ע\"פ תורה צוה) צה, סע\"א ואילך בשינויים והוספות. אוה\"ת ח\"ש כרך ז ע' 2419."],["1426","115","<b>אורייתא מח\"ע נפקת</b>: זהר בשלח סב, א. יתרו פה, א. רע\"מ משפטים קכא, א. קדושים פא, א. חוקת קפב, א. ואתחנן רסא, א."],["1427","116","<b>בבראשית רבה פי\"ז</b>: ס\"ה. פמ\"ד, יז. באוה\"ת ח\"ש כאן מציין: בס\"י."],["1428","117","<b>ג' נובלות הןח</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370050\" data-slug=\"torah-or\" data-id=\"3901370050\">תו\"א לך יא, ג</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670191\" data-slug=\"torat-chaim\" data-id=\"2300670191\">תו\"ח לך פב, ג</a>. אוה\"ת לך כרך ו ע' תתרעד ואילך."],["1429","118","<b>שבכתר ובחכ'. . קירוב</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג-ד. שער סדר אבי\"ע שמ\"ז, פ\"א. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670533\" data-slug=\"torat-chaim\" data-id=\"2300670533\">תו\"ח בראשית יז, ג</a> הערה 5. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה להבין שרש ענין מקיפים דבינה ובהנסמן שם."],["1430","119","<b>הנה</b>: מכאן לשון אגה\"ק סי\"ט, צויין אליו ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381108\" data-slug=\"likkutei-torah\" data-id=\"4001381108\">לקו\"ת ברכה כאן צה, ב</a>."]]],[2000470215,"מהאריז\"ל<sup data-n=\"1431\">120</sup> פ' כי תשא<sup data-n=\"1432\">121</sup> ופ' ויקרא<sup data-n=\"1433\">122</sup> כתב כי השגת מרע\"ה לא היתה בבחי' פנימית דח\"ע הנק' אבא<sup data-n=\"1434\">123</sup> דאצי' וכ\"ש בספי' הכתר שלמעלה מזה הנק'<sup data-n=\"1435\">125</sup> א\"א<sup data-n=\"1436\">124</sup> כ\"א בבחי' אחוריי' דחכ' המתלבשי'<sup data-n=\"1437\">126</sup> בז'<sup data-n=\"1438\">127</sup> ספירות התחתוני'<sup data-n=\"1439\">128</sup> שנק' ז\"א סוד התורה<sup data-n=\"1440\">129</sup> ומתפשטות<sup data-n=\"1441\">130</sup> עד סוף ד' ספירות תחתוני' שהם<sup data-n=\"1442\">131</sup> נהי\"ם, ושם היתה השגת נבואתו בבחי' פנימיות דהיינו מבחי' פנימיות דנהי\"ם אבל למעלה מנהי\"ם לא היתה לו שום השגה בפנימיות כ\"א באחוריי'<sup data-n=\"1443\">132</sup> דחכ' המלובשים<sup data-n=\"1444\">133</sup> בבינה המלובשת ומתפשטות<sup data-n=\"1445\">134</sup> תוך פנימיות דנהי\"ם בסוד נובלות חכ' שלמעלה תורה שהוא בחי'<sup data-n=\"1446\">135</sup> ז\"א וכדכתי' וראית את אחורי<sup data-n=\"1447\">136</sup> ופני לא יראו ע\"ש ובשער הנבואה פ\"א<sup data-n=\"1448\">137</sup>, והנה תושבע\"פ הוא פי' וביאור על תושב\"כ, שבתושב\"כ אינה מפורש היטב כל המצות &lt;6&gt;\nּ לפי שנמשכה מבחי' ח\"ע שלמעלה מהשגה רק בתושבע\"פ בא לידי גילוי לפרש כל פרטי המצות, ולכן נק' תושבע\"פ בחי' דבור<sup data-n=\"1449\">139</sup> מל' פה<sup data-n=\"1450\">140</sup> כו', אך אינו בא לידי גילוי בתושבע\"פ אלא בחי' אחוריים וחיצוני' תושב\"כ בחי' הארה בעלמא שהם גוף המצות אבל פנימיות תושב\"כ שהם טעמים נקודות תגין לא בא בתושבע\"פ בבחי' גילוי<sup data-n=\"1451\">141</sup>, וי\"ל שגם פנימיות האותיות<sup data-n=\"1452\">142</sup> לא באו ג\"כ לידי גילוי בתושבע\"פ והם הנקראים עלמין סתימין דלא אתגליין<sup data-n=\"1453\">143</sup> שאינם באים לידי גילוי",[["1431","120","<b>מהאריז\"ל</b>: באגה\"ק: של האריז\"ל."],["1432","121","<b>פ' כי תשא</b>: עה\"פ וראית את אחורי (לג, כג)."],["1433","122","<b>ופ' ויקרא</b>: בתחילתו. ובד\"ה ונבאר ענין חטא נו\"א וענין משה כו'. — ראה ס' שיעורים בתניא כאן ע' 1495 הערה 5."],["1434","123","<b>דח\"ע הנק' אבא</b>: ראה זהר רע\"מ קדושים פב, א. תצא רעח, ב."],["1435","125","<b>הכתר. . הנק' א\"א</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"א."],["1436","124","<b>בספי' הכתר. . הנק' א\"א</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061259\" data-slug=\"likkutei-sichot\" data-id=\"1300061259\">לקו\"ש שמות כרך ו ע' 249</a> ואילך."],["1437","126","<b>המתלבשי'</b>: באגה\"ק: המלובשת. אבל כ\"ה בתניא שקלאוו תקע\"ד. וכן תוקן בלוח התיקון לאגה\"ק שם."],["1438","127","<b>המתלבשי' בז'</b>: באגה\"ק: המתלבשי' בבינה המתלבשת בז'. ובתניא הנ\"ל כבפנים."],["1439","128","<b>התחתוני'</b>: באגה\"ק: תחתונו'."],["1440","129","<b>ז\"א סוד התורה</b>: ראה ע\"ח שער הכללים ספ\"א. שער המוחין ש\"כ, פ\"ג. שער דרושי הצלם שכ\"ה, דרוש ח (קרוב לתחילתו). שער יעקב ולאה של\"ז, פ\"א. מבוא שערים ש\"ג ח\"ב, פ\"ו. זהר פקודי רלח, ב ובהגהות מהרח\"ו ומק\"מ שם."],["1441","130","<b>ומתפשטות</b>: באגה\"ק: ומתפשטת."],["1442","131","<b>תחתוני' שהם</b>: באגה\"ק: התחתונות שהן."],["1443","132","<b>באחוריי'</b>: באגה\"ק (קכז, ריש ע\"ב): בבחי' אחוריים. בתניא שקלאוו הנ\"ל כבפנים."],["1444","133","<b>המלובשים</b>: באגה\"ק: המלובשת. בתניא הנ\"ל כבפנים."],["1445","134","<b>ומתפשטות</b>: בהמשך הנדפס: ומתפשטת. וכ\"ה באגה\"ק."],["1446","135","<b>שהוא בחי'</b>: באגה\"ק: שהיא בבחי'. בתניא הנ\"ל כבפנים."],["1447","136","<b>וראית את אחורי</b>: תשא לג, כג."],["1448","137","<b>פ\"א</b>: ע\"כ לשון אגה\"ק סי\"ט — ראה לעיל הערה 119."],["1449","139","<b>נק' תושבע\"פ בחי' דבור</b>: באוה\"ת בראשית כרך ו ע' 2060 מציין ע' זהר ויקהל דף ר ע\"א."],["1450","140","<b>מל' פה</b>: ת\"ז בהקדמה יז, א."],["1451","141","<b>טעמים. . גילוי</b>: ראה גם לעיל בהמשך זאת חנוכת המזבח פכ\"ב. לקו\"ת כאן צה, ד. אוה\"ת ח\"ש כאן ע' תתתיא."],["1452","142","<b>פנימיות האותיות</b>: ראה גם לקו\"ת כאן צה, ד."],["1453","143","<b>עלמין סתימין דלא אתגליין</b>: ת\"ז בהקדמה יז, א."]]],[2000470216,"כלל<sup data-n=\"1454\">144</sup> וכמו עד\"מ קרי וכתיב שבאותיות התורה שהקרי הוא לפי ההבנה הנגלית לנו והכתיב הוא למעלה מהשכל וההבנה שתיבה זו בכתיבתה אין לה לבוש בבחי' הבנה<sup data-n=\"1455\">146</sup> ובקריאתה בפה יש לה לבוש, וכן הענין באותיות גדולות שבתנ\"ך שהם מעלמא עילאה ומאירות משם בגילוי בלי לבוש<sup data-n=\"1456\">145</sup>, אבל לא בבחי' השגה והבנה כו', וגם האתוון בינונים ג\"כ אינו מושג אלא בחי' אור ההשכלה שבאותיות אבל לא עצם ציור האותיות מפני מה הם כך, ומשנ\"ת ע\"ז בס' הקבלה הם מעט מזעיר וג\"ז הוא רזין דאורייתא.\n<b>והנה</b><sup data-n=\"1457\">138</sup> הממשיכים מתושב\"כ לתושבע\"פ הם התנאים בעלי המשנה שנק' תנאים אותיות אתנים, וכמ\"ש והאתנים מוסדי ארץ, ארץ היא בחי' תושבע\"פ והאתנים אותיות תנאים הם המייסדים את הארץ בחי' תושבע\"פ, וכמ\"ש משכיל לאיתן<sup data-n=\"1458\">148</sup> שהאתנים ממשיכים מבחי' משכיל, כי איתן הוא בחי' יסוד אבא, ולכן התנאים שהם בחי' איתן הם דוקא יכולים להמשיך בחי' זו וכמארז\"ל משה קיבל תורה מסיני<sup data-n=\"1459\">149</sup> כו' עד ונביאים מסרוה לאנשי כנה\"ג הרי קבלתם ממשה שהוא בחי' חכ'<sup data-n=\"1460\">150</sup>, ולכן עיקר פסקי ההלכות שלהם לא הי' ע\"פ הכרעת שכלם רק ממה שקבלו איש מפי איש עד משה, וכמארז\"ל גבי ר\"א י\"ב א\"ל שמעתי<sup data-n=\"1461\">151</sup> י\"ח א\"ל לא שמעתי, וכן גבי עקבי' בן מהללאל, אני שמעתי מפי המרובים<sup data-n=\"1462\">152</sup> כו', והיינו לפי שהי'<sup data-n=\"1463\">153</sup> בבחי' אין וביטול ממש, ע\"כ האירה בהם בחי' משה שהוא בחי' ביטול אמיתי ונחנו מה<sup data-n=\"1464\">154</sup> מן המים משיתיהו<sup data-n=\"1465\">155</sup>, משא\"כ אליהו בגימ' ב\"ן<sup data-n=\"1466\">156</sup> הביטול בחיצוני', ולכן עלה גופו<sup data-n=\"1467\">157</sup>, ולכן ההלכות שאמרו התנאים במשנה הם בחי' אלקות ממש שהוא מה שנמשך אחר בירור ב' דמ\"ה דחכ\"ע<sup data-n=\"1468\">147</sup> כו', ולכן הם הם המוסדי ארץ בחי' תושבע\"פ מפני שהם אתנים איתן כמשמעו",[["1454","144","<b>כלל</b>: ע\"כ לשון הלקו\"ת בשינויים והוספות — כנ\"ל הערה 114."],["1455","146","<b>הבנה</b>: שם: ההבנה."],["1456","145","<b>שהקרי. . לבוש</b>: לשון אגה\"ק סי\"ט קכח, א בשינויים והוספות — ראה גם לעיל הערה 119."],["1457","138","<b>והנה</b>: מכאן שוב לשון הלקו\"ת ברכה — כנ\"ל הערה 114."],["1458","148","<b>איתן. . יסוד אבא</b>: ע' באגה\"ק ע\"פ וצדקה כנחל איתן — <a class=\"ft-cite\" href=\"#/read/torah-or/3901370223\" data-slug=\"torah-or\" data-id=\"3901370223\">תו\"א כאן מט, רע\"ג</a>."],["1459","149","<b>משה קיבל תורה מסיני</b>: אבות רפ\"א."],["1460","150","<b>ממשה. . חכ'</b>: ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061254\" data-slug=\"likkutei-sichot\" data-id=\"1300061254\">לקו\"ש שמות כרך ו ע' 244</a> ואילך."],["1461","151","<b>ר\"א י\"ב א\"ל שמעתי</b>: סוכה כח, א."],["1462","152","<b>אני שמעתי מפי המרובים</b>: עדיות פ\"ה, מ\"ז."],["1463","153","<b>שהי'</b>: בתו\"א: שהיו."],["1464","154","<b>ונחנו מה</b>: נסמן לעיל בהמשך זאת חנוכת המזבח ספכ\"א הערה 593."],["1465","155","<b>מן המים משיתיהו</b>: שמות ב, י."],["1466","156","<b>אליהו בגימ' ב\"ן</b>: ראה פע\"ח שער הק\"ש ש\"ח, פ\"ח. לקמן פכ\"ז. מאמרי אדה\"א ויקרא ח\"ב ע' תקלז. וש\"נ. תו\"ח ויצא קעח, ג ובהערה 33."],["1467","157","<b>אליהו. . עלה גופו</b>: ראה מל\"ב ב, יא. פרדס שער היכלות שכ\"ד, פי\"ג. פי\"ד. לקמן פכ\"ז. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה צאינה וראינה על יד הערה 101. לקמן ח\"ב (חלק המאמרים) מאמר ד\"ה כנשר יעיר ובהערה 17. ד\"ה וכל שיח השדה פ\"ד. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה וכל שיח השדה על יד הערה 72. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשנו. מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. סה\"מ תרל\"ב ח\"א ע' קיא. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540861\" data-slug=\"torat-chaim\" data-id=\"2300540861\">תו\"ח בשלח ח\"א קצו, ג</a>. וש\"נ. פלח הרמון בחוקותי ע' תקכט ואילך. וש\"נ."],["1468","147","<b>והנה. . דחכ\"ע</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370222\" data-slug=\"torah-or\" data-id=\"3901370222\">תו\"א שמות מט, סע\"ב</a> ואילך."]]],[2000470217,"קשה<sup data-n=\"1469\">158</sup> בחי' ביטול דמ\"ה דחכ'<sup data-n=\"1470\">159</sup> שלמעלה מן השכל כמ\"ש במ\"א, ולכן הם המוסדי ארץ כו', אך הנה זהו לייסד הארץ בחי' תושבע\"פ אמנם לאחר שכבר נוסדה ע\"י בחי' התנאים בחי'<sup data-n=\"1471\">160</sup> איתנים הנ\"ל הנה ע\"י העיון בעומק בלימוד התורה שכאו\"א לומד ומייגע א\"ע למצוא בהאותיות שנוסדו ע\"י האיתנים הנ\"ל עי\"ז נמשך תוס' וריבוי אור, ויובן זה ע\"פ משנ\"ת בסש\"ב שכאו\"א יש בנשמתו מבחי' ח\"ע<sup data-n=\"1472\">161</sup> שבתוכה א\"ס אפי' מי &lt;7&gt;\nּ שיש לו נשמה רק מבחי' מל' דמל' דעשייה<sup data-n=\"1473\">162</sup> עכ\"ז בתוכה מלובש כו' עד בחי' ח\"ע דאצי' שבה א\"ס, ולכן ע\"י שמייגע כלי שכלו בעיון עד שמעליהו לבחי' האין שבו, וי\"ל שזהו שרש<sup data-n=\"1474\">163</sup> שרשו כמו שהוא באותיות התורה בבחי' אין דחכ' כמשנת\"ל, הרי העלאה זו היא כמו בחי' העלאת מ\"ן לבחי' האין דאתנים שיש בתורה מבחי' התנאים שהם מוסדי ארץ כנ\"ל ולכן בכחו ג\"כ להמשיך מבחי' אור אבא כנ\"ל<sup data-n=\"1475\">164</sup> בענין להמתיק דיני לאה, אשר עי\"ז נמשך תוס' וריבוי אור כו'.\n<b></b>קיצור. נובלות חכ' שלמעלה תורה היינו הארה מבחי' ח\"ע שהרי גם משה לא השיג רק בבחי' אחוריי' דחכ', ותושבע\"פ היא פי' וביאור על בחי' אותיות התורה לבד, וג\"ז רק חיצוני' האותיות בחי' קרי, ולא הכתיב היינו האותיות בעצם ואתוון רברבין, והממשיכים בחי' זו בתושבע\"פ הם התנאים בחי' איתן ביטול שלמעלה מן השכל, ולאחר שכבר נוסדה ע\"י האתנים הנה ע\"י עיון שהוא העלאת כלי שכלו לבחי' האין שבו ה\"ז כמו העלאת מ\"ן להמשיך תוס' אורות מבחי' אור אבא כו'. ",[["1469","158","<b>איתן כמשמעו קשה</b>: סוטה מו, סע\"א."],["1470","159","<b>איתן. . ביטול דמ\"ה דחכ'</b>: ראה גם תו\"א כאן. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380788\" data-slug=\"likkutei-torah\" data-id=\"4001380788\">לקו\"ת פ' ראה יח, א</a>. המשך מים רבים תרל\"ו פ\"ה."],["1471","160","<b>התנאים בחי'</b>: בהמשך הנדפס ליתא. ואולי נשמט מפני תיבות הדומות: בחי'. . בחי'."],["1472","161","<b>בסש\"ב שכאו\"א. . ח\"ע</b>: פי\"ח."],["1473","162","<b>נשמה. . מל' דמל' דעשייה</b>: ראה גם (לקמן בחלק ההנחות) הנחה ד\"ה כמים הפנים ובהערה 11."],["1474","163","<b>שרש</b>: בהמשך הנדפס ליתא."],["1475","164","<b>כנ\"ל</b>: פ\"ג."]]],[2000470218,"<h3>אז ישיר</h3>\n<b>יום שש\"פ</b>\n(ה) <b>אז</b> ישיר<sup data-n=\"1476\">165</sup> משה ובנ\"י<sup data-n=\"1477\">166</sup> את השירה הזאת, פי' השירה הזאת ידוע שקאי על בחי' המל'<sup data-n=\"1478\">167</sup> שאומרת שירה<sup data-n=\"1479\">168</sup> כמ\"ש בכ\"ד, וא\"כ בפי' פסוק זה י\"ל ב' פירושים הא' שע\"י שמשה ובנ\"י אמרו שירה עי\"ז נתעורר למעלה בחי' שירה הזאת, והב' ע\"י בחי' שירה הזאת אמרו משה ובנ\"י ג\"כ שירה למטה, ותחלה נבין פי' הא', ויובן בהקדם ענין מה שנת\"ל<sup data-n=\"1480\">169</sup> שהנשמות שרשן מאותיות התורה והאותיות שרשן מבחי' עדן לכן תשוקת כ\"א מישראל ליכלל באחד, ולכן ע\"י שנש\"י הם בבחי' כלתה",[["1476","165","<b>אז ישיר</b>: מכאן מתחיל מאמר הב' מהמשך מצה זו (הכולל פרקים ה-יו\"ד).\nמאמר דידן כפי שמופיע לפנינו הנה הוא כולל פרקים ה-י. אמנם בבוך 224 נמצא חלוקה אחרת והוא, שמאמר הראשון כולל רק פרקים ה-ז, וקודם פרק ח נרשמה כותרת: שמיני ש\"פ. ועפ\"ז הנה המאמר כפי שהוא לפנינו נאמר בב' פעמים, היינו שפרקים ה-ז נאמרו בשש\"פ. ואילו הפרקים ח-י. נאמרו לאח\"כ בשמיני ש\"פ. ראה גם לקמן הנחת כ\"ק אדמו\"ר מהורש\"ב (בחלק ההנחותיו) ממאמר דידן.\nלמאמר זה (לאחרי הפתיחה) לפ\"ה — ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770430\" data-slug=\"or-hatorah-hb\" data-id=\"8316770430\">אוה\"ת שה\"ש כרך ב ע' תל</a> ס\"ב. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a> (צויין אליו באוה\"ת שם). מג, א.\nלפ\"ו — ראה אוה\"ת שה\"ש שם.\nפ\"ח — לשון אוה\"ת שה\"ש שם תל, ב ואילך (בהוספות). לשון <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381139\" data-slug=\"likkutei-torah\" data-id=\"4001381139\">לקו\"ת שה\"ש ב, ג</a> (בשינויים והוספות — צויין אליו ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770431\" data-slug=\"or-hatorah-hb\" data-id=\"8316770431\">אוה\"ת</a> הנ\"ל). אוה\"ת נצבים כרך ו ע' ב'תכא. ראה מאמרי אדה\"ז אתהלך לאזניא ע' קלט. אוה\"ת סידור ס\"ע יד ואילך. סה\"מ תרכ\"ז ע' מז. תרל\"ה ח\"א ע' קפד.\nפ\"ט — לשון אוה\"ת שה\"ש ח\"ב ע' תלא <a class=\"ft-cite\" href=\"#/read/torah-or/3901370125\" data-slug=\"torah-or\" data-id=\"3901370125\">תו\"א וישב כו, ג</a> <a class=\"ft-cite\" href=\"#/read/torah-or/3901370127\" data-slug=\"torah-or\" data-id=\"3901370127\">כז, א</a> בשינויים.\nפ\"י — לשון <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381116\" data-slug=\"likkutei-torah\" data-id=\"4001381116\">לקו\"ת ברכה צז, ב</a> ואילך (בשינויים — צויין אליו באוה\"ת שה\"ש הנ\"ל).\nמאמר זה נזכר בכ\"מ<sup data-n=\"e84\">א</sup>. הנחת<sup data-n=\"e85\">ב</sup> כ\"ק אדמו\"ר מהורש\"ב מדרוש זה נדפסה לקמן (בחלק הנחותיו).\nהכותרת המופיעה בריש המאמר לא נרשמה בהמשך הנדפס. ותיבת: ”יום\" בהכותרת ניתוסף מהנחת כ\"ק אדמו\"ר מהורש\"ב.\nבבוך זה הנה בריש הע' לאחרי הכותרת נרשם: ”ה) והנה נת\"ל שהנשמות שרשן מאותיות התורה והאותיות שרשן\" (והוא ע\"ד המובא בסמוך בפנים). והעביר עליו קו ונרשם כבפנים. ואולי הפתיחה ניתוספה לאח\"כ."],["1477","166","<b>אז ישיר משה ובנ\"י</b>: בשלח טו, א."],["1478","167","<b>השירה הזאת. . המל'</b>: ראה גם בענין השירה הזאת מאמרי אדה\"ז תקס\"ז ע' שנב ואילך."],["1479","168","<b>המל' שאומרת שירה</b>: ראה גם סה\"מ תרכ\"ו ע' סה. תר\"ל ע' קיט. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן."],["1480","169","<b>מה שנת\"ל</b>: פ\"ב ואילך. וראה גם פיסקא ובזה יובן (בפ\"ג).\n\n<b>א</b>  <b>ומהם</b>: לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 212 ושם: בד\"ה אז ישיר שבמאמר מצה זו. על יד הערה 370 ושם: בד\"ה מצה זו בענין אז ישיר. ד\"ה כנשר יעיר על יד הערה 51 ושם: כמשנ\"ת בד\"ה אז ישיר שבמצה זו. סה\"מ תרמ\"ד ע' קסד ושם: וע' בד\"ה גן נעול (מ\"ם) פ\"ו ופ\"ז. ע' קסה ושם: וע' בהרשימה ד\"ה אז ישיר מהמא' ג\"ן תר\"מ. (מהדורת תשס\"ב) ע' שנא ושם: וע' בד\"ה ג\"ן מ\"ם. תרמ\"ז ע' נא ושם: ד\"ה גן נעול פ\"ז, מ\"ם. תרמ\"ו-תר\"ן ע' שצז ושם: וכמ\"ש בד\"ה גן נעול (מם) פ\"ו. תרנ\"ח ע' כט ושם: ובדרוש גן נעול (מצה זו) ר\"מ. המשך תער\"ב ח\"ג ע' א'רסט ושם: בד\"ה מצה זו תר\"מ. תרס\"ט ע' קמה ושם: בד\"ה גן נעול, תר\"מ (ג\"פ). תרע\"ז ע' ה ושם: בד\"ה מצה זו תר\"מ. תרע\"ח ע' נ ושם: בד\"ה גן נעול (מצה זו) תר\"מ. פר\"ת ע' קיח ושם: ובד\"ה גן נעול תר\"מ.\n\n<b>ב</b>  ויש להוסיף הנחה זו לרשימת מאמרי דא\"ח של כ\"ק אדמו\"ר מהר\"ש ש. ז."]]],[2000470219,"נפשי עי\"ז מתעלות אותיות התו' לשרשן<sup data-n=\"1481\">170</sup>. וביאור הענין דהנה<sup data-n=\"1482\">171</sup> התורה נתלבשה באותיות, שאותיות התורה שרשן למעלה מעלה מבחי' התורה, ולכן נשפלו להיות לבוש שבהם יתגלה אור התורה, וכנודע ממ\"ש במ\"א בענין החשמל שהלבוש<sup data-n=\"1483\">173</sup> שרשו גבוה יותר<sup data-n=\"1484\">172</sup>, ולכן בכדי להלביש איזה דבר במשל שעם היות שהמשל הוא רק לבוש לבד עכ\"ז צריך להיות המלביש המשל חכם היותר גדול<sup data-n=\"1485\">174</sup> דוקא, וכמ\"ש משלי שלמה<sup data-n=\"1486\">175</sup> שלפי שבשלמה נא' ויחכם מכל האדם<sup data-n=\"1487\">176</sup> הי' יכול לאמר משל להלביש החכ' במשל, וכן על ר\"מ אמרו שהי' אומר תלתא מתלי<sup data-n=\"1488\">177</sup> והיינו שהי' גדול בחכ' עד ששמו מוכיח עליו שקראו אותו כן לפי שהי' מנהיר עיני חכמים בהלכה כידוע בדרז\"ל לא ר\"מ שמו<sup data-n=\"1489\">178</sup> כו', ועד\"ז באותיות התורה שהם בעצמם הם לבוש לאור התורה, ועכ\"ז שרשן גבוה יותר דאורייתא מחכמה נפקת<sup data-n=\"1490\">179</sup>, והאותיות שרשן למעלה בבחי' כתר<sup data-n=\"1491\">180</sup>, ואותיות הם מלשון אתא<sup data-n=\"1492\">181</sup> שהוא לשון המשכה, שהאותיות הן הממשיכות שבהם וע\"י נמשך להיות התורה<sup data-n=\"1493\">182</sup>, והנה<sup data-n=\"1494\">183</sup> שרש &lt;8&gt;\nּ גילוי האותיות הוא בחכמה, אך אין זה רק בחי' גילוי לבד אבל שרשם הנעלם הוא למעלה מעלה בבחי' כתר כמ\"ש בזהר אינון כתרין עילאין<sup data-n=\"1495\">184</sup> כו' ונחתא כ\"ף מעל כורסי' דיקרי'<sup data-n=\"1496\">185</sup> כו' כי",[["1481","170","<b><a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770430\" data-slug=\"or-hatorah-hb\" data-id=\"8316770430\">ולכן ע\"י</a>. . לשרשן</b>: לשון אוה\"ת שה\"ש כאן ע' תל."],["1482","171","<b>דהנה</b>: לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a> בשינויים והוספות (צויין אליו באוה\"ת שם)."],["1483","173","<b>שהלבוש</b>: בהמשך הנדפס: שהמלבישה. וכנשצ\"ל כבפנים."],["1484","172","<b>בענין החשמ\"ל שהלבוש שרשו גבוה יותר</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370055\" data-slug=\"torah-or\" data-id=\"3901370055\">תו\"א לך יב, ד</a>. ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' שצג ואילך. מאמרי אדה\"א ויקרא ח\"ב ס\"ע תקכב ואילך. וש\"נ. סה\"מ תרנ\"ד ע' ריא ואילך."],["1485","174","<b>המלביש המשל חכם היותר גדול</b>: ראה תו\"א שם יא, ג. הנסמן לעיל בהערה 172."],["1486","175","<b>משלי שלמה</b>: משלי א, א."],["1487","176","<b>ויחכם מכל האדם</b>: מל\"א ה, יא."],["1488","177","<b>ר\"מ. . תלתא מתלי</b>: סנהדרין לח, סע\"ב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370412\" data-slug=\"torah-or\" data-id=\"3901370412\">תו\"א מג\"א צא, ג</a>. מאמרי אדה\"ז תקס\"ח ח\"א ריש ע' שצד. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091202\" data-slug=\"likkutei-sichot\" data-id=\"1300091202\">לקו\"ש וילך כרך ט ע' 202</a> ואילך."],["1489","178","<b>שהי' מנהיר עיני חכמים. . לא ר\"מ שמו</b>: ראה ערובין יג, ב. ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370295\" data-slug=\"torah-or\" data-id=\"3901370295\">תו\"א שם. ש\"א סו, ב</a>. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 20. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ע' ה. המשך מים רבים פל\"ז. סה\"מ תרל\"ב ח\"א ע' קפח. תרל\"ח ע' ריג. תרנ\"ד שם. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300181084\" data-slug=\"likkutei-sichot\" data-id=\"1300181084\">לקו\"ש נשא כרך יח ע' 75</a>."],["1490","179","<b>דאורייתא מחכמה נפקת</b>: נסמן לעיל הערה 115."],["1491","180","<b>והאותיות. . כתר</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן הערה 23."],["1492","181","<b>ואותיות הם מלשון אתא</b>: ישעי' כא, יב. ראה (בנוסף לתו\"א מקץ כאן) מאמרי אדה\"א שמות ח\"א ע' קנח. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540319\" data-slug=\"torat-chaim\" data-id=\"2300540319\">תו\"ח שמות ח\"א כה, ג</a>. וש\"נ."],["1493","182","<b>התורה</b>: ע\"כ מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370190\" data-slug=\"torah-or\" data-id=\"3901370190\">תו\"א מקץ מב, ב</a> — ראה לעיל הערה 171."],["1494","183","<b>והנה</b>: מכאן לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">תו\"א מקץ מג, א</a> בשינויים."],["1495","184","<b>בזהר אינון כתרין עילאין</b>: כ\"ה בתו\"א שם<sup data-n=\"e86\">א</sup>. ראה אוה\"ת תזריע ח\"ב ע' תקכא<sup data-n=\"e87\">ב</sup>: אמרו בזהר בהקדמה שהאותיות הם בחי' כתרים בחי' כתרין עילאין כמש\"ש, ובפ' ויגש דר\"ה ע\"ב כיון דנחית כף מעל כתרא. ראה גם סהמ\"צ להצ\"צ ע' 266. ז\"ח שה\"ש סו, ד. פרדס שער האותיות שכ\"ז, פכ\"ו."],["1496","185","<b>ונחתא כ\"ף מעל כורסי' דיקרי'</b>: זהר בהקדמה ג, א [ושם: וכד נחתת כ' מעל כורסי יקרי' — ראה אוה\"ת תשא ע' א'תתקו. ושם לפנ\"ז: נחתא. . את כ]. סה\"מ תרל\"ג ח\"א ע' ו. לקמן בהנחה כאן על יד הערה 25.\n\n<b>א</b>  וכ\"ה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 24. סה\"מ תרל\"ג ח\"א ע' ו.\n\n<b>ב</b>  נדפס גם בסה\"מ תרל\"ה ח\"א ע' ר. והנחת כ\"ק אדמו\"ר מהורש\"ב בח\"ב שם ע' תפ. וע' תפג."]]],[2000470220,"מהות האותיות אינם בחי' שכל רק הם למעלה מן השכל שא\"א להשיג בשכל מהות האותיות ומוצאן במבטא שהם יוצאים מכלי השכל וכנ\"ל, רק עיקרם נלקחים מבחי' שלמעלה מן השכל והן נעשית<sup data-n=\"1497\">186</sup> בחי' לבוש להשכל להשכיל כל דבר בכל לשון מע' לשון, שכל דבר שכל אינו נתפס אלא באותיות, אבל אין האותיות מהות השכל ועצמותו אלא בחי' לבושו כנודע שהשכל מתלבש לפעמים באותיות אלו ולפעמים באותיות אחרים, וכמו המפרשי' והפוסקי' שעם שאומרים דבר אחד עכ\"ז כ\"א אומר באותיות אחרים<sup data-n=\"1498\">187</sup>, והיינו מפני כי האותיות אינם ממהות השכל כ\"א לבושו, ונת' לעיל שהלבוש הוא מבחי' היותר גבוה שנשפל להיות לבוש כו'.\n<b>והנה</b> בזהר ויצא דקנ\"ה סע\"ב<sup data-n=\"1499\">189</sup> ע\"פ לכן ישכב עמך<sup data-n=\"1500\">190</sup> פי' ישכב יש<sup data-n=\"1501\">191</sup> כ\"ב, ויש<sup data-n=\"1502\">192</sup> דא עלמא<sup data-n=\"1503\">193</sup> עילאה היינו בינה, להנחיל אוהבי יש<sup data-n=\"1504\">194</sup>, כ\"ב נקודא עילאה דאעיל כל ך\"ב אתוון, והוא אבא שממנו שרש צורת ך\"ב אותיות כמ\"ש באג\"ה ד\"ה ויעש דוד שם וכנ\"ל<sup data-n=\"1505\">195</sup>, וא\"כ פי' ישכב י\"ל המשכת יש תענוג עליון דעוה\"ב תוך ך\"ב אתוון, והיינו ישכב כו' בלילה<sup data-n=\"1506\">196</sup> ההוא<sup data-n=\"1507\">188</sup>, ולפי משנ\"ת לעיל<sup data-n=\"1508\">197</sup> שבחי' ההשגה והבנה שבעוה\"ב זהו מבחי' האור שהוא ההארה המצומצמת שביו\"ד, אבל בחי' הענג זהו מעצם האות שהוא הגבה למעלה כו', א\"כ פי' יש כ\"ב שיתגלה היש והענג שנמשך מעצם האותיות שיש בעוה\"ב יאיר ויתגלה דרך האותיות, והיינו שהאותיות יגלו גם בחי' הענג שנמשך מעצם האותיות ולא מבחי' אור השכל שבהם, אך איך יוכל להיות גילוי הענג שמעצם האותיות ע\"י בחי' האותיות, מאחר שהלבוש צ\"ל שרשו גבוה יותר יתבאר לקמן אי\"ה, ובקצרה י\"ל שמאחר שהענג שנמשך מהאותיות נעשה גילוי בחי' ענג, וזהו כלל שכל מה שמתגלה אינו אלא בחי' האחרונה שבמשפיע<sup data-n=\"1509\">198</sup>, והתענוג הוא גילוי ההמשכה מהאותיות א\"כ הוא מבחי' אחרונה שבאותיות<sup data-n=\"1510\">199</sup> לכן ע\"י עצם האותיות יוכל לבוא לידי גילוי בהשגה גם מבחי' התענוג שנמשך מהאותיות כו'.",[["1497","186","<b>נעשית</b>: בהמשך הנדפס: נעשי'. בתו\"א: נעשות."],["1498","187","<b>אחרים</b>: ע\"כ מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">תו\"א מקץ מג, א</a> — ראה לעיל הערה 183."],["1499","189","<b>בזהר ויצא דקנ\"ה סע\"ב</b>: וכ\"ה באוה\"ת שה\"ש כאן. ראה שם סתרי תורה קנו, סע\"ב — וכ\"ה באוה\"ת ויצא ח\"א ריש ע' 392 בשלח ע' תרכה ויקהל ע' ב'קז."],["1500","190","<b>לכן ישכב עמך</b>: ויצא ל, טו."],["1501","191","<b>יש</b>: בזהר ובאוה\"ת כאן: י\"ש."],["1502","192","<b>ויש</b>: שם: י\"ש."],["1503","193","<b>דא עלמא</b>: שם: דא איהו עלמא."],["1504","194","<b>להנחיל אוהבי יש</b>: משלי ח, כא."],["1505","195","<b>וכנ\"ל</b>: פ\"ב."],["1506","196","<b>כו' בלילה ההוא</b>: באוה\"ת כאן: כו' הוא. אולי הכוונה לויצא ל, טז ושם: בלילה הוא ו”לסבירין\" ההוא. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 31."],["1507","188","<b>והנה. . ההוא</b>: לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770430\" data-slug=\"or-hatorah-hb\" data-id=\"8316770430\">אוה\"ת שה\"ש כאן ע' תל</a> בשינויים."],["1508","197","<b>משנ\"ת לעיל</b>: פ\"ג."],["1509","198","<b>וזהו כלל. . שמתגלה. . בחי' האחרונה שבמשפיע</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' א'יא. וש\"נ. וראה גם סה\"מ תרל\"ח ע' תפח. וש\"נ. תרל\"ג ח\"ב ע' תפח. וש\"נ. תרל\"ו ע' לח. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ויהי הענן והחשך על יד הערה 61. ד\"ה משה קבל על יד הערה 11. ד\"ה וירא העם וינועו על יד הערה 21. ד\"ה וביום הביכורים על יד הערה 26. (בחלק ההנחות) הנחה ד\"ה וביום הביכורים על יד הערה 41."],["1510","199","<b>שבאותיות</b>: בהמשך הנדפס ליתא."]]],[2000470221,"<b></b>קיצור. שע\"י שנש\"י שרשן מהאותיות לכן ע\"י בחי' כלתה נפשי דנש\"י מתעלים האותיות, כי האותיות גבוהים יותר ע\"ד כמו המשל, וגילוי האותיות בחכ' ושרשם הנעלם בכתר ולכן נעשים לבוש לשכל, ובזהר פי' ישכב יש ך\"ב, י\"ל שיתגלה בחי' הענג ע\"י עצם האותיות.\n(וא\"ו) <b>וזהו</b><sup data-n=\"1511\">200</sup> דכתי' למען יזמרך כבוד<sup data-n=\"1512\">201</sup> ולא ידום כו', ויש בזה ב' פירושים הא' &lt;9&gt;\nּ דהנה נודע שאין כבוד אלא תורה<sup data-n=\"1513\">202</sup> ס\"ר אותיות התורה שבכדי שיהי' יזמרך כבוד ולא ידום ויתעלו למקורן ושרשן עדן העליון זהו ע\"י שה'<sup data-n=\"1514\">203</sup> אלקי לעולם אודך כי ע\"י שישראל יש להם בחי' כלתה נפשי עי\"ז נתעלים ג\"כ אותיות התורה למקורן ושרשן, ואפ\"ל כי שרש ומקור האותיות מהרשימו הנשאר מהצמצום ומק\"פ כמ\"ש בביאור ע\"פ את שבתותי תשמורו<sup data-n=\"1515\">204</sup>, והנה בהאותיות אין מאיר גילוי אוא\"ס ממש רק ע\"ד רשימו, ושיאיר בהם תוס' אור זהו עלייתן, והיינו ע\"י כלתה נפשי, והיינו המשכת הקו בהרשימו, וגם תוס' אור בהקו וחוט, וכמ\"ש בזהר הרקיע פ' בראשית דט\"ו על המאמר שם בריש הורמנא דמלכא פי'<sup data-n=\"1516\">205</sup> נר חזק כו' קו ומדה כו' וזאת הבוצינא נתלבשה תוך א\"ק, כי א\"ק הלביש הרשימו שהניח הא\"ס כו', וזו היסוד דמל' דא\"ס<sup data-n=\"1517\">206</sup> נק' בוצינא דקרדוניתא כו' כי<sup data-n=\"1518\">207</sup> יסוד דנוק' נק' נר לצוק בתוכה שמן טוב כו' חוט הא\"ס היורד בתוכה כו'<sup data-n=\"1519\">208</sup> מת\"ת הנעלם דרך חוט ליסוד ומשם למקום הפנוי שהוא כלי המקבל<sup data-n=\"1520\">209</sup> עכ\"ל. נמצא ז\"ע המשכת הקו תוך אותיות הרשימו וז\"ע יחוד חתן וכלה כו' וזהו ענין ישכב יש כ\"ב הנ\"ל, ואפ\"ל ג\"כ שז\"ע מ\"ש בע\"ח יחוד מ\"ה וב\"ן דעתיק מיני' ובי'<sup data-n=\"1521\">210</sup> כו'<sup data-n=\"1522\">211</sup>, ומובן כי ע\"י בחי' האותיות שנשארו בהרשימו עי\"ז מתגלה בחי' האוא\"ס דקו וחוט, כי הרשימו היינו מה שלא נגע בו הצמצום, ולכן הן יכולים לגלות ההמשכה שנמשך ע\"י הקו כי הקו הוא לאחר הצמצום כו'.\n<b>אך</b> מה שנת' שנמשך גם בחי' תוס' אור בבחי' הק\"ו<sup data-n=\"1523\">212</sup> שזהו לכאו' מבחי' העיגול שלפני הק\"ו א\"כ זהו מלמעלה מהצמצום, וא\"כ איך יש באותיות הרשימו לגלות מה שלפני הצמצום, וכנ\"ל<sup data-n=\"1524\">213</sup> שהלבוש בהכרח שיהי' שרשו גבוה יותר כו', אך",[["1511","200","<b>וזהו</b>: ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770430\" data-slug=\"or-hatorah-hb\" data-id=\"8316770430\">אוה\"ת שה\"ש כאן ע' תל</a> בשינויים והוספות."],["1512","201","<b>למען יזמרך כבוד</b>: תהלים ל, יג."],["1513","202","<b>שאין כבוד אלא תורה</b>: אבות פ\"ו, ג. ראה מאמרי אדה\"א בראשית ע' טז."],["1514","203","<b>שה'</b>: בהמשך הנדפס: שיהי'."],["1515","204","<b>בביאור ע\"פ את שבתותי תשמורו</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380261\" data-slug=\"likkutei-torah\" data-id=\"4001380261\">לקו\"ת בהר מג, ב</a> ואילך."],["1516","205","<b>הורמנא. . פי'</b>: באוה\"ת שה\"ש כאן: הורמנתא. . כו' בוצינא דקרדוניתא פי'."],["1517","206","<b>דא\"ס</b>: כ\"ה באוה\"ת שה\"ש כאן. ובזהר הרקיע ליתא."],["1518","207","<b>כי</b>: בהמשך הנדפס ליתא. אבל כ\"ה גם באוה\"ת ובזהר\"ק."],["1519","208","<b>כו'</b>: בהמשך הנדפס ליתא. אבל כ\"ה גם באוה\"ת כאן."],["1520","209","<b>המקבל</b>: וכ\"ה גם באוה\"ת ובזהר\"ק. בהמשך הנדפס: המקבלים."],["1521","210","<b>יחוד מ\"ה וב\"ן דעתיק מיני' ובי'</b>: ראה ע\"ח שער עתיק שי\"ב, פ\"ב. שער אנ\"ך שי\"ט, פ\"ה. שער העיבורים שכ\"ח, פ\"ב. שער מ\"ן ומ\"ד דרוש ב."],["1522","211","<b>כו'</b>: ע\"כ מאוה\"ת שה\"ש. ראה לעיל הערה 200."],["1523","212","<b>הק\"ו</b>: בהמשך הנדפס: הקו."],["1524","213","<b>וכנ\"ל</b>: פ\"ה."]]],[2000470222,"הענין הוא כנודע שקודם הצמצום הי' אוא\"ס ממלא כל<sup data-n=\"1525\">214</sup> החלל<sup data-n=\"1526\">215</sup> וע\"י בחי' הצמצום סילק אורו הגדול על הצד<sup data-n=\"1527\">216</sup> ונשאר רק רשימו ומקום פנוי<sup data-n=\"1528\">217</sup>, וא\"כ גם מה שסילק על הצד שזהו בבחי' העיגול שלפני הקו הרי גם בו נגע בחי' הצמצום<sup data-n=\"1529\">218</sup> שהרי סילקו להתעלות ממקום המק\"פ על הצד בבחי' העיגול שלפני הק\"ו, ובחי'<sup data-n=\"1530\">219</sup> הרשימו מאחר שנשאר במקום המק\"פ הרי לא נגע בו הצמצום כלל<sup data-n=\"1531\">220</sup>, ועם",[["1525","214","<b>שקודם הצמצום. . ממלא כל החלל</b>: ראה ע\"ח דרוש עגו\"י ש\"א, ענף ב."],["1526","215","<b>ממלא כל החלל</b>: ראה גם לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 234. ד\"ה כנשר יעיר על יד הערה 59. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יפה שעה הא' על יד הערה 74. (בחלק ההנחות) ד\"ה כנשר יעיר קנו על יד הערה 153. ד\"ה יפה שעה הא' על יד הערה 77. שעה\"י קיד, א הערה 17."],["1527","216","<b>סילק אורו הגדול על הצד</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310054\" data-slug=\"tanya\" data-id=\"3401310054\">תניא</a> פמ\"ט (סט, א<sup data-n=\"e88\">ג</sup>): ”שהקב\"ה. . וסילק לצד<sup data-n=\"e89\">ד</sup> אחד דרך משל את אורו הגדול\". ובהערות ותיקונים לשם: ”לצד אחד\" ”לצדדין (כי הסילוק הי' לכל הצדדין בשוה<sup data-n=\"e90\">ה</sup>)\"."],["1528","217","<b>ונשאר רק רשימו ומקום פנוי</b>: בע\"ח שם: ואז נשאר מקום פנוי ואויר וחלל רקני<sup data-n=\"e91\">ו</sup>. באוצרות חיים שער העיגולים בתחילתו: ונשאר חלל ובהגהת הרמ\"ז שם: לאו דוקא חלל כי נשאר שם רשימו מהאור<sup data-n=\"e92\">ז</sup>. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380261\" data-slug=\"likkutei-torah\" data-id=\"4001380261\">לקו\"ת בהר מג, ב</a>: ובע\"ח אינו מבואר<sup data-n=\"e93\">ח</sup> ענין הרשימו רק בספר עמק המלך (עיי\"ש). שם בהוספות (לויקרא) נא, ב ואילך. בסהמ\"צ להצ\"צ איסור. . שביעית ע' 70: הרשימו וכמ\"ש בס' עמק המלך כי בע\"ח לא נת' זה<sup data-n=\"e94\">ט</sup>. מצות האמנת אלקות רפ\"ו (נא, א): וכמ\"ש האריז\"ל. . רק רשימו נשאר שם. שרש מצות התפלה פ\"י (ע' 236): ענין המק\"פ המבואר בע\"ח שנסתלק האור ונשאר רק רשימו. פל\"ד (קלו, א): וכמ\"ש בס' מבוא שערים. . ונשאר רשימו."],["1529","218","<b>העיגול. . נגע בחי' הצמצום</b>: ראה (בנוסף להנחה כאן) סה\"מ תרמ\"ג ע' עט ואילך. תרנ\"ה ע' רח. תרס\"ו ע' קצד ואילך. מאמר ד\"ה ויקח קרח תשי\"ד."],["1530","219","<b>ובחי'</b>: בהמשך הנדפס: ומבחי'. וכנצ\"ל כבפנים."],["1531","220","<b>ובחי' הרשימו. . לא נגע בו הצמצום כלל</b>: ראה גם [ובהבא לקמן] (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) בהנחה כאן על יד הערה 44 ואילך. לקמן ח\"ב (בחלק המאמרים) המשך יונתי פ\"ט. אוה\"ת נח כרך ו<sup data-n=\"e95\">י</sup> ע' 2136 ספ\"ה הגהת כ\"ק אדמו\"ר מהר\"ש. סה\"מ תרל\"ג ח\"א ע' קל. וש\"נ. תרל\"ו פי\"ג. וככה תרל\"ז פמ\"ז. תרמ\"ג ע' עט ואילך. תרס\"ד ע' קלז ואילך. תער\"ב ח\"ג ע' א'רסח ואילך. וראה גם לעיל הערה 165. שערי עיונים בדא\"ח ח\"ב ע' סג ואילך.\n\n<b>ג</b>  הועתק גם באוה\"ת ואתחנן ריש ע' רמ. ע' רנו. ע' שעב.\n\n<b>ד</b>  <b>ראה גם אוה\"ת משפטים ע' א'רכ</b>: שיניח אורו הבלתי מוגבל על הצד. סה\"מ תרל\"ג ח\"ב ע' תקד: בכתהאריז\"ל מקשה בענין הצמצום שסילק אורו הגדול על הצד. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 367 ומציין לע\"ח ומב\"ש.\n(לקמן ח\"ב בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה לכל תכלה ראיתי קץ על יד הערה 64. ד\"ה אני לדודי הב' על יד הערה 39. (בחלק ההנחות) הנחה ד\"ה יפה שעה הא' על יד הערה 103. ד\"ה לכל תכלה על יד הערה 62. ד\"ה כנשר יעיר קנו על יד הערה 151. סה\"מ תרס\"ה ע' שי (בשם הע\"ח). המשך תער\"ב ח\"ב ע' תתקיג. ע' תתקיט. ע' א'קב. ח\"ג ע' א'תמ. סה\"מ ליקוט ח\"ג ע' רלו. מאמר ד\"ה בשעה שהקדימו תשי\"ב.\n\n<b>ה</b>  ראה ע\"ח שבהערה 214. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380298\" data-slug=\"likkutei-torah\" data-id=\"4001380298\">לקו\"ת</a> בהוספות (לויקרא) נא, ג שמציין לאוצ\"ח ומבו\"ש צמצם עצמו אל הצדדין (בשוה).\n\n<b>ו</b>  <b>בשער ההקדמות הקדמה ד (יד, א) ובאדם ישר דרוש העגולים ענף ב</b>: ואויר ריקני חלל.\n\n<b>ז</b>  ראה גם מק\"מ לזהר בראשית טו, א ד\"ה בריש הורמנא דמלכא פי'.\n\n<b>ח</b>  <b>בסהמ\"צ להצ\"צ שרש מצות התפלה פל\"ג (ע' 268)</b>: ובע\"ח לא נזכר כלום מענין הרשימו, רק בספר עמק המלך. ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830008\" data-slug=\"or-hatorah-hb\" data-id=\"8158830008\">אוה\"ת</a> בהר כרך ד ע' א'קסג: אכן בע\"ח לא נז' רק ענין הצמצום ומק\"פ רק הרשימו ודאי הוא ג\"כ עולה לפמ\"ש בע\"ח. בלקו\"ב לשעה\"י קעז, ג: ובע\"ח לא נז' רק ברמז במלת אויר ריקני.\n\n<b>ט</b>  ראה גם הנחת כ\"ק אדמו\"ר מהורש\"ב נדפסה לקמן (בחלק הנחותיו) על יד הערה 48.\n\n<b>י</b>  ושם ע' תתרסה מציין שנדפס בלקו\"ת לג\"פ עא, א ואילך."]]],[2000470223,"היות שגם בהאותיות נגע בחי' הצמצום שהרי קודם הצמצום הי' גילוי אוא\"ס דרך האותיות וע\"י הצמצום נסתלק האור בבחי' העלם עד שאין האותיות יכולים לגלות אוא\"ס שהאיר בהם תחילה כמ\"ש בביאור ע\"פ את שבתותי תשמורו, הרי גם בהאותיות נגע בחי' הצמצום, אמנם זהו רק בפעולת האותיות ולא בעצם האותיות, שעצם האותיות לא &lt;10&gt;\nּ זזו ממקומם, (ולא ע\"ד שבה\"כ ח\"ו שנתפרדו האותיות כמ\"ש במ\"א בד\"ה ויקח מן הבא בידו מנחה<sup data-n=\"1532\">221</sup> ), וגם בפעולת האותיות הנה מה שנגע הצמצום אינו מצד האותיות כ\"א ממה שנסתלק<sup data-n=\"1533\">222</sup> האורות ונתעלמו בבחי' א\"ס ולא מצד האותיות, וא\"כ לא נגע הצמצום בבחי' האותיות גם מצד פעולתם ג\"כ וכ\"ש בהאותיות עצמם כו', ולכן כאשר ממשיכים תוס' אור בבחי' הק\"ו שזהו מלפני הצמצום הנה הם מתגלים ע\"י האותיות שלא נגע בהם הצמצום כלל, ונמצא כי בזה יש להם יתרון על בחי' אור הא\"ס שנסתלק ונתעלם להיות נק' לפני הצמצום כו', ולכן ביכולתם לגלותו כו'.\n<b></b>קיצור. למען יזמרך כבוד אין כבוד אלא תורה, וע\"י הזמרה שנש\"י הם בבחי' כלתה נפשי, ע\"י<sup data-n=\"1534\">223</sup> מגביהים בחי' אותיות התו' לשרשן, והאותיות שרשן מהרשימו, ונמשך תוס' מהק\"ו ובהק\"ו מלמעלה מהצמצום. וזהו יחוד מ\"ה וב\"ן, ומפני כי בהאותיות לא נגע הצמצום לכן יכולים לגלות מלמעלה מהצמצום שעכ\"פ נגע בו הצמצום שנעשה מק\"פ כו'.\n(ז) <b>אך</b> עדיין צ\"ל איך שייך בחי' אותיות לפני הצמצום שהרי ענין בחי' האותיות הם מגבילים השכל, ואיך שייך לומר הגבלה לפני הצמצום, אך כפשוטו אפ\"ל האיך נעשה הצמצום שהוא ג\"כ הגבלה לצמצם עד פה תבוא, והמק\"פ יהי' האור בבחי' העלם ולא בגילוי, אלא שכשם שאוא\"ס הוא כח הבבע\"ג כן יש לו כח בגבול כמ\"ש בעה\"ק<sup data-n=\"1535\">224</sup>, וכמו שיש בלפני הצמצום כח בחי' הצמצום כן יש בחי' האותיות",[["1532","221","<b>שבה\"כ. . בד\"ה ויקח מן הבא בידו מנחה</b>: לע\"ע לא נתברר לאיזה מאמר כוונתו. ראה גם כנפי יונה ח\"ג סנ\"ו. סקמ\"א. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370129\" data-slug=\"torah-or\" data-id=\"3901370129\">תו\"א וישב כז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370462\" data-slug=\"torah-or\" data-id=\"3901370462\">ויחי קד, ד</a>. מאמרי אדה\"א דברים ח\"א ע' ט. וש\"נ. לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ביום השמיני עצרת על יד הערה 53. ובחלק ההנחות שם על יד הערה 66."],["1533","222","<b>שנסתלק</b>: בהמשך הנדפס: שנסתלקו."],["1534","223","<b>ע\"י</b>: בהמשך הנדפס: עי\"ז."],["1535","224","<b>שאוא\"ס. . הבבע\"ג. . כח בגבול כמ\"ש בעה\"ק</b>: ראה עבודת הקודש<sup data-n=\"e96\">א</sup> ח\"א רפ\"ח. דרך אמונה להנ\"ל רפ\"ב (קה\"ת תשמ\"ח ע' יג). ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380778\" data-slug=\"likkutei-torah\" data-id=\"4001380778\">לקו\"ת עקב טז, א</a>.\n\n<b>א</b>  <b>מובא בשמו בכ\"מ ומהם (בנוסף להלקו\"ת)</b>: סהמ\"צ להצ\"צ ע' קנג. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316460026\" data-slug=\"or-hatorah-hb\" data-id=\"8316460026\">אוה\"ת</a> בשלח כרך ז ע' ב'תרסא. יתרו ס\"ע תתמא. תזריע כרך ב ע' תקלג. בהר כרך ג' ס\"ע תתפז. ואתחנן ע' קכג. ע' שצו. ענינים ע' סז*. ע' קנו. ע' רסה. ביאוה\"ז להצ\"צ כרך א ע' א. ע' תיח. סה\"מ תרכ\"ז ע' תנג. תרכ\"ט ע' קסג. תרל\"ב ח\"ב ע' תו. ע' תעה. ע' תפד. תרל\"ג ח\"א ע' קצט. ח\"ב ע' תקה. תרל\"ה ח\"א ע' קעג. (המשך) מים רבים תרל\"ו ספל\"א. פקי\"א. פקנ\"ט. תרל\"ח ע' ג. תרמ\"ח ע' קס. תרנ\"ז ע' מח. תרנ\"ח ע' קצא. תרנ\"ט ע' לד. תרס\"ג ח\"ב ע' רעט. תרס\"ה ע' קפא. (המשך) תרס\"ו ע' כא. ע' קצג. ע' תסז. תרס\"ח ע' סד. ע' ריד. עת\"ר ע' ל. אעת\"ר ע' קטו. (המשך) תער\"ב ח\"א ע' יב. ע' שב. ס\"ע שיט. ח\"ב ע' תתקמ. ח\"ג ע' א'תכח. עזר\"ת ע' קלו. תרע\"ח ע' רעט. ע' שסג. ע' שפד. עטר\"ת ע' כב. ע' שכח. תרפ\"ט ע' 202. ע' 254. תש\"ט ע' 80 הב'. (לקמן ח\"ב בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה אני לדודי הב' על יד הערה 57. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300071214\" data-slug=\"likkutei-sichot\" data-id=\"1300071214\">לקו\"ש בחוקותי כרך ז ע' 202</a> בהערה."]]],[2000470224,"ג\"כ, ונמצא צ\"ל שזהו כח הגבול שבאוא\"ס<sup data-n=\"1536\">225</sup> שלפני הצמצום, ומ\"מ יש הפרש גדול בין בחי' הצמצום לבחי' האותיות שהם לפני הצמצום שהרי הצמצום הוא להיות האור בלתי יתגלה, וה\"ז הגבלה ממש, משא\"כ האותיות עם היות שהם מגבילים אור ההשכלה עכ\"ז עיקרם הוא שע\"י יתגלה אור ההשכלה, וה\"ז היפך הצמצום שהוא להעלים כו', והגם שבמ\"א נת' שכוונת הצמצום הוא בכדי שיוכל להיות אח\"כ הגילוי<sup data-n=\"1537\">226</sup> ע\"י בחי' הק\"ו, ע\"ד צמצם שכינתו<sup data-n=\"1538\">227</sup> בין שני בדי הארון שזהו בשביל שיוכל להיות ונועדתי לך שם<sup data-n=\"1539\">228</sup> עכ\"ז זהו רק בכדי שיוכל להיות אח\"כ אבל הוא עצמו הוא צמצום שפועל העלם וגם בכדי שיוכל להיות אח\"כ גילוי אור המצומצם דרך הק\"ו לבד, אבל האותיות עם היות שהם בעצם מצמצמי' אור השכל אבל הכוונה הוא בכדי שיתגלה, והגילוי הוא מאור א\"ס שלפני הצמצום כו', ולפ\"ז יובן היטב איך נמשך גילוי התוס' אור ע\"י האותיות מאחר שהם עצמם בכדי לגלות כו'.\n<b></b>קיצור. ענין בחי' האותיות שברשימו שזהו מלפני הצמצום זהו כח הגבול שבא\"ס שלפני הצמצום וכמו כח הצמצום, אלא שזה להעלים וזה לגלות כו', ועפ\"ז יובן איך &lt;11&gt;\nּ שע\"י קרי\"ס עי\"ז פעל שישירו משה ובנ\"י, ועי\"ז נעשה למעלה ג\"כ בחי' שירה הזאת כו'<sup data-n=\"1540\">229</sup>. ",[["1536","225","<b>שבאוא\"ס</b>: בהמשך הנדפס: שבאו\"א. וכנצ\"ל כבפנים."],["1537","226","<b>שכוונת הצמצום. . הגילוי</b>: ראה גם סה\"מ עת\"ר ע' ל. המשך תער\"ב ח\"ב ע' תרמא. ע' א'ג."],["1538","227","<b>צמצם שכינתו</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380223\" data-slug=\"likkutei-torah\" data-id=\"4001380223\">לקו\"ת אמור לד, ב</a>. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12."],["1539","228","<b>ונועדתי לך שם</b>: תרומה כה, כב."],["1540","229","<b>ועפ\"ז יובן. . כו'</b>: כ\"ז לא נמצא בפנים. וראה לעיל רפ\"ה."]]],[2000470225,"<h3>ועוי\"ל פי' למען יזמרך</h3>\n<b></b><b>[שמיני ש\"פ<sup data-n=\"1541\">*230</sup>]</b>\n(ח-יו\"ד)\nשמיני ש\"פ\n(ח) <b>ועוי\"ל</b> פי' למען יזמרך כבוד כו' בהיפך מפי' הראשון שמאין נמצא בישראל בחי' זו שיוכלו לעלות ממטה למעלה להיות לעולם אודך הוא",[["1541","*230","<b>שמיני ש\"פ</b>: הוספת המו\"ל ע\"פ בוך 224 שיג, ב. ראה לעיל הערה 165."]]],[2000470226,"ע\"י יזמרך כבוד אותיות התורה ולא ידום מתעלות למקורן ושרשן כנ\"ל<sup data-n=\"1542\">231</sup> לכן יוכלו גם ישראל להיות לעולם אודך ולעלות בעילוי אחר עילוי מעלה מעלה דהא בהא תליא<sup data-n=\"1543\">230</sup> כו', ועד\"ז יובן איך ע\"י שירה הזאת אמרו משה ובנ\"י ג\"כ שירה כו', וביאור הענין דכתי' התהללו בשם קדשו<sup data-n=\"1544\">232</sup> דלכאו' אינו מובן לשון התהללו שהוא לשון נפעל דמשמע שבהם נמשך בחי' תהלה, והרי<sup data-n=\"1545\">233</sup> אדרבה הם מהללים את ה' והל\"ל הללו את שם קדשו ומהו לשון התהללו. אך הענין יובן עפמ\"ש אד' שפתי תפתח<sup data-n=\"1546\">234</sup> ופי יגיד תהלתיך, וביאור פסוק זה יובן עד\"מ הנה כשאדם מתפלל ברוב העתים צריך ליגיעה רבה בהתבוננות עד שיפעול בלב, ולפעמים א\"צ ליגיעה כלל רק מיד שתעלה במחשבתו אחדות ה' וגדולתו תמשך הלב מאליה בהתפעלות מבלי שידע מי הוא המושכה בעבותות אה\"ר וכפלא יחשב בעיניו מהיכן באה לו הכוונה ברעותא דלבא מאליו וממילא כו'. אך הענין הוא, דכתי'<sup data-n=\"1547\">235</sup> למען יזמרך כבוד ולא ידום, וכתי' אלקי' אל דמי לך<sup data-n=\"1548\">236</sup>, ופי' בזהר דקאי על בחי' מל' שמזמרת תמיד נהורא תתאה קארי תדיר<sup data-n=\"1549\">237</sup> לנהורא עילאה ולא שכיך כו', וזהו ואני תפלה אני הוא בחי' מל'<sup data-n=\"1550\">238</sup> הוא בחי' תפלה כו', ובחי' מל' כלולה מע\"ס חב\"ד ומדות ודבור, ובחי' הדבור ממנו נמשכו עשרה מאמרות המלובשים בעולמות ע\"י חילופי' ותמורות וחילופי' דחילופי' ותמורות דתמורות כמ\"ש בסש\"ב ח\"ב בשער היחוד והאמונה בסופו, ובפרט בנשמות ומלאכים כו' שמקבלים שלא ע\"י העלם כ\"כ<sup data-n=\"1551\">239</sup> כו' כמ\"ש במ\"א, והנה כשיש גילוי אוא\"ס בתהלה זו של מדת המל' היינו כשהגילוי בחב\"ד ומדות עד שגם בבחי' הדבור שבמל' כמ\"ש למען יזמרך כבוד, אל דמי לך כו', הנה עד\"מ באדם התחתון כשמתפלל ברעותא דלבא וגילוי תשוקת הלב שאז הדבורים יוצאים מעומקא דלבא ורשפי אש ודבר היוצא מן הלב נכנס ללב השומע<sup data-n=\"1552\">240</sup> עד שגם הוא מתפעל ג\"כ מזה משא\"כ אם הדבור בקרירות כו', וכמ\"כ יובן למעלה בענין ואני תפלה דבחי' מל' שהוא בחי' חב\"ד ומדות שבמל' עד גם בחי' הדבור שהוא בחי' האותיות כח הפועל שבנפעלים נשמות ומלאכים מאירים בבחי' גילוי אלקות דברים היוצאים מן הלב כו', עד שמאיר בחי' זו גם בנשמות שלמטה שנמשכים מאליהן להתפעל ולהתלהב לבו<sup data-n=\"1553\">241</sup>",[["1542","231","<b>כנ\"ל</b>: פ\"ו."],["1543","230","<b>בהיפך מפי'. . תליא</b>: לשון אוה\"ת שה\"ש תל, ב ואילך (בהוספות)."],["1544","232","<b>התהללו בשם קדשו</b>: (תהלים קה, ג). דהי\"א טז, י (ראה לקמן הערה 248).\nמכאן לשון <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381139\" data-slug=\"likkutei-torah\" data-id=\"4001381139\">לקו\"ת שה\"ש ב, ג</a> (בשינויים והוספות — צויין אליו באוה\"ת הנ\"ל). אוה\"ת נצבים כרך ו ע' ב'תכא. ראה מאמרי אדה\"ז אתהלך לאזניא ע' קלט. אוה\"ת סידור ס\"ע יד ואילך. סה\"מ תרכ\"ז ע' מז. תרל\"ה ח\"א ע' קפד."],["1545","233","<b>והרי</b>: בהמשך הנדפס: והלא. בלקו\"ת כבפנים."],["1546","234","<b>אד' שפתי תפתח</b>: תהלים נא, יז."],["1547","235","<b>דכתי'</b>: בהמשך הנדפס: דהנה כתי'. בלקו\"ת כבפנים."],["1548","236","<b>אלקי' אל דמי לך</b>: תהלים פג, ב."],["1549","237","<b>נהורא תתאה קארי תדיר</b>: ראה זהר היכלות פקודי רנו, ב. תרומה קמ, רע\"א. וישלח קעח, ב. לך עז, ב. פו, ב."],["1550","238","<b>ואני תפלה. . מל'</b>: תהלים קט, ד. ראה זהר תזריע מט, ב. פע\"ח שער התפלה בתחלתו. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תקצב. סה\"מ תרכ\"ז ע' עב."],["1551","239","<b>בנשמות ומלאכים. . העלם כ\"כ</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381139\" data-slug=\"likkutei-torah\" data-id=\"4001381139\">לקו\"ת שה\"ש כאן ב, ג</a>."],["1552","240","<b>ודבר היוצא. . ללב השומע</b>: ספר הישר לר\"ת שי\"ג. הובא בשל\"ה שער האותיות אות כ (סט, א). שירת ישראל לר' משה בן עזרא (ירושלים תשכ\"ז ע' קנו)."],["1553","241","<b>לבו</b>: בהמשך הנדפס: לבן. בלקו\"ת כבפנים."]]],[2000470227,"לה' בלי יגיעה וזהו בחי' אהוי\"ר הנמשכים מלמעלה בחי' עבודת מתנה אתן<sup data-n=\"1554\">242</sup> כו', משא\"כ לפעמים כשאין נמשך בחי' דבור העליון בבחי' גילוי למטה כמ\"ש נאלמתי דומי'<sup data-n=\"1555\">243</sup>, כרחל לפני &lt;12&gt;\nּ גוזזי' נאלמה<sup data-n=\"1556\">244</sup>, וגם מחמת גשמיות וחומריות האדם שאין לו כלי לקבל גילוי זה, והיינו כי כדי לקבל דו\"ר הבאים מלמעלה הוא ע\"י שמעורר תחלה אהוי\"ר בנפשו, וז\"ע אד' שפתי תפתח, בחי' שם אד' שהוא בחי' מל'<sup data-n=\"1557\">245</sup> הוא הפותח שפתי האדם המתפלל, ופי יגיד תהלתיך לשון יגיד הוא המשכה<sup data-n=\"1558\">246</sup> כמשל המושך מים מגבוה לנמוך שהמים הולכים מאליהם, כמ\"כ התהלה והשבח שהנשמה משבחת אינה מצד השגת הנשמה עצמה שהיא המשיכה דבר מה רק התהלה היא תהלתך העצמי' ממדת מל' ופי אינה אלא המגיד וממשיך לבד, והיינו שהפה שבאדם הוא כלי להשראת דבור העליון כו', וז\"ע התהללו בשם קדשו לשון נפעל ולא נא' הללו דהיינו כשיש בחי' גילוי מלמעלה אז אומר לנשמות ומלאכים עליונים שתהלתם ושבחם בהשגות<sup data-n=\"1559\">247</sup> אלקות שלהם באלקים חיים שאין התהלה שלהם שיאמר הללו רק שנמשך להם בחי' תהלה זו מלמעלה ופיהם יגיד תהלתו ית' הנמשך בהם מלמעלה, ולכן אמרו פסוק התהללו כשהביאו את הארון לירושלים<sup data-n=\"1560\">248</sup> שאז ע\"י גילוי אלקות שבארון שהוא בחי' נורא תהלות<sup data-n=\"1561\">249</sup> נורא אותיות ארון כמ\"ש בס' ה\"מ<sup data-n=\"1562\">250</sup> סי' ע\"ז, עי\"ז נמשך בהם גילוי בחי' תהלה להיות התהללו כו'.\n<b></b>קיצור. שהעלי' בנש\"י זהו ע\"י אותיות התורה, וכמ\"ש התהללו בשם קדשו שהל\"ל הללו אלא ע\"י שנמשך גילוי אלקות בבחי' המל' להיות בבחי'<sup data-n=\"1563\">251</sup> תהלה עי\"ז נמשך גם בנשמות להיות התהללו לשון נפעל כו'.\n(ט) <b>ובזהר</b> בראשית דל\"ט ע\"ב פי' ע\"פ הנצנים נראו בארץ<sup data-n=\"1564\">253</sup> עת הזמיר הגיע דהא כדין משבח ומהדר כד\"א למען יזמרך כבוד, ופי' כדין היינו כשמתגלים בו ו\"ק דז\"א שזהו הנצנים נראו בארץ, ובמאו\"א אות נו\"ן סעיף ך\"ה",[["1554","242","<b>עבודת מתנה אתן</b>: קרח יח, ז."],["1555","243","<b>נאלמתי דומי'</b>: תהלים לט, ג."],["1556","244","<b>כרחל לפני גוזזי' נאלמה</b>: ישעי' נג, ז [ושם: וכרחל. ראה גם לקמן ח\"ב (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה עטרת תפארת על יד הערה 102. תו\"ח ויצא קסו, ג הערה 53]."],["1557","245","<b>שם אד'. . מל'</b>: ראה זהר ויקרא יא, א. מאמרי אדה\"א בראשית ע' קצז. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670094\" data-slug=\"torat-chaim\" data-id=\"2300670094\">תו\"ח נח סד, ג</a> הערה 44."],["1558","246","<b>יגיד הוא המשכה</b>: ראה גם בנוסף ל<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381139\" data-slug=\"likkutei-torah\" data-id=\"4001381139\">לקו\"ת שה\"ש כאן (ב, ג</a>). <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381292\" data-slug=\"likkutei-torah\" data-id=\"4001381292\">מא, א</a>. מאמרי אדה\"א נ\"ך ע' שט. וש\"נ. וראה גם סה\"מ תרל\"ח ע' קעו. וש\"נ."],["1559","247","<b>אינה. . היא. . ופי. . בהשגות</b>: בהמשך הנדפס: אינו. . הוא. . ופי'. . בהשגת. בלקו\"ת (כ\"ז) כבפנים."],["1560","248","<b>התהללו כשהביאו את הארון לירושלים</b>: ראה דהי\"א טו, א. ג. כט. טז, א."],["1561","249","<b>נורא תהלות</b>: בשלח טו, יא."],["1562","250","<b>נורא אותיות ארון כמ\"ש בס' ה\"מ </b>[ הדרך מלך]: הועתק גם (עם הגהות מכ\"ק אדמו\"ר הצ\"צ) באוה\"ת יהל אור תהלים ע' קכ (לג, א). ראה גם ע\"ח שער מיעוט הירח של\"ו, פ\"ג."],["1563","251","<b>בבחי'</b>: בהמשך הנדפס ליתא."],["1564","253","<b>הנצנים נראו בארץ</b>: שה\"ש ב, יב."]]],[2000470228,"נצנים נו\"ה<sup data-n=\"1565\">254</sup> דז\"א הנמשכים מצד הבינה ארץ החיים, ובפרד\"ס<sup data-n=\"1566\">255</sup> ערך נצנים<sup data-n=\"1567\">256</sup> שהם חג\"ת כשהם בחו\"ב<sup data-n=\"1568\">257</sup> כו', וא\"כ פי' נראו בארץ היינו כשהמל' מקבלת ממדות דאו\"א עצמן<sup data-n=\"1569\">252</sup>, ויש לפרש זה בשני דרכים, הא' ע\"פ מ\"ש אתהלך לפני הוי' בארצות החיים<sup data-n=\"1570\">259</sup> שיש שני בחי' ארצות שהם בחי' כלים להשראות<sup data-n=\"1571\">260</sup> בחי' חיים העליונים, וכמו חיים ל' רבים כן ארצות לשון רבים<sup data-n=\"1572\">258</sup>, והענין יובן ע\"פ הקדמה למה דוקא נש\"י שנק' בנים למקום<sup data-n=\"1573\">261</sup> גזר עליהם ד\"ג<sup data-n=\"1574\">262</sup> להיות בארץ לא להם, ובמצרים עבדו וענו אותם ד' מאות<sup data-n=\"1575\">264</sup> שנה<sup data-n=\"1576\">263</sup> ועיקר ג' מצרים הי' רד\"ו שנה<sup data-n=\"1577\">265</sup>, ועבודת פרך הי' פ\"ו שנים<sup data-n=\"1578\">266</sup> אשר לא עשה כן לכל גוי<sup data-n=\"1579\">267</sup>, ומדוע לישראל עם קרובו<sup data-n=\"1580\">268</sup> גזרה חכמתו כן דוקא, אלא שבודאי יש בזה יתרון המעלה, וצ\"ל מהו, אך הענין הוא דכל התורה כולה נדרשת בזלעו\"ז, שכמו שהי' פרעה וג' שרי פרעה<sup data-n=\"1581\">269</sup> בלעו\"ז כן יש כל<sup data-n=\"1582\">272</sup> בחי' אלו בקדושה, ובכדי שירשו נש\"י את כל בחי' אלו<sup data-n=\"1583\">273</sup> בקדושה<sup data-n=\"1584\">270</sup> עי\"ז הוכרח להיות גלות מצרים בכדי לברר כל בחי' אלו בכדי שלא יהי' מקום<sup data-n=\"1585\">274</sup> לבע\"ד לחלוק מדוע יגיע לנש\"י כ\"ז, וכמו במ\"ת שהשיב משה גם למלאכים למצרים ירדתם<sup data-n=\"1586\">275</sup> כו', וגם שיגיע כ\"ז ע\"י העבודה שלא כמו נהמא דכסופא<sup data-n=\"1587\">276</sup>. וביאור הענין דכתיב",[["1565","254","<b>נו\"ה</b>: במאו\"א (נעתק לשונו באוה\"ת כאן): ”נק' ה\"ן\". ופי' הצ\"צ: וענין ה\"ן דז\"א היינו נו\"ה דז\"א."],["1566","255","<b>ובפרד\"ס</b>: כ\"ה בכ\"מ — ראה סה\"מ תרל\"ח ע' קט הערה 293."],["1567","256","<b>ובפרד\"ס ערך נצנים</b>: שעה\"כ שכ\"ג, פי\"ד."],["1568","257","<b>כשהם בחו\"ב</b>: בפרדס: בתחלת עלייתם במחשבה."],["1569","252","<b>ובזהר. . עצמן</b>: לשון <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770431\" data-slug=\"or-hatorah-hb\" data-id=\"8316770431\">אוה\"ת שה\"ש ח\"ב ע' תלא</a> בשינויים."],["1570","259","<b>אתהלך לפני ה' בארצות החיים</b>: תהלים קטז, ט. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גדולה מילה על יד הערה 20. ובח\"ב ד\"ה ויאמר כו לך לך על יד הערה 107."],["1571","260","<b>להשראות</b>: בהמשך הנדפס ובתו\"א: להשראת."],["1572","258","<b>אתהלך. . רבים</b>: לשון ה<a class=\"ft-cite\" href=\"#/read/torah-or/3901370125\" data-slug=\"torah-or\" data-id=\"3901370125\">תו\"א וישב כו, ג</a> (בשינויים). ראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קפג."],["1573","261","<b>נש\"י שנק' בנים למקום</b>: פ' ראה יד, א. שמות ד, כב."],["1574","262","<b>ד\"ג</b>: דוקא גלות."],["1575","264","<b>ובמצרים עבדו וענו אותם ד' מאות שנה</b>: כ\"ה גם בהמשך הנדפס."],["1576","263","<b>בארץ לא להם. . מאות שנה</b>: ע\"פ לך טו, יג. וראה גם רש\"י שם שה\"ש ב, יב ושבהערה 265. ראה גם מאמרי אדמו\"ר מהר\"ש דרושי חתונה ע' ז ואילך ובהנסמן שם."],["1577","265","<b>ועיקר ג' מצרים הי' רד\"ו שנה</b>: ראה תנחומא מקץ ח. במדב\"ר פי\"ג, כ. רש\"י מקץ מב, ב לך שם בא יב, מ מגילה ט, א."],["1578","266","<b>ועבודת פרך הי' פ\"ו שנים</b>: ראה תנחומא — באבער — בא ז. מאמרי אדה\"א בראשית ע' רעט. וש\"נ. ראה גם דרושי חתונה הנ\"ל ע' ט."],["1579","267","<b>לא עשה כן לכל גוי</b>: תהלים קמז, כ."],["1580","268","<b>לישראל עם קרובו</b>: ע\"פ תהלים קמח, יד."],["1581","269","<b>וג' שרי פרעה</b>: וישב לז, לו. מ, א ואילך."],["1582","272","<b>כל</b>: בהמשך הנדפס ליתא."],["1583","273","<b>ובכדי. . אלו בקדושה</b>: בהמשך הנדפס ליתא. ואולי נשמט מפני תיבות הדומות: בקדושה. . בקדושה."],["1584","270","<b>וג' שרי פרעה. . בקדושה</b>: ראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680034\" data-slug=\"torat-chaim\" data-id=\"2300680034\">תו\"ח מקץ ריב, ג</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680463\" data-slug=\"torat-chaim\" data-id=\"2300680463\">רכח, ג</a> ואילך. לעיל מאמר ד\"ה כמגדל דוד צוארך על יד הערה 52 ואילך. וש\"נ."],["1585","274","<b>מקום</b>: ניתוסף בפנים ע\"פ המשך הנדפס."],["1586","275","<b>במ\"ת. . למצרים ירדתם</b>: שבת פח, סע\"ב."],["1587","276","<b>נהמא דכסופא</b>: ראה ירושלמי ערלה פ\"א, ה\"ג הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380107\" data-slug=\"likkutei-torah\" data-id=\"4001380107\">לקו\"ת צו ז, רע\"ד</a>. מאמרי אדה\"א קונטרסים ע' תקצה. וש\"נ."]]],[2000470229,"ובקשתם<sup data-n=\"1588\">277</sup> משם את ה' אלקיך ומצאת<sup data-n=\"1589\">278</sup> משם דוקא, וכמ\"ש קראו שם פרעה<sup data-n=\"1590\">279</sup> מלך מצרים, ובעבודה בנפש האדם &lt;13&gt;\nּ מצרים הוא בחי' המצרים וגבולים וג' שרי פרעה הם קנה ושט ורידין<sup data-n=\"1591\">271</sup> שהם במיצר הגרון המונע ומעכב לבוא מבחי' המוח ללב, והיינו הגם שמבין מעט לפי ערכו בגדולת ה' עכ\"ז אינו יכול להוליד מהתבוננות זו אהוי\"ר בהתגלות לבו, והיינו מפני המיצר הגרון המונע ומעכב מבלי יבא ללב כלל, אך ע\"ז נא' ובקשתם משם דהיינו כשיתבונן על ההיפוך מדרכי ה' איך שהוא רחוק בתכלית הריחוק מה' עושהו, כמו עוברי רצונו, וכמו טענת מדה\"ד אלו עובדי כו' ואלו עובדי<sup data-n=\"1592\">280</sup> כו', וכאשר יתבונן מאין נשפע להם שפע וחיות להיות בהם קיום וחיות הנה הוא מרצונו ית' שרצונו ית' הוא המחי' אותם כמ\"ש ואתה מחי' את כולם<sup data-n=\"1593\">281</sup>, אך ע\"ז אמרו כמה ארך אפים לפניו<sup data-n=\"1594\">282</sup>, שמבחי' ארך אפים נמשך ומשתלשל ממדריגות עליונות דרך נפילה להחיותם אף שהם עוברי רצונו, וכשיתבונן אם לעוברי רצונו כך<sup data-n=\"1595\">283</sup> לעושי רצונו עאכו\"כ שיושפע בחי' רצון העליון שהוא למעלה מעלה מגדר עלמין שלא בבחי' ירידת והשתלשלות המדרגות בבחי' חכ' ומדות אלא בבחי' פנימי' נקודת הלב שהוא בחי' תשובה עילאה שקדמה לעולם<sup data-n=\"1596\">284</sup>, וזהו כי תדרשנו בכל לבבך ובכל נפשך<sup data-n=\"1597\">285</sup> דהיינו שיהפך לבו מן הקצה אל הקצה ואתהפכא חשוכא לנהורא<sup data-n=\"1598\">286</sup> ע\"י בחי' רעו\"ד<sup data-n=\"1599\">287</sup> זו למאוס בחיי עוה\"ז ותענוגים<sup data-n=\"1600\">288</sup> ולמשוך לבו ונפשו לדבקה בו ית', ונודע כי תשו\"ע ורעו\"ד<sup data-n=\"1601\">290</sup> הוא בבחי' הבינה<sup data-n=\"1602\">289</sup>, וזהו אתהלך לפני ה' בארצות החיים שנש\"י בעצם שרשם מבחי' המל' כנס\"י דלעילא בחי' ארץ תתאה, וע\"י העבודה ע\"י ההתבוננות משם דוקא באים לבחי' תשו\"ע ורעו\"ד שהוא בחי' ארץ עילאה שיאיר אור האהוי\"ר ג\"כ מבחי' ארץ עילאה, וז\"ע הנצנים נראו בארץ שבארץ תתאה נראה בחי' מדות עליונות שהוא בחי' אהוי\"ר, אלא שבזהר",[["1588","277","<b>ובקשתם. . בו ית'</b>: לשון <a class=\"ft-cite\" href=\"#/read/torah-or/3901370127\" data-slug=\"torah-or\" data-id=\"3901370127\">תו\"א וישב כז, א</a> בהוספות ובשינויים."],["1589","278","<b>ובקשתם משם. . ומצאת</b>: ואתחנן ד, כט."],["1590","279","<b>קראו שם פרעה</b>: ירמי' מו, יז. ראה גם לקו\"ת חוקת נו, ד. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרעו."],["1591","271","<b>וג' שרי פרעה. . קנה ושט ורידין</b>: ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370453\" data-slug=\"torah-or\" data-id=\"3901370453\">תו\"א ויחי קב, ג</a>. מאמרי אדה\"ז תקס\"ג ח\"א ע' פא. מאמרי אדה\"א בראשית ע' תעא ואילך. סה\"מ תרל\"ד ע' קסד ואילך. לקמן ח\"ב (בחלק המאמרים) המשך יונתי על יד הערה 667. (בחלק ההנחות) הנחה ד\"ה שובה ישראל הא' על יד הערה 150."],["1592","280","<b>אלו עובדי כו' ואלו עובדי</b>: ראה זהר תרומה קע, ב. יל\"ר בשלח יד, כח. סה\"מ תרל\"ב ח\"א ע' רפז ואילך."],["1593","281","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו. ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה ובהערה 66."],["1594","282","<b>כמה ארך אפים לפניו</b>: אבות פ\"ה, מ\"ב. ראה גם מאמרי אדה\"ז תקס\"ב ח\"א ע' קמו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300540247\" data-slug=\"torat-chaim\" data-id=\"2300540247\">תו\"ח בשלח ח\"א קלד, ד</a> ואילך."],["1595","283","<b>אם לעוברי רצונו כך</b>: ראה מכות בסופה. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380445\" data-slug=\"likkutei-torah\" data-id=\"4001380445\">לקו\"ת בהעלותך לג, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380500\" data-slug=\"likkutei-torah\" data-id=\"4001380500\">שלח מז, א</a>."],["1596","284","<b>תשובה. . שקדמה לעולם</b>: פסחים נד, א. ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקצז. וש\"נ. שע\"ת ג, א."],["1597","285","<b>כי תדרשנו. . נפשך</b>: המשך הכתוב ובקשתם משם — ואתחנן ד, כט."],["1598","286","<b>ואתהפכא חשוכא לנהורא</b>: ראה זהר בהקדמה ד, א. סה\"מ תרכ\"ט ע' פח ואילך. וש\"נ. מאמר ד\"ה זאת חוקת התורה ש\"פ פרה תשכ\"ו."],["1599","287","<b>רעו\"ד</b>: זהר וירא ק, א."],["1600","288","<b>ותענוגים</b>: בהמשך הנדפס: ותענוגיו. ובתו\"א כבפנים."],["1601","290","<b>ורעו\"ד. . הבינה</b>: ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט</a>. לקו\"ת שה\"ש נא, ג."],["1602","289","<b>תשו\"ע. . בבחי' הבינה</b>: ראה אגה\"ת פ\"ח ופ\"ט ובליקוט פירושים לשם."]]],[2000470230,"אומר בכלל שנראו נו\"ה כו', והרי אות על בחי' יצ\"מ שיצאו ממיצר הגרון, ואומרו על נו\"ה לפי שהם בחי' ההשפעה שבמדות וגם שלא כאו\"א יכול לבוא לגילוי בחי' אהוי\"ר, כ\"א בבחי' נצח או הודאה כו', והמאו\"א מפרש יותר ואומר שנו\"ה דז\"א זהו נמשכי' מהבינה ארץ החיים וכנ\"ל שבא ע\"י בחי' רעו\"ד כו', והפרד\"ס מבאר עוד יותר ואינו חושב הפעולה כ\"א הפועל ואומר שזהו חג\"ת שכשהם בחו\"ב שז\"ע ארץ החיים ארץ הוא בחי' בינה<sup data-n=\"1603\">291</sup> ארץ עילאה וחיים הוא בחי' חכ' כמ\"ש והחכ' תחי'<sup data-n=\"1604\">292</sup>, ולפי שחו\"ב הם תרדל\"מ<sup data-n=\"1605\">293</sup> לכן אמר כשהם בחו\"ב, וגם י\"ל כי רעו\"ד ז\"ע שעה\"נ דבינה שמחבר חו\"ב<sup data-n=\"1606\">294</sup>, וע' בעה\"מ שער שעשועי המלך בעצמותו<sup data-n=\"1607\">295</sup>, שמפרש נתיב לא ידעו עיט<sup data-n=\"1608\">296</sup> זהו שעה\"נ דבינה שמשה לא השיגו בחייו, וזהו הא\"ב דא\"ל ב\"ם<sup data-n=\"1609\">297</sup> שהוא תוך הרל\"א שערים<sup data-n=\"1610\">298</sup>, ונתיב בגימט' ב\"פ רל\"א<sup data-n=\"1611\">299</sup>, והיינו רל\"א שערים פנים ואחור, וא\"כ זהו מאותיות שברשימו היותר נעלים ע\"ש בעה\"מ, אשר ע\"י אותיות אלו מתגלה מבחי' אוא\"ס בחי' התוס' אור מלפני הצמצום בבחי' היותר נעלה כו'.\n&lt;14&gt;\nּ <b>קיצור.</b> הנצנים נו\"ה נראו במל' שנק' ארץ, והיינו שהמל' מקבלת ממדות דאו\"א, ויתפרש ע\"ד ארצות החיים שזהו דוקא ע\"י משם עי\"ז בא לרעו\"ד שהיא בינה, ושיווי ג' פי' שבזהר ובמאו\"א ובפרד\"ס, וזהו ענין נתיב לא ידעו עיט כמ\"ש בעה\"מ שער שעה\"מ.\n(יו\"ד) <b>והדרך</b> הב' יובן עפמ\"ש שער<sup data-n=\"1612\">300</sup> החצר הפנימית<sup data-n=\"1613\">301</sup> הפונה קדים סגור יהי' ששת ימי המעשה כו' וביום החדש יפתח שיום החדש אינו מכלל ששת ימי המעשה להיות סגור בו שער הפונה קדים, והענין יובן עד\"מ מבשרי אחזה<sup data-n=\"1614\">302</sup>",[["1603","291","<b>ארץ. . בינה</b>: ראה לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ויאמר כו' לך לך על יד הערה 82 ואילך. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300680343\" data-slug=\"torat-chaim\" data-id=\"2300680343\">תו\"ח וישב רג, ד</a> ובהנסמן במ\"מ לשם. אוה\"ת אוה\"ת לך כרך ד ע' 1450 ואילך. בלק ע' תתקמד. מאמרי אדמו\"ר הצ\"צ הנחות תרי\"ד ס\"ע ג ואילך. (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה גדולה מילה."],["1604","292","<b>והחכ' תחי'</b>: קהלת ז, יב [ושם: החכמה — ראה גם לקמן ח\"ב (בחלק המאמרים) מאמר ד\"ה ולהבין שרש ענין בחי' מזבח הפנימי על יד הערה 149. (בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה יונתי בחגוי הסלע על יד הערה 88. (בחלק ההנחות) הנחה ד\"ה שובה ישראל הב' על יד הערה 96. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת פ' ראה כה, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381192\" data-slug=\"likkutei-torah\" data-id=\"4001381192\">שה\"ש טו, ד</a> הובא לקמן פכ\"ח. פרק ג\"ל. מאמרי אדה\"ז תק\"ע ע' קכז. מאמרי אדה\"א דברים ח\"א ע' ש. וש\"נ. סה\"מ תרל\"ח ע' נג. וש\"נ]."],["1605","293","<b>שחו\"ב הם תרדל\"מ</b>: ראה זהר בשלח נו, א. ויקרא ד, א. מאמרי אדה\"א דברים ח\"ב ע' שסו. וש\"נ. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670185\" data-slug=\"torat-chaim\" data-id=\"2300670185\">תו\"ח בראשית כא, ב</a> ובהערה 8."],["1606","294","<b>שעה\"נ דבינה שמחבר חו\"ב</b>: ראה גם (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה מזבח אדמה על יד הערה 86. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380356\" data-slug=\"likkutei-torah\" data-id=\"4001380356\">לקו\"ת במדבר יב, א</a> ואילך. אמרי בינה שער הק\"ש פ\"ס. סה\"מ תרמ\"ז ע' צא. המשך תער\"ב ח\"ב ע' א'ר."],["1607","295","<b>בעה\"מ שער שעשועי המלך בעצמותו</b>: פ\"ד ופנ\"ב."],["1608","296","<b>נתיב לא ידעו עיט</b>: איוב כח, ז."],["1609","297","<b>הא\"ב דא\"ל ב\"ם</b>: שבת קד, סע\"א."],["1610","298","<b>הרל\"א שערים</b>: ראה ס\"י פ\"ב, מ\"ד-ה ובמפרשיו. פי' הראב\"ד שם [מב, ד]. פרדס שער הצרוף ש\"ל, פ\"ה. עמה\"מ שם פ\"ה,"],["1611","299","<b>ונתיב בגימט' ב\"פ רל\"א</b>: עמה\"מ שבהערה 295. מאו\"א מערכת נתיב אות מב."],["1612","300","<b>שער. . השבת</b>: לשון <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381116\" data-slug=\"likkutei-torah\" data-id=\"4001381116\">לקו\"ת ברכה צז, ב</a> ואילך (בשינויים — צויין אליו ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770431\" data-slug=\"or-hatorah-hb\" data-id=\"8316770431\">אוה\"ת שה\"ש ע' תלא</a>)."],["1613","301","<b>שער החצר הפנימית</b>: יחזקאל מו, א."],["1614","302","<b>מבשרי אחזה</b>: איוב יט, כו."]]],[2000470231,"שהדבור הוא מקבל מב' בחי' שלפעמים מקבל מבחי' המדות שלפי שאוהב הדבר ההיא מדבר בו, או להיפך מפני שכועס כו', ולפעמים הדבור מקבל מבחי' ההשגה והבנה שמדבר מה שמשכיל בשכלו ומבין ברוח בינתו, כך עד\"מ יובן למשכיל למעלה שהגם שלא מחשבותי מחשבותיכם<sup data-n=\"1615\">303</sup>, אעפ\"כ נא' למעלה לשון דבור, ובחי' דבר ה'<sup data-n=\"1616\">304</sup> הוא בחי' עלמא דאתגלי' והוא מקור בחי' כנס\"י, ולפעמים אשר כנס\"י מקבלת בחי' זו מבחי' המדות דהיינו בחי' אהבה מוסתרת בכל ששת ימי החול אחר התפלה להיות סומ\"ר ועש\"ט בקש שלום<sup data-n=\"1617\">305</sup> מחמת אהבה הטבעית המוסתרת בלב כל אדם, ופי' בקש שלום להיות התקשרות שני הפכים שכל מה שלמעלה מעלה הוא אין וכל מה שלמטה מטה הוא בחי' יש, משא\"כ בראש חדש היא מקבלת מבחי' השכל והבנה שאז הוא שעת הכושר למעלה להמשיך לו השגה והבנה בהתחדשות מעשה בראשית מאין ליש ולהיות האהבה בבחי' ביטול וכמ\"ש ודברי אשר שמתי בפיך<sup data-n=\"1618\">306</sup> דברי ממש, ובחי' זו נק' שער החצר הפנימית הפונה קדים היינו מקדם למע\"ב, כי מע\"ב היינו בחי' החכ' כמו שמתלבשת במדות<sup data-n=\"1619\">307</sup>, משא\"כ בר\"ח מקבל הדבור מבחי' החכ' עצמה, ואינו דומה בחי' החכ'<sup data-n=\"1620\">308</sup> המלובשת במדות שהיא<sup data-n=\"1621\">309</sup> בתוכם בהעלם לבחי' גילוי החכמה עצמה שהיא רמה ונשגבה למעלה מעלה כמ\"ש מזה במ\"א בד\"ה באתי לגני<sup data-n=\"1622\">310</sup>, והו\"ע מחדש חדשים מקור ההתחדשות וכנס\"י מתעלה בבחי' זו שביום החדש יפתח כמו ביום השבת שהוא בחי' מוחין דאבא<sup data-n=\"1623\">311</sup> כנודע, ועפ\"ז יובן ענין הנצנים נראו בארץ שהארץ מקבלת מבחי' חכ', והיינו מבחי' המדות כמ\"ש באו\"א, כמ\"ש הפרד\"ס, ובמאו\"א כולל דבר זה בתיבת אה\"ח<sup data-n=\"1624\">312</sup> כנ\"ל<sup data-n=\"1625\">313</sup>, ושניהם ע\"פ הזהר<sup data-n=\"1626\">314</sup> שכדין משבח ומהדר שצ\"ל שבחי' שמתגלי' ו\"ק דז\"א אינו בכל העתים שמקבלת מז\"א אלא מבחי' ו\"ק דז\"א כו'<sup data-n=\"1627\">315</sup> כמו שהם באו\"א כו'.\n<b></b>קיצור. שיש ב' בחי' במל' לפעמים מקבלת מהמדות ולפעמים מחו\"ב עצמם, כמו בר\"ח שהשער הפונה קדים יפתח בו, ועד\"ז הו\"ע הנצנים נראו בארץ כו', ועפ\"ז יובן &lt;15&gt;\nּ איך שע\"י קרי\"ס נתעורר למעלה בחי' שירה הזאת עי\"ז נעשה להיות ישיר משה ובנ\"י כו'<sup data-n=\"1628\">316</sup> ",[["1615","303","<b>שלא מחשבותי מחשבותיכם</b>: ישעי' נה, ח."],["1616","304","<b>ובחי' דבר ה'</b>: בהמשך הנדפס: ובחי' דבור. בלקו\"ת: ודבר הוי'. עיי\"ש."],["1617","305","<b>סומ\"ר. . שלום</b>: תהלים לד, טו."],["1618","306","<b>ודברי אשר שמתי בפיך</b>: ישעי' נט, כא. ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380338\" data-slug=\"likkutei-torah\" data-id=\"4001380338\">לקו\"ת במדבר ז, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370301\" data-slug=\"torah-or\" data-id=\"3901370301\">תו\"א יתרו סז, ב</a> (צויין בלקו\"ת כאן)."],["1619","307","<b>כי מע\"ב. . החכ'. . במדות</b>: בלקו\"ת כאן: כמש\"ל [צו, ד] בפי' ימי בראשית."],["1620","308","<b>החכ'</b>: בהמשך הנדפס: החו\"ב. בלקו\"ת כאן כבפנים."],["1621","309","<b>שהיא</b>: בהמשך הנדפס: שהוא. בלקו\"ת כבפנים."],["1622","310","<b>כמ\"ש בד\"ה באתי לגני</b>: <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381257\" data-slug=\"likkutei-torah\" data-id=\"4001381257\">לקו\"ת שה\"ש לב, א</a>."],["1623","311","<b>השבת. . מוחין דאבא</b>: ראה (לקמן בחלק הנחות כ\"ק אדמו\"ר מהורש\"ב) הנחה ד\"ה ואתה תצוה הערה 84."],["1624","312","<b>אה\"ח</b>: ארץ החיים."],["1625","313","<b>כנ\"ל</b>: בפרק שלפנ\"ז."],["1626","314","<b>הזהר</b>: לעיל רפ\"ט."],["1627","315","<b>כו'</b>: בהמשך הנדפס ליתא."],["1628","316","<b>ועפ\"ז יובן. . כו'</b>: כ\"ז לא נמצא בפנים. ראה לעיל רפ\"ח."]]]]});
